func copyCollectionFormatFiles(sourcePath, targetPath, format string) error {
	ext := ".bru"
	rootConfigName := "bruno.json"
	if strings.EqualFold(format, "yml") || strings.EqualFold(format, "yaml") || fileExists(filepath.Join(sourcePath, "opencollection.yml")) {
		ext = ".yml"
		rootConfigName = "opencollection.yml"
	}
	return filepath.WalkDir(sourcePath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if path != sourcePath && pathInside(targetPath, path) {
			if entry.IsDir() {
				return filepath.SkipDir
			}
			return nil
		}
		if entry.IsDir() {
			return nil
		}
		if strings.ToLower(filepath.Ext(path)) != ext {
			return nil
		}
		if filepath.Dir(path) == sourcePath && filepath.Base(path) == rootConfigName {
			return nil
		}
		rel, err := filepath.Rel(sourcePath, path)
		if err != nil {
			return err
		}
		return copyCollectionFile(path, filepath.Join(targetPath, rel))
	})
}

func copyCollectionFile(sourcePath, targetPath string) (err error) {
	info, statErr := os.Stat(sourcePath)
	if statErr != nil {
		return statErr
	}
	if !info.Mode().IsRegular() {
		return nil
	}
	if err := os.MkdirAll(filepath.Dir(targetPath), 0o755); err != nil {
		return err
	}
	source, err := os.Open(sourcePath)
	if err != nil {
		return err
	}
	// Read-only handle: a failed close cannot lose data.
	defer func() { _ = source.Close() }()
	target, err := os.OpenFile(targetPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, info.Mode().Perm())
	if err != nil {
		return err
	}
	// The write handle's close error must surface: it is where a deferred
	// write failure (ENOSPC, EDQUOT, a failing network filesystem) is reported,
	// and dropping it would report a truncated collection copy as a success.
	defer func() {
		if closeErr := target.Close(); closeErr != nil && err == nil {
			err = closeErr
		}
	}()
	_, err = io.Copy(target, source)
	return err
}

func (a *App) writeFolderConfigLocked(collection *Collection, folder FolderConfig) error {
	if strings.TrimSpace(collection.Path) == "" {
		return errors.New("collection path is empty")
	}
	folderPath := normalizeFolderPathKey(folder.Path)
	if folderPath == "" {
		return errors.New("folder path is required")
	}
	if strings.HasPrefix(folderPath, "../") || folderPath == ".." || filepath.IsAbs(folderPath) {
		return fmt.Errorf("invalid folder path %s", folder.Path)
	}
	targetDir := filepath.Join(collection.Path, filepath.FromSlash(folderPath))
	if !pathInside(collection.Path, targetDir) {
		return fmt.Errorf("folder path %s escapes collection", folder.Path)
	}
	if err := os.MkdirAll(targetDir, 0o755); err != nil {
		return err
	}
	target := folderMetadataWritePath(*collection, targetDir)
	var content string
	if collection.Format == "yml" {
		content = stringifyYAMLFolder(folder)
	} else {
		content = stringifyBruFolder(folder)
	}
	if err := os.WriteFile(target, []byte(content), 0o600); err != nil {
		return err
	}
	a.seedCollectionWatchFingerprintLocked(collection.Path)
	return nil
}

func folderMetadataWritePath(collection Collection, targetDir string) string {
	if collection.Format == "yml" {
		for _, name := range []string{"folder.yml", "folder.yaml"} {
			path := filepath.Join(targetDir, name)
			if _, err := os.Stat(path); err == nil {
				return path
			}
		}
		return filepath.Join(targetDir, "folder.yml")
	}
	return filepath.Join(targetDir, "folder.bru")
}

func (a *App) writeWorkspaceGlobalEnvironmentFilesLocked(workspace *Workspace) error {
	if workspace == nil || strings.TrimSpace(workspace.Path) == "" {
		return nil
	}
	envPath := filepath.Join(workspace.Path, "environments")
	if err := os.MkdirAll(envPath, 0o755); err != nil {
		return err
	}
	entries, err := os.ReadDir(envPath)
	if err == nil {
		for _, entry := range entries {
			if entry.IsDir() {
				continue
			}
			ext := strings.ToLower(filepath.Ext(entry.Name()))
			if ext == ".yml" || ext == ".yaml" {
				if err := os.Remove(filepath.Join(envPath, entry.Name())); err != nil && !errors.Is(err, os.ErrNotExist) {
					return err
				}
			}
		}
	}
	for _, env := range workspace.GlobalEnvironments {
		filename := sanitizeFilename(env.Name)
		if filename == "" {
			filename = env.ID
		}
		if err := os.WriteFile(filepath.Join(envPath, filename+".yml"), []byte(stringifyYAMLEnvironment(env)), 0o600); err != nil {
			return err
		}
	}
	return nil
}

func requestFilePath(collection Collection, item RequestItem, defaultExt string) string {
	if pathInside(collection.Path, item.FilePath) {
		return filepath.Clean(item.FilePath)
	}
	filename := sanitizeFilename(item.Name)
	if filename == "" {
		filename = item.ID
	}
	folder := filepath.Clean(collection.Path)
	if strings.TrimSpace(item.FolderPath) != "" {
		folder = filepath.Join(folder, filepath.FromSlash(item.FolderPath))
	}
	return filepath.Join(folder, filename+defaultExt)
}

func collectionFolderFilesystemPath(collection *Collection, folderPath string) (string, error) {
	if collection == nil {
		return "", errors.New("collection is required")
	}
	if strings.TrimSpace(collection.Path) == "" {
		return "", errors.New("collection path is empty")
	}
	folder, err := findFolderConfig(collection, folderPath)
	if err != nil {
		return "", err
	}
	physicalPath := normalizeFolderPathKey(firstNonEmpty(folder.Path, folder.DisplayPath, folder.Name))
	if physicalPath == "" {
		return "", errors.New("folder path is required")
	}
	targetPath := filepath.Clean(filepath.Join(collection.Path, filepath.FromSlash(physicalPath)))
	if !pathInside(collection.Path, targetPath) {
		return "", fmt.Errorf("folder path %s escapes collection", physicalPath)
	}
	return targetPath, nil
}

func collectionRequestFilesystemPath(collection *Collection, item RequestItem) (string, error) {
	if collection == nil {
		return "", errors.New("collection is required")
	}
	if strings.TrimSpace(collection.Path) == "" {
		return "", errors.New("collection path is empty")
	}
	if pathInside(collection.Path, item.FilePath) {
		return filepath.Clean(item.FilePath), nil
	}
	filename := sanitizeFilename(item.Name)
	if filename == "" {
		filename = item.ID
	}
	folder := filepath.Clean(collection.Path)
	if folderPath := normalizeFolderPathKey(item.FolderPath); folderPath != "" {
		if folderConfig, err := findFolderConfig(collection, folderPath); err == nil {
			folderPath = normalizeFolderPathKey(firstNonEmpty(folderConfig.Path, folderConfig.DisplayPath, folderConfig.Name))
		}
		folder = filepath.Join(collection.Path, filepath.FromSlash(folderPath))
	}
	targetPath := filepath.Clean(filepath.Join(folder, filename+requestFileExtensionForCollection(*collection)))
	if !pathInside(collection.Path, targetPath) {
		return "", fmt.Errorf("request path %s escapes collection", targetPath)
	}
	return targetPath, nil
}

func ensureRequestFilePaths(collection *Collection, defaultExt string) {
	used := map[string]bool{}
	for i := range collection.Items {
		target := ""
		if pathInside(collection.Path, collection.Items[i].FilePath) {
			target = filepath.Clean(collection.Items[i].FilePath)
			if used[target] {
				target = ""
			}
		}
		if target == "" {
			target = uniqueRequestFilePath(*collection, collection.Items[i], defaultExt, used)
		}
		collection.Items[i].FilePath = target
		used[target] = true
	}
}

func uniqueRequestFilePath(collection Collection, item RequestItem, defaultExt string, used map[string]bool) string {
	filename := sanitizeFilename(item.Name)
	if filename == "" {
		filename = item.ID
	}
	folder := filepath.Clean(collection.Path)
	if strings.TrimSpace(item.FolderPath) != "" {
		folder = filepath.Join(folder, filepath.FromSlash(item.FolderPath))
	}
	for index := 0; ; index++ {
		candidateName := filename
		if index > 0 {
			candidateName = fmt.Sprintf("%s %d", filename, index+1)
		}
		candidate := filepath.Clean(filepath.Join(folder, candidateName+defaultExt))
		if !used[candidate] {
			return candidate
		}
	}
}

func requestFileExtensionForCollection(collection Collection) string {
	if strings.EqualFold(collection.Format, "yml") || strings.EqualFold(collection.Format, "yaml") {
		return ".yml"
	}
	return ".bru"
}

func pathInside(root, candidate string) bool {
	if strings.TrimSpace(root) == "" || strings.TrimSpace(candidate) == "" {
		return false
	}
	rel, err := filepath.Rel(filepath.Clean(root), filepath.Clean(candidate))
	if err != nil {
		return false
	}
	return rel == "." || (!strings.HasPrefix(rel, ".."+string(filepath.Separator)) && rel != ".." && !filepath.IsAbs(rel))
}

func normalizeGitRemoteURL(raw string) (string, error) {
	remote := strings.TrimSpace(raw)
	if remote == "" {
		return "", errors.New("git remote URL is required")
	}
	if strings.ContainsAny(remote, "\r\n\t ") {
		return "", errors.New("git remote URL cannot contain whitespace")
	}
	if strings.Contains(remote, "://") {
		parsed, err := url.Parse(remote)
		if err != nil {
			return "", fmt.Errorf("invalid Git remote URL: %w", err)
		}
		switch parsed.Scheme {
		case "https", "http", "ssh", "git":
			if parsed.Host == "" || parsed.Path == "" || parsed.Path == "/" {
				return "", errors.New("git remote URL must include host and repository path")
			}
		case "file":
			if parsed.Path == "" || parsed.Path == "/" {
				return "", errors.New("file Git remote URL must include a repository path")
			}
		default:
			return "", fmt.Errorf("unsupported Git remote URL scheme %q", parsed.Scheme)
		}
		if parsed.User != nil {
			return "", errors.New("git remote URL must not embed credentials")
		}
		return remote, nil
	}
	if strings.HasPrefix(remote, "/") || strings.HasPrefix(remote, "./") || strings.HasPrefix(remote, "../") {
		return "", errors.New("local Git remotes must use file:// URLs")
	}
	colon := strings.Index(remote, ":")
	if colon <= 0 || colon == len(remote)-1 {
		return "", errors.New("git remote URL must be https://, ssh://, file://, or git@host:path")
	}
	userHost := remote[:colon]
	repoPath := remote[colon+1:]
	at := strings.Index(userHost, "@")
	if at <= 0 || at == len(userHost)-1 || strings.Contains(repoPath, ":") || strings.HasPrefix(repoPath, "/") {
		return "", errors.New("git remote URL must be https://, ssh://, file://, or git@host:path")
	}
	return remote, nil
}

func gitVersion() (string, error) {
	if _, err := exec.LookPath("git"); err != nil {
		return "", errors.New("git is not installed or not on PATH")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	output, err := exec.CommandContext(ctx, "git", "--version").CombinedOutput()
	if err != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return "", errors.New("git --version timed out")
		}
		return "", fmt.Errorf("git --version failed: %s", strings.TrimSpace(string(output)))
	}
	return strings.TrimSpace(string(output)), nil
}

func (a *App) emitGitCloneProgress(stage, message, targetPath string) {
	if a == nil || a.ctx == nil {
		return
	}
	message = strings.TrimSpace(message)
	if message == "" {
		return
	}
	wailsruntime.EventsEmit(a.ctx, "git:clone:progress", GitCloneProgress{
		Stage:      stage,
		Message:    message,
		TargetPath: targetPath,
		At:         time.Now().Format(time.RFC3339Nano),
	})
}

func scanGitProgressToken(data []byte, atEOF bool) (advance int, token []byte, err error) {
	for index, b := range data {
		if b == '\n' || b == '\r' {
			return index + 1, bytes.TrimSpace(data[:index]), nil
		}
	}
	if atEOF && len(data) > 0 {
		return len(data), bytes.TrimSpace(data), nil
	}
	return 0, nil, nil
}

func deriveGitRepoName(remote string) string {
	remote = strings.TrimSpace(remote)
	if parsed, err := url.Parse(remote); err == nil && parsed.Scheme != "" {
		base := strings.TrimSuffix(pathBase(parsed.Path), ".git")
		return sanitizeFilename(base)
	}
	if colon := strings.LastIndex(remote, ":"); colon >= 0 && colon < len(remote)-1 {
		return sanitizeFilename(strings.TrimSuffix(pathBase(remote[colon+1:]), ".git"))
	}
	return sanitizeFilename(strings.TrimSuffix(pathBase(remote), ".git"))
}

func pathBase(value string) string {
	value = strings.TrimRight(strings.TrimSpace(value), "/")
	if value == "" {
		return ""
	}
	index := strings.LastIndex(value, "/")
	if index >= 0 {
		return value[index+1:]
	}
	return value
}

func scanBrunoCollections(rootPath string) ([]GitCollectionCandidate, error) {
	rootPath = strings.TrimSpace(rootPath)
	if rootPath == "" {
		return nil, errors.New("scan path is required")
	}
	info, err := os.Stat(rootPath)
	if err != nil {
		return nil, err
	}
	if !info.IsDir() {
		return nil, fmt.Errorf("%s is not a directory", rootPath)
	}
	rootPath = filepath.Clean(rootPath)
	candidates := []GitCollectionCandidate{}
	err = filepath.WalkDir(rootPath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if !entry.IsDir() {
			return nil
		}
		base := entry.Name()
		if path != rootPath && (base == ".git" || base == "node_modules" || base == "environments") {
			return filepath.SkipDir
		}
		if !looksLikeCollectionDir(path) {
			return nil
		}
		collection, err := readCollectionFromDisk(path)
		if err != nil {
			return err
		}
		candidates = append(candidates, GitCollectionCandidate{
			Name:         collection.Name,
			Path:         filepath.Clean(path),
			Format:       collection.Format,
			RequestCount: len(collection.Items),
		})
		if path != rootPath {
			return filepath.SkipDir
		}
		return nil
	})
	if err != nil {
		return nil, err
	}
	sort.SliceStable(candidates, func(i, j int) bool {
		return strings.ToLower(candidates[i].Path) < strings.ToLower(candidates[j].Path)
	})
	return candidates, nil
}

func looksLikeCollectionDir(path string) bool {
	for _, name := range []string{"bruno.json", "opencollection.yml", "opencollection.yaml"} {
		if info, err := os.Stat(filepath.Join(path, name)); err == nil && !info.IsDir() {
			return true
		}
	}
	return false
}

func updateManagedGitIgnore(workspacePath, collectionPath string, add bool) error {
	return updateManagedGitIgnoreSecure(workspacePath, collectionPath, add)
}

func managedGitIgnoreEntries(content string) map[string]bool {
	entries := map[string]bool{}
	inBlock := false
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		switch trimmed {
		case "# LiteAPI managed Git-backed collections":
			inBlock = true
			continue
		case "# End LiteAPI managed Git-backed collections":
			inBlock = false
			continue
		}
		if inBlock && trimmed != "" && !strings.HasPrefix(trimmed, "#") {
			entries[trimmed] = true
		}
	}
	return entries
}

func replaceManagedGitIgnoreBlock(content string, entries map[string]bool) string {
	lines := strings.Split(strings.ReplaceAll(content, "\r\n", "\n"), "\n")
	kept := make([]string, 0, len(lines))
	inBlock := false
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "# LiteAPI managed Git-backed collections" {
			inBlock = true
			continue
		}
		if trimmed == "# End LiteAPI managed Git-backed collections" {
			inBlock = false
			continue
		}
		if !inBlock {
			kept = append(kept, line)
		}
	}
	for len(kept) > 0 && strings.TrimSpace(kept[len(kept)-1]) == "" {
		kept = kept[:len(kept)-1]
	}
	keys := make([]string, 0, len(entries))
	for entry := range entries {
		keys = append(keys, entry)
	}
	sort.Strings(keys)
	if len(keys) > 0 {
		if len(kept) > 0 {
			kept = append(kept, "")
		}
		kept = append(kept, "# LiteAPI managed Git-backed collections")
		kept = append(kept, keys...)
		kept = append(kept, "# End LiteAPI managed Git-backed collections")
	}
	if len(kept) == 0 {
		return ""
	}
	return strings.Join(kept, "\n") + "\n"
}

func collectionFromImport(payload ImportPayload) (Collection, error) {
	now := time.Now()
	name := strings.TrimSpace(payload.Name)
	if name == "" {
		name = "Imported Collection"
	}
	collection := Collection{
		ID:             newID("collection"),
		Name:           name,
		Format:         "json",
		Auth:           AuthConfig{Mode: "none"},
		SecurityConfig: CollectionSecurityConfig{JSSandboxMode: "safe"},
		CreatedAt:      now,
		UpdatedAt:      now,
	}
	kind := strings.ToLower(payload.Kind)
	switch kind {
	case "bruno-json", "json", "bruno":
		var imported Collection
		if err := json.Unmarshal([]byte(payload.Content), &imported); err != nil {
			return Collection{}, err
		}
		imported.ID = collection.ID
		if imported.Name == "" {
			imported.Name = name
		}
		imported.SecurityConfig = normalizeCollectionSecurityConfig(imported.SecurityConfig)
		imported.CreatedAt = now
		imported.UpdatedAt = now
		return imported, nil
	case "bru":
		item, err := parseBru(payload.Content)
		if err != nil {
			return Collection{}, err
		}
		collection.Items = []RequestItem{item}
		return collection, nil
	case "postman":
		return importPostman(payload.Content, name)
	case "insomnia":
		return importInsomnia(payload.Content, name)
	case "openapi":
		return importOpenAPI(payload.Content, name, payload.GroupBy)
	case "curl":
		collection, _, err := collectionFromCurlImport(payload.Content, name)
		return collection, err
	default:
		return Collection{}, fmt.Errorf("unsupported import kind %q", payload.Kind)
	}
}

func (a *App) openAPISyncInputs(collectionID string, options OpenAPISyncOptions) (Collection, string, string, string, error) {
	a.mu.Lock()
	if err := a.ensureReadyLocked(); err != nil {
		a.mu.Unlock()
		return Collection{}, "", "", "", err
	}
	collection, err := a.findCollectionLocked(collectionID)
	if err != nil {
		a.mu.Unlock()
		return Collection{}, "", "", "", err
	}
	collectionCopy := *collection
	defaultConfig := firstOpenAPISyncConfig(collectionCopy)
	sourceURL := strings.TrimSpace(options.SourceURL)
	if sourceURL == "" {
		sourceURL = defaultConfig.SourceURL
	}
	groupBy := strings.TrimSpace(options.GroupBy)
	if groupBy == "" {
		groupBy = defaultConfig.GroupBy
	}
	groupBy = normalizeOpenAPISyncGroupBy(groupBy)
	content := options.Content
	client := a.httpClient
	a.mu.Unlock()
	if strings.TrimSpace(content) == "" {
		fetched, err := fetchOpenAPISyncContent(collectionCopy.Path, sourceURL, client)
		if err != nil {
			return Collection{}, "", "", "", err
		}
		content = fetched
	}
	return collectionCopy, content, sourceURL, groupBy, nil
}

func (a *App) openAPILocalDriftInputs(collectionID string) (Collection, string, OpenAPISyncConfig, bool, error) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if err := a.ensureReadyLocked(); err != nil {
		return Collection{}, "", OpenAPISyncConfig{}, false, err
	}
	collection, err := a.findCollectionLocked(collectionID)
	if err != nil {
		return Collection{}, "", OpenAPISyncConfig{}, false, err
	}
	if len(collection.OpenAPI) == 0 {
		return Collection{}, "", OpenAPISyncConfig{}, false, errors.New("OpenAPI sync is not connected")
	}
	collectionCopy := *collection
	collectionCopy.Items = append([]RequestItem(nil), collection.Items...)
	collectionCopy.Folders = append([]FolderConfig(nil), collection.Folders...)
	collectionCopy.Variables = append([]Variable(nil), collection.Variables...)
	config := firstOpenAPISyncConfig(collectionCopy)
	content, noStoredSpec, err := a.loadOpenAPISyncSpecLocked(collection.Path)
	if err != nil {
		return Collection{}, "", OpenAPISyncConfig{}, false, err
	}
	return collectionCopy, content, config, noStoredSpec, nil
}

func firstOpenAPISyncConfig(collection Collection) OpenAPISyncConfig {
	if len(collection.OpenAPI) == 0 {
		return OpenAPISyncConfig{GroupBy: "tag", AutoCheck: true, AutoCheckInterval: 5}
	}
	return normalizeOpenAPISyncConfig(collection.OpenAPI[0])
}

func newOpenAPISyncConfig(sourceURL, groupBy, hash string) OpenAPISyncConfig {
	return OpenAPISyncConfig{
		SourceURL:         strings.TrimSpace(sourceURL),
		GroupBy:           normalizeOpenAPISyncGroupBy(groupBy),
		LastSyncDate:      time.Now().UTC().Format(time.RFC3339),
		SpecHash:          hash,
		AutoCheck:         true,
		AutoCheckInterval: 5,
	}
}

func newOpenAPISyncConfigPreservingSettings(sourceURL, groupBy, hash string, existing OpenAPISyncConfig) OpenAPISyncConfig {
	next := newOpenAPISyncConfig(sourceURL, groupBy, hash)
	existing = normalizeOpenAPISyncConfig(existing)
	next.AutoCheck = existing.AutoCheck
	next.AutoCheckInterval = normalizeOpenAPISyncAutoCheckInterval(existing.AutoCheckInterval)
	return next
}

func normalizeOpenAPISyncConfig(config OpenAPISyncConfig) OpenAPISyncConfig {
	config.SourceURL = strings.TrimSpace(config.SourceURL)
	config.GroupBy = normalizeOpenAPISyncGroupBy(config.GroupBy)
	config.AutoCheckInterval = normalizeOpenAPISyncAutoCheckInterval(config.AutoCheckInterval)
	return config
}

func normalizeOpenAPISyncAutoCheckInterval(interval int) int {
	if interval <= 0 {
		return 5
	}
	return interval
}

func normalizeOpenAPISyncGroupBy(groupBy string) string {
	switch strings.ToLower(strings.TrimSpace(groupBy)) {
	case "path", "paths":
		return "path"
	default:
		return "tag"
	}
}

func validateOpenAPISyncSource(sourceURL string) error {
	sourceURL = strings.TrimSpace(sourceURL)
	if sourceURL == "" {
		return errors.New("OpenAPI source URL or file path is required")
	}
	if parsed, err := url.Parse(sourceURL); err == nil && parsed.Scheme != "" {
		switch strings.ToLower(parsed.Scheme) {
		case "http", "https", "file":
			return nil
		default:
			return errors.New("invalid source: only http/https URLs and local file paths are allowed")
		}
	}
	return nil
}

func fetchOpenAPISyncContent(collectionPath, sourceURL string, client *http.Client) (string, error) {
	sourceURL = strings.TrimSpace(sourceURL)
	if sourceURL == "" {
		return "", errors.New("OpenAPI source URL or file path is required")
	}
	if err := validateOpenAPISyncSource(sourceURL); err != nil {
		return "", err
	}
	if parsed, err := url.Parse(sourceURL); err == nil && parsed.Scheme != "" {
		switch strings.ToLower(parsed.Scheme) {
		case "http", "https":
			if client == nil {
				client = http.DefaultClient
			}
			fetchURL := sourceURL
			separator := "?"
			if strings.Contains(fetchURL, "?") {
				separator = "&"
			}
			fetchURL += separator + "_=" + strconv.FormatInt(time.Now().UnixMilli(), 10)
			req, err := http.NewRequest(http.MethodGet, fetchURL, nil)
			if err != nil {
				return "", err
			}
			req.Header.Set("Cache-Control", "no-cache, no-store, must-revalidate")
			req.Header.Set("Pragma", "no-cache")
			res, err := client.Do(req)
			if err != nil {
				return "", fmt.Errorf("could not reach %s: %w", sourceURL, err)
			}
			defer func() { _ = res.Body.Close() }()
			if res.StatusCode < 200 || res.StatusCode >= 300 {
				return "", fmt.Errorf("failed to fetch spec: %d %s", res.StatusCode, http.StatusText(res.StatusCode))
			}
			data, err := io.ReadAll(io.LimitReader(res.Body, 16<<20))
			if err != nil {
				return "", err
			}
			return string(data), nil
		case "file":
			sourceURL = parsed.Path
		default:
			return "", errors.New("invalid source: only http/https URLs and local file paths are allowed")
		}
	}
	path := sourceURL
	if !filepath.IsAbs(path) && strings.TrimSpace(collectionPath) != "" {
		path = filepath.Join(collectionPath, path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return "", fmt.Errorf("spec file not found at: %s", sourceURL)
		}
		return "", err
	}
	return string(data), nil
}

type openAPISpecMetadataEntry struct {
	Filename  string `json:"filename"`
	SourceURL string `json:"sourceUrl"`
}

func (a *App) openAPISyncSpecsDirLocked() string {
	if a.dataDir == "" {
		a.dataDir = defaultDataDir()
	}
	return filepath.Join(a.dataDir, "specs")
}

func (a *App) openAPISyncSpecMetadataPathLocked() string {
	return filepath.Join(a.openAPISyncSpecsDirLocked(), "metadata.json")
}

func (a *App) readOpenAPISyncSpecMetadataLocked() map[string][]openAPISpecMetadataEntry {
	path := a.openAPISyncSpecMetadataPathLocked()
	data, err := os.ReadFile(path)
	if err != nil {
		return map[string][]openAPISpecMetadataEntry{}
	}
	var meta map[string][]openAPISpecMetadataEntry
	if err := json.Unmarshal(data, &meta); err != nil || meta == nil {
		return map[string][]openAPISpecMetadataEntry{}
	}
	return meta
}

func (a *App) writeOpenAPISyncSpecMetadataLocked(meta map[string][]openAPISpecMetadataEntry) error {
	if meta == nil {
		meta = map[string][]openAPISpecMetadataEntry{}
	}
	path := a.openAPISyncSpecMetadataPathLocked()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	data, err := json.MarshalIndent(meta, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o600)
}

func (a *App) saveOpenAPISyncSpecLocked(collectionPath, sourceURL, content string) error {
	if strings.TrimSpace(collectionPath) == "" || strings.TrimSpace(content) == "" {
		return nil
	}
	specsDir := a.openAPISyncSpecsDirLocked()
	if err := os.MkdirAll(specsDir, 0o755); err != nil {
		return err
	}
	meta := a.readOpenAPISyncSpecMetadataLocked()
	key := filepath.Clean(collectionPath)
	entry := openAPISpecMetadataEntry{}
	if entries := meta[key]; len(entries) > 0 {
		entry = entries[0]
	}
	if strings.TrimSpace(entry.Filename) == "" {
		ext := ".json"
		if openAPISyncSpecLooksYAML(content) {
			ext = ".yaml"
		}
		entry.Filename = newID("spec") + ext
	}
	entry.SourceURL = strings.TrimSpace(sourceURL)
	meta[key] = []openAPISpecMetadataEntry{entry}
	if err := os.WriteFile(filepath.Join(specsDir, entry.Filename), []byte(content), 0o600); err != nil {
		return err
	}
	return a.writeOpenAPISyncSpecMetadataLocked(meta)
}

func (a *App) loadOpenAPISyncSpecLocked(collectionPath string) (string, bool, error) {
	if strings.TrimSpace(collectionPath) == "" {
		return "", true, nil
	}
	meta := a.readOpenAPISyncSpecMetadataLocked()
	entries := meta[filepath.Clean(collectionPath)]
	if len(entries) == 0 || strings.TrimSpace(entries[0].Filename) == "" {
		return "", true, nil
	}
	specsDir := a.openAPISyncSpecsDirLocked()
	target := filepath.Clean(filepath.Join(specsDir, entries[0].Filename))
	if !pathInside(specsDir, target) {
		return "", true, nil
	}
	data, err := os.ReadFile(target)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return "", true, nil
		}
		return "", false, err
	}
	return string(data), false, nil
}

func (a *App) cleanupOpenAPISyncSpecLocked(collectionPath string) {
	meta := a.readOpenAPISyncSpecMetadataLocked()
	key := filepath.Clean(collectionPath)
	for _, entry := range meta[key] {
		if strings.TrimSpace(entry.Filename) != "" {
			_ = os.Remove(filepath.Join(a.openAPISyncSpecsDirLocked(), entry.Filename))
		}
	}
	delete(meta, key)
	_ = a.writeOpenAPISyncSpecMetadataLocked(meta)
}

func openAPISyncSpecLooksYAML(content string) bool {
	var jsonValue interface{}
	if json.Unmarshal([]byte(content), &jsonValue) == nil {
		return false
	}
	var yamlValue interface{}
	return yaml.Unmarshal([]byte(content), &yamlValue) == nil
}

func openAPISyncCollectionFromContent(content, fallbackName, groupBy string) (Collection, string, openAPIDoc, error) {
	hash, doc, err := validateOpenAPISyncSpec(content)
	if err != nil {
		return Collection{}, "", openAPIDoc{}, err
	}
	collection, err := importOpenAPI(content, fallbackName, normalizeOpenAPISyncGroupBy(groupBy))
	if err != nil {
		return Collection{}, "", openAPIDoc{}, err
	}
	return collection, hash, doc, nil
}

func validateOpenAPISyncSpec(content string) (string, openAPIDoc, error) {
	var raw map[string]interface{}
	if err := yaml.Unmarshal([]byte(content), &raw); err != nil {
		return "", openAPIDoc{}, fmt.Errorf("parse openapi: %w", err)
	}
	if _, ok := raw["swagger"]; ok {
		return "", openAPIDoc{}, errors.New("OpenAPI sync supports OpenAPI 3.x specifications; Swagger 2.0 is not supported")
	}
	var doc openAPIDoc
	if err := yaml.Unmarshal([]byte(content), &doc); err != nil {
		return "", openAPIDoc{}, fmt.Errorf("parse openapi: %w", err)
	}
	if !strings.HasPrefix(strings.TrimSpace(doc.OpenAPI), "3.") {
		return "", openAPIDoc{}, errors.New("OpenAPI sync supports OpenAPI 3.x specifications")
	}
	if len(doc.Paths) == 0 && len(doc.Webhooks) == 0 {
		return "", openAPIDoc{}, errors.New("OpenAPI document contains no supported operations")
	}
	canonical, err := json.Marshal(raw)
	if err != nil {
		return "", openAPIDoc{}, err
	}
	sum := md5.Sum(canonical)
	return hex.EncodeToString(sum[:]), doc, nil
}

func buildOpenAPISpecDiffLines(storedContent, newContent string) []OpenAPISyncSpecDiffLine {
	oldLines := splitOpenAPISpecDiffContent(storedContent)
	newLines := splitOpenAPISpecDiffContent(newContent)
	lines := make([]OpenAPISyncSpecDiffLine, 0, max(len(oldLines), len(newLines)))
	for oldIndex, newIndex := 0, 0; oldIndex < len(oldLines) || newIndex < len(newLines); {
		switch {
		case oldIndex >= len(oldLines):
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "added", NewNumber: newIndex + 1, NewText: newLines[newIndex]})
			newIndex++
		case newIndex >= len(newLines):
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "removed", OldNumber: oldIndex + 1, OldText: oldLines[oldIndex]})
			oldIndex++
		case oldLines[oldIndex] == newLines[newIndex]:
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "same", OldNumber: oldIndex + 1, NewNumber: newIndex + 1, OldText: oldLines[oldIndex], NewText: newLines[newIndex]})
			oldIndex++
			newIndex++
		case oldIndex+1 < len(oldLines) && oldLines[oldIndex+1] == newLines[newIndex]:
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "removed", OldNumber: oldIndex + 1, OldText: oldLines[oldIndex]})
			oldIndex++
		case newIndex+1 < len(newLines) && oldLines[oldIndex] == newLines[newIndex+1]:
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "added", NewNumber: newIndex + 1, NewText: newLines[newIndex]})
			newIndex++
		default:
			lines = append(lines, OpenAPISyncSpecDiffLine{Kind: "changed", OldNumber: oldIndex + 1, NewNumber: newIndex + 1, OldText: oldLines[oldIndex], NewText: newLines[newIndex]})
			oldIndex++
			newIndex++
		}
	}
	return lines
}

func splitOpenAPISpecDiffContent(content string) []string {
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		return nil
	}
	lines := strings.Split(content, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func buildOpenAPISyncResult(collection, specCollection Collection, sourceURL, groupBy, hash string, doc openAPIDoc) OpenAPISyncResult {
	existing := openAPIEndpointMap(collection.Items)
	specs := openAPIEndpointMap(specCollection.Items)
	result := OpenAPISyncResult{
		SourceURL:     strings.TrimSpace(sourceURL),
		GroupBy:       normalizeOpenAPISyncGroupBy(groupBy),
		SpecHash:      hash,
		Title:         doc.Info.Title,
		Version:       doc.Info.Version,
		EndpointCount: len(specs),
		LastSyncDate:  firstOpenAPISyncConfig(collection).LastSyncDate,
	}
	seen := map[string]bool{}
	for _, spec := range specCollection.Items {
		id := openAPIEndpointID(spec)
		if id == "" || seen[id] {
			continue
		}
		seen[id] = true
		method, path := splitOpenAPIEndpointID(id)
		existingRef, ok := existing[id]
		if !ok {
			result.Added++
			result.Changes = append(result.Changes, OpenAPISyncEndpointChange{ID: id, Method: method, Path: path, Name: spec.Name, Change: "added", DefaultDecision: "accept-incoming"})
			continue
		}
		merged := mergeOpenAPISpecIntoRequest(existingRef.Item, spec, true)
		if openAPISyncRequestFieldsEqual(existingRef.Item, merged) {
			result.Unchanged++
			continue
		}
		result.Updated++
		result.Changes = append(result.Changes, OpenAPISyncEndpointChange{ID: id, Method: method, Path: path, Name: firstNonEmpty(existingRef.Item.Name, spec.Name), Change: "updated", ItemID: existingRef.Item.ID, DefaultDecision: "accept-incoming"})
	}
	specIDs := map[string]bool{}
	for id := range specs {
		specIDs[id] = true
	}
	existingIDs := make([]string, 0, len(existing))
	for id := range existing {
		existingIDs = append(existingIDs, id)
	}
	sort.Strings(existingIDs)
	for _, id := range existingIDs {
		if specIDs[id] {
			continue
		}
		ref := existing[id]
		method, path := splitOpenAPIEndpointID(id)
		result.Removed++
		result.Changes = append(result.Changes, OpenAPISyncEndpointChange{ID: id, Method: method, Path: path, Name: ref.Item.Name, Change: "removed", ItemID: ref.Item.ID, DefaultDecision: "accept-incoming"})
	}
	result.HasChanges = result.Added+result.Updated+result.Removed > 0
	return result
}

type openAPIEndpointRef struct {
	Index int
	Item  RequestItem
}

func openAPIEndpointMap(items []RequestItem) map[string]openAPIEndpointRef {
	out := map[string]openAPIEndpointRef{}
	for index, item := range items {
		if item.Type != "" && item.Type != "http" && item.Type != "graphql" {
			continue
		}
		id := openAPIEndpointID(item)
		if id == "" {
			continue
		}
		if _, exists := out[id]; !exists {
			out[id] = openAPIEndpointRef{Index: index, Item: item}
		}
	}
	return out
}

func openAPIEndpointID(item RequestItem) string {
	method := strings.ToUpper(firstNonEmpty(item.Method, http.MethodGet))
	path := normalizeOpenAPIEndpointPath(item.URL)
	if method == "" || path == "" {
		return ""
	}
	return method + ":" + path
}

func splitOpenAPIEndpointID(id string) (string, string) {
	method, path, ok := strings.Cut(id, ":")
	if !ok {
		return id, ""
	}
	return method, path
}

func normalizeOpenAPIEndpointPath(rawURL string) string {
	value := strings.TrimSpace(rawURL)
	if value == "" {
		return ""
	}
	value = regexp.MustCompile(`\{\{[^}]+\}\}`).ReplaceAllString(value, "")
	if parsed, err := url.Parse(value); err == nil && parsed.Host != "" {
		value = parsed.EscapedPath()
	}
	if cut, _, ok := strings.Cut(value, "?"); ok {
		value = cut
	}
	value = regexp.MustCompile(`\{([^}]+)\}`).ReplaceAllString(value, ":$1")
	value = strings.ReplaceAll(value, "//", "/")
	for strings.Contains(value, "//") {
		value = strings.ReplaceAll(value, "//", "/")
	}
	value = strings.TrimRight(value, "/")
	if value == "" {
		value = "/"
	}
	if !strings.HasPrefix(value, "/") {
		value = "/" + value
	}
	return value
}

func applyOpenAPISyncToCollection(collection *Collection, specCollection Collection, options OpenAPISyncOptions) map[string]bool {
	preserveValues := options.PreserveValues
	decisions := normalizeOpenAPISyncEndpointDecisions(options.EndpointDecisions)
	existing := openAPIEndpointMap(collection.Items)
	specIDs := map[string]bool{}
	maxSeq := 0
	for _, item := range collection.Items {
		if item.Seq > maxSeq {
			maxSeq = item.Seq
		}
	}
	for _, spec := range specCollection.Items {
		id := openAPIEndpointID(spec)
		if id == "" || specIDs[id] {
			continue
		}
		specIDs[id] = true
		if ref, ok := existing[id]; ok {
			if openAPISyncEndpointDecision(decisions, id, "accept-incoming") == "keep-mine" {
				continue
			}
			merged := mergeOpenAPISpecIntoRequest(collection.Items[ref.Index], spec, preserveValues)
			merged.ID = collection.Items[ref.Index].ID
			merged.FilePath = collection.Items[ref.Index].FilePath
			merged.FolderPath = collection.Items[ref.Index].FolderPath
			merged.Seq = collection.Items[ref.Index].Seq
			merged.CreatedAt = collection.Items[ref.Index].CreatedAt
			merged.UpdatedAt = time.Now()
			collection.Items[ref.Index] = merged
			continue
		}
		if openAPISyncEndpointDecision(decisions, id, "accept-incoming") == "keep-mine" {
			continue
		}
		next := spec
		if strings.TrimSpace(next.ID) == "" {
			next.ID = newID("request")
		}
		maxSeq++
		next.Seq = maxSeq
		next.CreatedAt = time.Now()
		next.UpdatedAt = time.Now()
		collection.Items = append(collection.Items, next)
	}
	removedIDs := map[string]bool{}
	next := collection.Items[:0]
	for _, item := range collection.Items {
		id := openAPIEndpointID(item)
		if id != "" && !specIDs[id] {
			defaultDecision := "accept-incoming"
			if openAPISyncEndpointDecision(decisions, id, defaultDecision) == "accept-incoming" {
				removedIDs[item.ID] = true
				continue
			}
		}
		next = append(next, item)
	}
	collection.Items = next
	collection.Variables = mergeOpenAPIVariablesPreserving(specCollection.Variables, collection.Variables, preserveValues)
	collection.UpdatedAt = time.Now()
	return removedIDs
}

func buildOpenAPILocalDriftResult(collection, specCollection Collection, config OpenAPISyncConfig) OpenAPILocalDriftResult {
	config = normalizeOpenAPISyncConfig(config)
	existing := openAPIEndpointMap(collection.Items)
	specs := openAPIEndpointMap(specCollection.Items)
	result := OpenAPILocalDriftResult{
		SourceURL:               config.SourceURL,
		GroupBy:                 config.GroupBy,
		SpecEndpointCount:       len(specs),
		CollectionEndpointCount: len(existing),
		LastSyncDate:            config.LastSyncDate,
	}
	seenSpec := map[string]bool{}
	for _, spec := range specCollection.Items {
		id := openAPIEndpointID(spec)
		if id == "" || seenSpec[id] {
			continue
		}
		seenSpec[id] = true
		method, path := splitOpenAPIEndpointID(id)
		ref, ok := existing[id]
		if !ok {
			result.Missing++
			result.Changes = append(result.Changes, OpenAPISyncEndpointChange{
				ID:              id,
				Method:          method,
				Path:            path,
				Name:            spec.Name,
				Change:          "missing",
				DefaultDecision: "accept-incoming",
			})
			continue
		}
		if changes := openAPILocalDriftRequestChanges(spec, ref.Item); len(changes) > 0 {
			result.Modified++
			result.Changes = append(result.Changes, OpenAPISyncEndpointChange{
				ID:              id,
				Method:          method,
				Path:            path,
				Name:            firstNonEmpty(ref.Item.Name, spec.Name),
				Change:          "modified",
				ItemID:          ref.Item.ID,
				DefaultDecision: "accept-incoming",
			})
			continue
		}
		result.InSync++
	}
	specIDs := map[string]bool{}
	for id := range specs {
		specIDs[id] = true
	}
	existingIDs := make([]string, 0, len(existing))
	for id := range existing {
		existingIDs = append(existingIDs, id)
	}
	sort.Strings(existingIDs)
	for _, id := range existingIDs {
		if specIDs[id] {
			continue
		}
		ref := existing[id]
		method, path := splitOpenAPIEndpointID(id)
		result.LocalOnly++
		result.Changes = append(result.Changes, OpenAPISyncEndpointChange{
			ID:              id,
			Method:          method,
			Path:            path,
			Name:            ref.Item.Name,
			Change:          "local-only",
			ItemID:          ref.Item.ID,
			DefaultDecision: "keep-mine",
		})
	}
	result.HasChanges = result.Modified+result.Missing+result.LocalOnly > 0
	return result
}

func applyOpenAPILocalDriftToCollection(collection *Collection, specCollection Collection, options OpenAPILocalDriftOptions) (map[string]bool, error) {
	existing := openAPIEndpointMap(collection.Items)
	specs := openAPIEndpointMap(specCollection.Items)
	resetIDs := openAPILocalDriftIDSet(options.ResetIDs)
	restoreIDs := openAPILocalDriftIDSet(options.RestoreIDs)
	deleteIDs := openAPILocalDriftIDSet(options.DeleteIDs)
	now := time.Now()
	changed := false

	for _, id := range sortedOpenAPIEndpointIDs(resetIDs) {
		ref, ok := existing[id]
		spec, specOK := specs[id]
		if !ok || !specOK {
			continue
		}
		merged := mergeOpenAPISpecIntoRequest(collection.Items[ref.Index], spec.Item, false)
		merged.ID = collection.Items[ref.Index].ID
		merged.FilePath = collection.Items[ref.Index].FilePath
		merged.FolderPath = collection.Items[ref.Index].FolderPath
		merged.Seq = collection.Items[ref.Index].Seq
		merged.CreatedAt = collection.Items[ref.Index].CreatedAt
		merged.UpdatedAt = now
		collection.Items[ref.Index] = merged
		changed = true
	}

	maxSeq := 0
	for _, item := range collection.Items {
		if item.Seq > maxSeq {
			maxSeq = item.Seq
		}
	}
	for _, id := range sortedOpenAPIEndpointIDs(restoreIDs) {
		if _, ok := existing[id]; ok {
			continue
		}
		spec, ok := specs[id]
		if !ok {
			continue
		}
		next := spec.Item
		next.ID = newID("request")
		maxSeq++
		next.Seq = maxSeq
		next.CreatedAt = now
		next.UpdatedAt = now
		assignExampleIDs(&next)
		collection.Items = append(collection.Items, next)
		changed = true
	}

	removedIDs := map[string]bool{}
	nextItems := collection.Items[:0]
	for _, item := range collection.Items {
		id := openAPIEndpointID(item)
		if deleteIDs[id] {
			if _, specExists := specs[id]; !specExists {
				if err := removeOpenAPILocalDriftRequestFile(collection, item); err != nil {
					return nil, err
				}
				removedIDs[item.ID] = true
				changed = true
				continue
			}
		}
		nextItems = append(nextItems, item)
	}
	collection.Items = nextItems

	if changed {
		collection.UpdatedAt = now
	}
	return removedIDs, nil
}

func openAPILocalDriftIDSet(values []string) map[string]bool {
	out := map[string]bool{}
	for _, value := range values {
		value = strings.TrimSpace(value)
		if value != "" {
			out[value] = true
		}
	}
	return out
}

func sortedOpenAPIEndpointIDs(values map[string]bool) []string {
	out := make([]string, 0, len(values))
	for value := range values {
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

func removeOpenAPILocalDriftRequestFile(collection *Collection, item RequestItem) error {
	target := requestFilePath(*collection, item, requestFileExtensionForCollection(*collection))
	if pathInside(collection.Path, item.FilePath) {
		target = filepath.Clean(item.FilePath)
	}
	if !pathInside(collection.Path, target) {
		return fmt.Errorf("request path %s escapes collection", target)
	}
	if err := os.Remove(target); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func openAPILocalDriftRequestChanges(spec, actual RequestItem) []string {
	var changes []string
	if !stringSlicesEqual(openAPILocalDriftKeyValueNames(spec.PathParams, false), openAPILocalDriftKeyValueNames(actual.PathParams, false)) {
		changes = append(changes, "path params")
	}
	if !stringSlicesEqual(openAPILocalDriftKeyValueNames(spec.Params, false), openAPILocalDriftKeyValueNames(actual.Params, false)) {
		changes = append(changes, "query params")
	}
	if !stringSlicesEqual(openAPILocalDriftKeyValueNames(spec.Headers, true), openAPILocalDriftKeyValueNames(actual.Headers, true)) {
		changes = append(changes, "headers")
	}
	specBodyMode := normalizeOpenAPILocalDriftMode(spec.Body.Mode, "none")
	actualBodyMode := normalizeOpenAPILocalDriftMode(actual.Body.Mode, "none")
	if specBodyMode != actualBodyMode {
		changes = append(changes, "body mode")
	} else {
		switch specBodyMode {
		case "json":
			if !stringSlicesEqual(openAPILocalDriftJSONShape(spec.Body.JSON), openAPILocalDriftJSONShape(actual.Body.JSON)) {
				changes = append(changes, "json body")
			}
		case "formurlencoded":
			if !stringSlicesEqual(openAPILocalDriftKeyValueNames(spec.Body.FormURLEncoded, false), openAPILocalDriftKeyValueNames(actual.Body.FormURLEncoded, false)) {
				changes = append(changes, "form body")
			}
		case "multipartform":
			if !stringSlicesEqual(openAPILocalDriftMultipartNames(spec.Body.Multipart), openAPILocalDriftMultipartNames(actual.Body.Multipart)) {
				changes = append(changes, "multipart body")
			}
		}
	}
	if normalizeOpenAPILocalDriftMode(spec.Auth.Mode, "none") != normalizeOpenAPILocalDriftMode(actual.Auth.Mode, "none") {
		changes = append(changes, "auth")
	}
	return changes
}

func openAPILocalDriftKeyValueNames(values []KeyValue, foldCase bool) []string {
	out := make([]string, 0, len(values))
	for _, value := range values {
		name := strings.TrimSpace(value.Name)
		if name == "" {
			continue
		}
		if foldCase {
			name = strings.ToLower(name)
		}
		out = append(out, name)
	}
	sort.Strings(out)
	return out
}

func openAPILocalDriftMultipartNames(values []FormPart) []string {
	out := make([]string, 0, len(values))
	for _, value := range values {
		name := strings.TrimSpace(value.Name)
		if name == "" {
			continue
		}
		kind := "text"
		if strings.TrimSpace(value.FilePath) != "" {
			kind = "file"
		}
		out = append(out, name+":"+kind)
	}
	sort.Strings(out)
	return out
}

func normalizeOpenAPILocalDriftMode(value, fallback string) string {
	value = strings.ToLower(strings.TrimSpace(value))
	if value == "" {
		value = fallback
	}
	return strings.ReplaceAll(value, "-", "")
}

func openAPILocalDriftJSONShape(input string) []string {
	input = strings.TrimSpace(input)
	if input == "" {
		return nil
	}
	masked, _ := maskJSONInterpolations(input, "BRU_D")
	var value interface{}
	if err := json.Unmarshal([]byte(masked), &value); err != nil {
		return []string{"<json>"}
	}
	out := []string{}
	collectOpenAPILocalDriftJSONShape(value, "", &out)
	sort.Strings(out)
	return uniqueStrings(out)
}

func collectOpenAPILocalDriftJSONShape(value interface{}, prefix string, out *[]string) {
	switch typed := value.(type) {
	case map[string]interface{}:
		keys := make([]string, 0, len(typed))
		for key := range typed {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			path := key
			if prefix != "" {
				path = prefix + "." + key
			}
			*out = append(*out, path)
			collectOpenAPILocalDriftJSONShape(typed[key], path, out)
		}
	case []interface{}:
		arrayPath := "[]"
		if prefix != "" {
			arrayPath = prefix + "[]"
		}
		*out = append(*out, arrayPath)
		if len(typed) > 0 {
			collectOpenAPILocalDriftJSONShape(typed[0], arrayPath, out)
		}
	}
}

func stringSlicesEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func uniqueStrings(values []string) []string {
	if len(values) == 0 {
		return nil
	}
	out := values[:0]
	var previous string
	for index, value := range values {
		if index == 0 || value != previous {
			out = append(out, value)
		}
		previous = value
	}
	return out
}

func normalizeOpenAPISyncEndpointDecisions(values map[string]string) map[string]string {
	if len(values) == 0 {
		return nil
	}
	out := map[string]string{}
	for id, decision := range values {
		id = strings.TrimSpace(id)
		if id == "" {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(decision)) {
		case "accept", "accept-incoming", "incoming", "add", "apply", "remove", "reset":
			out[id] = "accept-incoming"
		case "keep", "keep-mine", "mine", "skip":
			out[id] = "keep-mine"
		}
	}
	return out
}

func openAPISyncEndpointDecision(decisions map[string]string, id, fallback string) string {
	if decision, ok := decisions[id]; ok {
		return decision
	}
	switch fallback {
	case "keep-mine":
		return "keep-mine"
	default:
		return "accept-incoming"
	}
}

func mergeOpenAPISpecIntoRequest(existing, spec RequestItem, preserveValues bool) RequestItem {
	if !preserveValues {
		out := existing
		out.Method = spec.Method
		out.URL = spec.URL
		out.PathParams = append([]KeyValue(nil), spec.PathParams...)
		out.Params = append([]KeyValue(nil), spec.Params...)
		out.Headers = append([]KeyValue(nil), spec.Headers...)
		out.Body = spec.Body
		out.Auth = spec.Auth
		out.Tags = append([]string(nil), spec.Tags...)
		out.Docs = firstNonEmpty(existing.Docs, spec.Docs)
		return out
	}
	out := existing
	out.URL = spec.URL
	out.PathParams = mergeKeyValueListPreserving(spec.PathParams, existing.PathParams, true)
	out.Params = mergeKeyValueListPreserving(spec.Params, existing.Params, true)
	out.Headers = mergeKeyValueListPreserving(spec.Headers, existing.Headers, true)
	out.Body = mergeRequestBodyPreserving(existing.Body, spec.Body, true)
	out.Auth = mergeAuthPreserving(existing.Auth, spec.Auth, true)
	return out
}

func openAPISyncRequestFieldsEqual(a, b RequestItem) bool {
	return a.URL == b.URL &&
		reflect.DeepEqual(a.PathParams, b.PathParams) &&
		reflect.DeepEqual(a.Params, b.Params) &&
		reflect.DeepEqual(a.Headers, b.Headers) &&
		reflect.DeepEqual(a.Body, b.Body) &&
		reflect.DeepEqual(a.Auth, b.Auth)
}

func mergeKeyValueListPreserving(specItems, existingItems []KeyValue, preserveValues bool) []KeyValue {
	spec := append([]KeyValue(nil), specItems...)
	if !preserveValues {
		return spec
	}
	cursorByName := map[string]int{}
	out := make([]KeyValue, 0, len(spec))
	for _, specEntry := range spec {
		matches := []KeyValue{}
		for _, existing := range existingItems {
			if existing.Name == specEntry.Name {
				matches = append(matches, existing)
			}
		}
		cursor := cursorByName[specEntry.Name]
		if cursor >= len(matches) {
			out = append(out, specEntry)
			continue
		}
		picked := matches[cursor]
		cursorByName[specEntry.Name] = cursor + 1
		merged := specEntry
		merged.Value = picked.Value
		merged.Enabled = picked.Enabled
		out = append(out, merged)
	}
	return out
}

func mergeFormPartListPreserving(specItems, existingItems []FormPart, preserveValues bool) []FormPart {
	spec := append([]FormPart(nil), specItems...)
	if !preserveValues {
		return spec
	}
	cursorByName := map[string]int{}
	out := make([]FormPart, 0, len(spec))
	for _, specEntry := range spec {
		matches := []FormPart{}
		for _, existing := range existingItems {
			if existing.Name == specEntry.Name {
				matches = append(matches, existing)
			}
		}
		cursor := cursorByName[specEntry.Name]
		if cursor >= len(matches) {
			out = append(out, specEntry)
			continue
		}
		picked := matches[cursor]
		cursorByName[specEntry.Name] = cursor + 1
		merged := specEntry
		merged.Value = picked.Value
		merged.FilePath = picked.FilePath
		merged.ContentType = picked.ContentType
		merged.Enabled = picked.Enabled
		out = append(out, merged)
	}
	return out
}

func mergeOpenAPIVariablesPreserving(specItems, existingItems []Variable, preserveValues bool) []Variable {
	spec := append([]Variable(nil), specItems...)
	if !preserveValues {
		return spec
	}
	existingByName := map[string]Variable{}
	for _, existing := range existingItems {
		existingByName[existing.Name] = existing
	}
	out := make([]Variable, 0, len(spec))
	for _, specEntry := range spec {
		if existing, ok := existingByName[specEntry.Name]; ok {
			merged := specEntry
			merged.ID = firstNonEmpty(existing.ID, specEntry.ID)
			merged.Value = existing.Value
			merged.Enabled = existing.Enabled
			merged.Secret = existing.Secret
			out = append(out, merged)
			continue
		}
		out = append(out, specEntry)
	}
	return out
}

func mergeRequestBodyPreserving(existing, spec RequestBody, preserveValues bool) RequestBody {
	if !preserveValues {
		return spec
	}
	specMode := firstNonEmpty(spec.Mode, "none")
	existingMode := firstNonEmpty(existing.Mode, "none")
	if specMode != existingMode {
		return spec
	}
	switch specMode {
	case "json":
		return mergeJSONRequestBodyPreserving(existing, spec)
	case "formUrlEncoded":
		spec.FormURLEncoded = mergeKeyValueListPreserving(spec.FormURLEncoded, existing.FormURLEncoded, true)
		return spec
	case "multipartForm":
		spec.Multipart = mergeFormPartListPreserving(spec.Multipart, existing.Multipart, true)
		return spec
	case "graphql":
		if strings.TrimSpace(existing.GraphQLQuery) != "" || strings.TrimSpace(existing.GraphQLVariables) != "" {
			return existing
		}
		return spec
	default:
		return existing
	}
}

func mergeJSONRequestBodyPreserving(existing, spec RequestBody) RequestBody {
	if strings.TrimSpace(existing.JSON) == "" || strings.TrimSpace(spec.JSON) == "" {
		return spec
	}
	userMasked, userVars := maskJSONInterpolations(existing.JSON, "BRU_U")
	specMasked, specVars := maskJSONInterpolations(spec.JSON, "BRU_S")
	var userValue interface{}
	var specValue interface{}
	if err := json.Unmarshal([]byte(userMasked), &userValue); err != nil {
		return existing
	}
	if err := json.Unmarshal([]byte(specMasked), &specValue); err != nil {
		return existing
	}
	merged := mergeJSONValuesPreserving(userValue, specValue)
	data, err := json.MarshalIndent(merged, "", "  ")
	if err != nil {
		return existing
	}
	jsonText := unmaskJSONInterpolations(string(data), userVars, "BRU_U")
	jsonText = unmaskJSONInterpolations(jsonText, specVars, "BRU_S")
	spec.JSON = jsonText
	return spec
}

func mergeJSONValuesPreserving(userValue, specValue interface{}) interface{} {
	specMap, specMapOK := specValue.(map[string]interface{})
	userMap, userMapOK := userValue.(map[string]interface{})
	if specMapOK && userMapOK {
		out := map[string]interface{}{}
		keys := make([]string, 0, len(specMap))
		for key := range specMap {
			keys = append(keys, key)
		}
		sort.Strings(keys)
		for _, key := range keys {
			if userChild, ok := userMap[key]; ok {
				out[key] = mergeJSONValuesPreserving(userChild, specMap[key])
			} else {
				out[key] = specMap[key]
			}
		}
		return out
	}
	specArray, specArrayOK := specValue.([]interface{})
	userArray, userArrayOK := userValue.([]interface{})
	if specArrayOK && userArrayOK {
		if len(userArray) == 0 {
			return specArray
		}
		if len(specArray) == 0 {
			return userArray
		}
		out := make([]interface{}, 0, len(userArray))
		for _, userChild := range userArray {
			out = append(out, mergeJSONValuesPreserving(userChild, specArray[0]))
		}
		return out
	}
	if userValue == nil {
		return specValue
	}
	return userValue
}

const openAPISyncJSONSentinel = "\ue000"

func maskJSONInterpolations(input, prefix string) (string, []string) {
	var tokens []string
	var out strings.Builder
	inString := false
	for i := 0; i < len(input); {
		ch := input[i]
		if ch == '"' {
			backslashes := 0
			for j := i - 1; j >= 0 && input[j] == '\\'; j-- {
				backslashes++
			}
			if backslashes%2 == 0 {
				inString = !inString
			}
			out.WriteByte(ch)
			i++
			continue
		}
		if ch == '{' && i+1 < len(input) && input[i+1] == '{' {
			if end := strings.Index(input[i+2:], "}}"); end >= 0 {
				tokenEnd := i + 2 + end + 2
				token := input[i:tokenEnd]
				index := len(tokens)
				tokens = append(tokens, token)
				if inString {
					out.WriteString(openAPISyncJSONSentinel + prefix + "_S_" + strconv.Itoa(index) + openAPISyncJSONSentinel)
				} else {
					out.WriteString(`"` + openAPISyncJSONSentinel + prefix + "_V_" + strconv.Itoa(index) + openAPISyncJSONSentinel + `"`)
				}
				i = tokenEnd
				continue
			}
		}
		out.WriteByte(ch)
		i++
	}
	return out.String(), tokens
}

func unmaskJSONInterpolations(input string, tokens []string, prefix string) string {
	for index, token := range tokens {
		valueSentinel := openAPISyncJSONSentinel + prefix + "_V_" + strconv.Itoa(index) + openAPISyncJSONSentinel
		stringSentinel := openAPISyncJSONSentinel + prefix + "_S_" + strconv.Itoa(index) + openAPISyncJSONSentinel
		input = strings.ReplaceAll(input, `"`+valueSentinel+`"`, token)
		input = strings.ReplaceAll(input, stringSentinel, token)
	}
	return input
}

func mergeAuthPreserving(existing, spec AuthConfig, preserveValues bool) AuthConfig {
	if !preserveValues {
		return spec
	}
	existingMode := firstNonEmpty(existing.Mode, "none")
	specMode := firstNonEmpty(spec.Mode, "none")
	if existingMode != specMode {
		return spec
	}
	if specMode == "none" || specMode == "inherit" {
		return spec
	}
	out := spec
	switch specMode {
	case "basic", "digest", "wsse":
		out.Username = firstNonEmpty(existing.Username, spec.Username)
		out.Password = firstNonEmpty(existing.Password, spec.Password)
	case "ntlm":
		out.Username = firstNonEmpty(existing.Username, spec.Username)
		out.Password = firstNonEmpty(existing.Password, spec.Password)
		out.Domain = firstNonEmpty(existing.Domain, spec.Domain)
	case "bearer":
		out.Token = firstNonEmpty(existing.Token, spec.Token)
	case "apikey":
		out.APIKey = firstNonEmpty(existing.APIKey, spec.APIKey)
		out.APIValue = firstNonEmpty(existing.APIValue, spec.APIValue)
		out.APILocation = firstNonEmpty(existing.APILocation, spec.APILocation)
	case "oauth1":
		out.OAuth1 = mergeOAuth1Preserving(existing.OAuth1, spec.OAuth1)
	case "oauth2":
		out.OAuth2 = mergeOAuth2Preserving(existing.OAuth2, spec.OAuth2)
	case "awsv4":
		out.AWSV4 = mergeAWSV4Preserving(existing.AWSV4, spec.AWSV4)
	}
	return out
}

func mergeOAuth1Preserving(existing, spec OAuth1Auth) OAuth1Auth {
	out := spec
	out.ConsumerKey = firstNonEmpty(existing.ConsumerKey, spec.ConsumerKey)
	out.ConsumerSecret = firstNonEmpty(existing.ConsumerSecret, spec.ConsumerSecret)
	out.AccessToken = firstNonEmpty(existing.AccessToken, spec.AccessToken)
	out.AccessTokenSecret = firstNonEmpty(existing.AccessTokenSecret, spec.AccessTokenSecret)
	out.CallbackURL = firstNonEmpty(existing.CallbackURL, spec.CallbackURL)
	out.Verifier = firstNonEmpty(existing.Verifier, spec.Verifier)
	out.SignatureMethod = firstNonEmpty(existing.SignatureMethod, spec.SignatureMethod)
	out.PrivateKey = firstNonEmpty(existing.PrivateKey, spec.PrivateKey)
	out.PrivateKeyType = firstNonEmpty(existing.PrivateKeyType, spec.PrivateKeyType)
	out.Timestamp = firstNonEmpty(existing.Timestamp, spec.Timestamp)
	out.Nonce = firstNonEmpty(existing.Nonce, spec.Nonce)
	out.Version = firstNonEmpty(existing.Version, spec.Version)
	out.Realm = firstNonEmpty(existing.Realm, spec.Realm)
	out.Placement = firstNonEmpty(existing.Placement, spec.Placement)
	out.IncludeBodyHash = existing.IncludeBodyHash || spec.IncludeBodyHash
	return out
}

func mergeOAuth2Preserving(existing, spec OAuth2Auth) OAuth2Auth {
	out := spec
	out.GrantType = firstNonEmpty(existing.GrantType, spec.GrantType)
	out.CallbackURL = firstNonEmpty(existing.CallbackURL, spec.CallbackURL)
	out.AuthorizationURL = firstNonEmpty(existing.AuthorizationURL, spec.AuthorizationURL)
	out.AccessTokenURL = firstNonEmpty(existing.AccessTokenURL, spec.AccessTokenURL)
	out.RefreshTokenURL = firstNonEmpty(existing.RefreshTokenURL, spec.RefreshTokenURL)
	out.Username = firstNonEmpty(existing.Username, spec.Username)
	out.Password = firstNonEmpty(existing.Password, spec.Password)
	out.ClientID = firstNonEmpty(existing.ClientID, spec.ClientID)
	out.ClientSecret = firstNonEmpty(existing.ClientSecret, spec.ClientSecret)
	out.Scope = firstNonEmpty(existing.Scope, spec.Scope)
	out.State = firstNonEmpty(existing.State, spec.State)
	out.CredentialsPlacement = firstNonEmpty(existing.CredentialsPlacement, spec.CredentialsPlacement)
	out.CredentialsID = firstNonEmpty(existing.CredentialsID, spec.CredentialsID)
	out.TokenSource = firstNonEmpty(existing.TokenSource, spec.TokenSource)
	out.TokenPlacement = firstNonEmpty(existing.TokenPlacement, spec.TokenPlacement)
	out.TokenHeaderPrefix = firstNonEmpty(existing.TokenHeaderPrefix, spec.TokenHeaderPrefix)
	out.TokenQueryKey = firstNonEmpty(existing.TokenQueryKey, spec.TokenQueryKey)
	out.PKCE = existing.PKCE || spec.PKCE
	out.AutoFetchToken = existing.AutoFetchToken || spec.AutoFetchToken
	out.AutoRefreshToken = existing.AutoRefreshToken || spec.AutoRefreshToken
	if len(existing.AuthorizationAdditionalParams) > 0 {
		out.AuthorizationAdditionalParams = append([]OAuth2AdditionalParam(nil), existing.AuthorizationAdditionalParams...)
	}
	if len(existing.TokenAdditionalParams) > 0 {
		out.TokenAdditionalParams = append([]OAuth2AdditionalParam(nil), existing.TokenAdditionalParams...)
	}
	if len(existing.RefreshAdditionalParams) > 0 {
		out.RefreshAdditionalParams = append([]OAuth2AdditionalParam(nil), existing.RefreshAdditionalParams...)
	}
	if len(existing.AdditionalParams) > 0 {
		out.AdditionalParams = append([]KeyValue(nil), existing.AdditionalParams...)
	}
	return out
}

func mergeAWSV4Preserving(existing, spec AWSV4Auth) AWSV4Auth {
	out := spec
	out.AccessKeyID = firstNonEmpty(existing.AccessKeyID, spec.AccessKeyID)
	out.SecretAccessKey = firstNonEmpty(existing.SecretAccessKey, spec.SecretAccessKey)
	out.SessionToken = firstNonEmpty(existing.SessionToken, spec.SessionToken)
	out.Service = firstNonEmpty(existing.Service, spec.Service)
	out.Region = firstNonEmpty(existing.Region, spec.Region)
	out.ProfileName = firstNonEmpty(existing.ProfileName, spec.ProfileName)
	out.AccessKey = firstNonEmpty(existing.AccessKey, spec.AccessKey)
	out.SecretKey = firstNonEmpty(existing.SecretKey, spec.SecretKey)
	return out
}

const collectionFileCacheVersion = 1

type collectionFileCacheStore struct {
	Version     int                                 `json:"version"`
	Collections map[string]collectionFileCacheEntry `json:"collections"`
}

type collectionFileCacheEntry struct {
	Fingerprint string     `json:"fingerprint"`
	Collection  Collection `json:"collection"`
	CachedAt    time.Time  `json:"cachedAt"`
}

func (a *App) readCollectionFromDiskCachedLocked(collectionPath string) (Collection, error) {
	preferences := normalizePreferences(a.state.Preferences)
	if !preferences.Cache.File.Enabled {
		return readCollectionFromDisk(collectionPath)
	}
	collectionPath = filepath.Clean(collectionPath)
	fingerprint, err := collectionFileCacheFingerprint(collectionPath)
	if err != nil {
		return Collection{}, err
	}
	store := a.readCollectionFileCacheLocked()
	if entry, ok := store.Collections[collectionPath]; ok && entry.Fingerprint == fingerprint {
		collection := entry.Collection
		collection.Path = collectionPath
		return collection, nil
	}
	collection, err := readCollectionFromDisk(collectionPath)
	if err != nil {
		return Collection{}, err
	}
	store.Collections[collectionPath] = collectionFileCacheEntry{
		Fingerprint: fingerprint,
		Collection:  collection,
		CachedAt:    time.Now(),
	}
	if err := a.writeCollectionFileCacheLocked(store); err != nil {
		return Collection{}, err
	}
	return collection, nil
}

func (a *App) collectionFileCachePathLocked() string {
	if a.dataDir == "" {
		a.dataDir = defaultDataDir()
	}
	return filepath.Join(a.dataDir, "cache", "collections.json")
}

func (a *App) readCollectionFileCacheLocked() collectionFileCacheStore {
	store := collectionFileCacheStore{
		Version:     collectionFileCacheVersion,
		Collections: map[string]collectionFileCacheEntry{},
	}
	data, err := os.ReadFile(a.collectionFileCachePathLocked())
	if err != nil {
		return store
	}
	if err := json.Unmarshal(data, &store); err != nil || store.Version != collectionFileCacheVersion {
		return collectionFileCacheStore{
			Version:     collectionFileCacheVersion,
			Collections: map[string]collectionFileCacheEntry{},
		}
	}
	if store.Collections == nil {
		store.Collections = map[string]collectionFileCacheEntry{}
	}
	return store
}

func (a *App) writeCollectionFileCacheLocked(store collectionFileCacheStore) error {
	store.Version = collectionFileCacheVersion
	if store.Collections == nil {
		store.Collections = map[string]collectionFileCacheEntry{}
	}
	data, err := json.MarshalIndent(store, "", "  ")
	if err != nil {
		return err
	}
	path := a.collectionFileCachePathLocked()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, data, 0o600)
}

func (a *App) fileCacheSizeLocked() (int64, error) {
	info, err := os.Stat(a.collectionFileCachePathLocked())
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return 0, nil
		}
		return 0, err
	}
	if info.IsDir() {
		return 0, nil
	}
	return info.Size(), nil
}

func collectionFileCacheFingerprint(collectionPath string) (string, error) {
	info, err := os.Stat(collectionPath)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		return "", fmt.Errorf("%s is not a directory", collectionPath)
	}
	parts := []string{}
	err = filepath.WalkDir(collectionPath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			base := entry.Name()
			if path != collectionPath && (base == "node_modules" || base == ".git") {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(collectionPath, path)
		if err != nil {
			return err
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		sum := sha256.Sum256(data)
		parts = append(parts, fmt.Sprintf("%s:%d:%d:%x", filepath.ToSlash(rel), info.Size(), info.ModTime().UnixNano(), sum[:]))
		return nil
	})
	if err != nil {
		return "", err
	}
	sort.Strings(parts)
	hash := sha256.New()
	for _, part := range parts {
		_, _ = io.WriteString(hash, part)
		_, _ = io.WriteString(hash, "\n")
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func collectionWatchFingerprint(collectionPath string) (string, error) {
	info, err := os.Stat(collectionPath)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		return "", fmt.Errorf("%s is not a directory", collectionPath)
	}
	ignorePatterns := collectionIgnorePatterns(collectionPath)
	parts := []string{}
	err = filepath.WalkDir(collectionPath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			if path != collectionPath && collectionPathIgnored(collectionPath, path, ignorePatterns) {
				return filepath.SkipDir
			}
			return nil
		}
		if collectionPathIgnored(collectionPath, path, ignorePatterns) {
			return nil
		}
		if !collectionWatchFileAffectsTree(collectionPath, path) {
			return nil
		}
		rel, err := filepath.Rel(collectionPath, path)
		if err != nil {
			return err
		}
		info, err := entry.Info()
		if err != nil {
			return err
		}
		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		sum := sha256.Sum256(data)
		parts = append(parts, fmt.Sprintf("%s:%d:%d:%x", filepath.ToSlash(rel), info.Size(), info.ModTime().UnixNano(), sum[:]))
		return nil
	})
	if err != nil {
		return "", err
	}
	sort.Strings(parts)
	hash := sha256.New()
	for _, part := range parts {
		_, _ = io.WriteString(hash, part)
		_, _ = io.WriteString(hash, "\n")
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func collectionIgnorePatterns(collectionPath string) []string {
	patterns := []string{"node_modules", ".git"}
	if ymlPath, ok := firstExistingCollectionYAMLPath(collectionPath); ok {
		if root, err := parseYAMLMapFile(ymlPath); err == nil {
			if extensions, ok := mapValue(root["extensions"]); ok {
				if bruno, ok := mapValue(extensions["bruno"]); ok {
					patterns = append(patterns, collectionIgnoreStringList(bruno["ignore"])...)
				}
			}
		}
		return normalizeCollectionIgnorePatterns(patterns)
	}
	configPath := filepath.Join(collectionPath, "bruno.json")
	data, err := os.ReadFile(configPath)
	if err != nil {
		return normalizeCollectionIgnorePatterns(patterns)
	}
	var config map[string]interface{}
	if err := json.Unmarshal(data, &config); err != nil {
		return normalizeCollectionIgnorePatterns(patterns)
	}
	patterns = append(patterns, collectionIgnoreStringList(config["ignore"])...)
	return normalizeCollectionIgnorePatterns(patterns)
}

func firstExistingCollectionYAMLPath(collectionPath string) (string, bool) {
	for _, name := range []string{"opencollection.yml", "opencollection.yaml"} {
		path := filepath.Join(collectionPath, name)
		if fileExists(path) {
			return path, true
		}
	}
	return "", false
}

func collectionIgnoreStringList(raw interface{}) []string {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if text := strings.TrimSpace(yamlScalarString(value)); text != "" {
			out = append(out, text)
		}
	}
	return out
}

func normalizeCollectionIgnorePatterns(patterns []string) []string {
	seen := map[string]bool{}
	out := make([]string, 0, len(patterns))
	for _, pattern := range patterns {
		pattern = strings.TrimSpace(strings.ReplaceAll(pattern, "\\", "/"))
		pattern = strings.TrimPrefix(pattern, "./")
		pattern = strings.TrimPrefix(pattern, "/")
		pattern = strings.TrimRight(pattern, "/")
		if pattern == "" || seen[pattern] {
			continue
		}
		seen[pattern] = true
		out = append(out, pattern)
	}
	return out
}

func collectionPathIgnored(collectionPath, path string, patterns []string) bool {
	rel, err := filepath.Rel(collectionPath, path)
	if err != nil || rel == "." {
		return false
	}
	rel = filepath.ToSlash(rel)
	if collectionPathHasDefaultIgnoredSegment(rel) {
		return true
	}
	for _, pattern := range patterns {
		if rel == pattern || strings.HasPrefix(rel, pattern) {
			return true
		}
	}
	return false
}

func collectionPathHasDefaultIgnoredSegment(rel string) bool {
	for _, segment := range strings.Split(filepath.ToSlash(rel), "/") {
		if segment == "node_modules" || segment == ".git" {
			return true
		}
	}
	return false
}

func collectionWatchFileAffectsTree(collectionPath, path string) bool {
	base := strings.ToLower(filepath.Base(path))
	if base == ".env" || strings.HasPrefix(base, ".env.") {
		return false
	}
	rel, err := filepath.Rel(collectionPath, path)
	if err != nil {
		return false
	}
	rel = filepath.ToSlash(rel)
	switch base {
	case "bruno.json", "collection.bru", "opencollection.yml", "opencollection.yaml", "folder.bru", "folder.yml", "folder.yaml":
		return true
	}
	ext := strings.ToLower(filepath.Ext(base))
	if strings.HasPrefix(rel, "environments/") {
		return ext == ".yml" || ext == ".yaml"
	}
	return ext == ".bru" || ext == ".yml" || ext == ".yaml"
}

func readCollectionFromDisk(collectionPath string) (Collection, error) {
	info, err := os.Stat(collectionPath)
	if err != nil {
		return Collection{}, err
	}
	if !info.IsDir() {
		return Collection{}, fmt.Errorf("%s is not a directory", collectionPath)
	}
	configName := filepath.Join(collectionPath, "bruno.json")
	name := filepath.Base(collectionPath)
	rootConfigHasName := false
	version := "1"
	format := "bru"
	if configData, err := os.ReadFile(configName); err == nil {
		var config map[string]interface{}
		if err := json.Unmarshal(configData, &config); err != nil {
			return Collection{}, fmt.Errorf("parse bruno.json: %w", err)
		}
		if configValue, ok := config["name"].(string); ok && strings.TrimSpace(configValue) != "" {
			name = configValue
			rootConfigHasName = true
		}
		if configValue := strings.TrimSpace(yamlScalarString(config["version"])); configValue != "" {
			version = configValue
		}
	}
	openCollectionConfig := filepath.Join(collectionPath, "opencollection.yml")
	if _, err := os.Stat(openCollectionConfig); err != nil {
		openCollectionConfig = filepath.Join(collectionPath, "opencollection.yaml")
	}
	if _, err := os.Stat(openCollectionConfig); err == nil {
		format = "yml"
		if root, err := parseYAMLMapFile(openCollectionConfig); err == nil {
			if value, ok := nestedString(root, "info", "name"); ok {
				name = value
				rootConfigHasName = true
			} else if value, ok := nestedString(root, "info", "title"); ok {
				name = value
				rootConfigHasName = true
			} else if value, ok := root["name"].(string); ok && strings.TrimSpace(value) != "" {
				name = value
				rootConfigHasName = true
			}
		}
	}
	collection := Collection{
		ID:             deterministicID("collection", filepath.Clean(collectionPath)),
		Name:           name,
		Version:        version,
		Path:           filepath.Clean(collectionPath),
		Format:         format,
		Auth:           AuthConfig{Mode: "none"},
		SecurityConfig: CollectionSecurityConfig{JSSandboxMode: "safe"},
		CreatedAt:      info.ModTime(),
		UpdatedAt:      time.Now(),
	}
	ignorePatterns := collectionIgnorePatterns(collectionPath)
	if configData, err := os.ReadFile(configName); err == nil {
		var config map[string]interface{}
		if err := json.Unmarshal(configData, &config); err == nil {
			if proxy, ok := parseJSONProxyConfig(config["proxy"]); ok {
				collection.Proxy = normalizeProxyConfig(proxy)
			}
			if certs, ok := parseJSONClientCertificates(config["clientCertificates"]); ok {
				collection.ClientCertificates = normalizeClientCertificates(certs)
			}
			if presets, ok := parseCollectionPresets(config["presets"]); ok {
				collection.Presets = normalizeCollectionPresets(presets)
			}
			if protobuf, ok := parseCollectionProtobuf(config["protobuf"]); ok {
				collection.Protobuf = normalizeCollectionProtobuf(collection.Path, protobuf)
			}
			if openAPI := parseOpenAPISyncConfigs(config["openapi"]); len(openAPI) > 0 {
				collection.OpenAPI = openAPI
			}
		}
	}
	if format == "yml" {
		if err := hydrateYAMLCollectionMetadata(&collection, openCollectionConfig); err != nil {
			return Collection{}, err
		}
	}
	if rootPath := filepath.Join(collectionPath, "collection.bru"); !collectionPathIgnored(collectionPath, rootPath, ignorePatterns) {
		if content, err := os.ReadFile(rootPath); err == nil {
			rootName := collection.Name
			if err := parseBruCollectionMetadata(&collection, string(content)); err != nil {
				return Collection{}, err
			}
			if rootConfigHasName {
				collection.Name = rootName
			}
		}
	}
	if environments, err := readCollectionEnvironments(collectionPath, ignorePatterns); err != nil {
		return Collection{}, err
	} else if len(environments) > 0 {
		collection.Environments = mergeEnvironments(collection.Environments, environments)
	}
	folderMap, folders := readFolderConfigs(collectionPath, ignorePatterns)
	collection.Folders = folders
	err = filepath.WalkDir(collectionPath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			if path != collectionPath && collectionPathIgnored(collectionPath, path, ignorePatterns) {
				return filepath.SkipDir
			}
			base := entry.Name()
			if base == "environments" {
				return filepath.SkipDir
			}
			return nil
		}
		if collectionPathIgnored(collectionPath, path, ignorePatterns) {
			return nil
		}
		ext := strings.ToLower(filepath.Ext(path))
		base := strings.ToLower(filepath.Base(path))
		if ext == ".bru" && base == "collection.bru" {
			return nil
		}
		if (ext == ".yml" || ext == ".yaml") && base == "opencollection.yml" {
			return nil
		}
		if isFolderMetadataFile(base) {
			return nil
		}
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		var item RequestItem
		switch ext {
		case ".bru":
			item, err = parseBru(string(content))
			if err != nil {
				return fmt.Errorf("parse %s: %w", path, err)
			}
		case ".yml", ".yaml":
			item, err = parseYAMLRequest(string(content))
			if err != nil {
				return fmt.Errorf("parse %s: %w", path, err)
			}
		default:
			return nil
		}
		if item.Type == "" || item.Type == "http" || item.Type == "graphql" || item.Type == "websocket" || item.Type == "grpc" {
			item.ID = deterministicID("request", filepath.Clean(path))
			item.FilePath = filepath.Clean(path)
			item.FolderPath = folderDisplayPath(collectionPath, path, folderMap)
			assignExampleIDs(&item)
			item.CreatedAt = info.ModTime()
			item.UpdatedAt = info.ModTime()
			collection.Items = append(collection.Items, item)
		}
		return nil
	})
	if err != nil {
		return Collection{}, err
	}
	sort.SliceStable(collection.Items, func(i, j int) bool {
		if collection.Items[i].Seq != collection.Items[j].Seq {
			return collection.Items[i].Seq < collection.Items[j].Seq
		}
		return strings.ToLower(collection.Items[i].Name) < strings.ToLower(collection.Items[j].Name)
	})
	return collection, nil
}

func readFolderConfigs(collectionPath string, ignorePatterns []string) (map[string]FolderConfig, []FolderConfig) {
	folderMap := map[string]FolderConfig{"": {Path: "", DisplayPath: ""}}
	folders := []FolderConfig{}
	_ = filepath.WalkDir(collectionPath, func(path string, entry os.DirEntry, walkErr error) error {
		if walkErr != nil {
			return nil
		}
		if !entry.IsDir() {
			return nil
		}
		if path != collectionPath && collectionPathIgnored(collectionPath, path, ignorePatterns) {
			return filepath.SkipDir
		}
		base := entry.Name()
		if base == "environments" {
			return filepath.SkipDir
		}
		rel, err := filepath.Rel(collectionPath, path)
		if err != nil || rel == "." {
			return nil
		}
		rel = filepath.ToSlash(rel)
		parentRel := filepath.ToSlash(filepath.Dir(rel))
		if parentRel == "." {
			parentRel = ""
		}
		config := readFolderConfig(path)
		if config.Name == "" {
			config.Name = filepath.Base(path)
		}
		config.Path = rel
		parentDisplay := folderMap[parentRel].DisplayPath
		if parentDisplay == "" {
			config.DisplayPath = config.Name
		} else {
			config.DisplayPath = parentDisplay + "/" + config.Name
		}
		folderMap[rel] = config
		folders = append(folders, config)
		return nil
	})
	sort.SliceStable(folders, func(i, j int) bool {
		return folders[i].DisplayPath < folders[j].DisplayPath
	})
	return folderMap, folders
}

func readFolderConfig(folderPath string) FolderConfig {
	config := FolderConfig{Auth: AuthConfig{}}
	if content, err := os.ReadFile(filepath.Join(folderPath, "folder.bru")); err == nil {
		temp := Collection{Auth: AuthConfig{}}
		_ = parseBruCollectionMetadata(&temp, string(content))
		config.Headers = temp.Headers
		config.Variables = temp.Variables
		config.ResVariables = temp.ResVariables
		config.Auth = temp.Auth
		config.PreScript = temp.PreScript
		config.PostScript = temp.PostScript
		config.Tests = temp.Tests
		config.Docs = temp.Docs
		if meta, ok := parseBruSections(string(content))["meta"]; ok {
			values := parseBruScalarMap(meta)
			config.Name = strings.TrimSpace(values["name"])
			if seq, err := strconv.Atoi(values["seq"]); err == nil && seq > 0 {
				config.Seq = seq
			}
		}
		return config
	}
	for _, name := range []string{"folder.yml", "folder.yaml"} {
		path := filepath.Join(folderPath, name)
		if root, err := parseYAMLMapFile(path); err == nil {
			if value, ok := nestedString(root, "info", "name"); ok {
				config.Name = value
			} else if value := strings.TrimSpace(yamlScalarString(root["name"])); value != "" {
				config.Name = value
			}
			if info, ok := mapValue(root["info"]); ok {
				config.Seq = intValue(info["seq"], 0)
			}
			applyYAMLFolderDefaults(&config, root)
			return config
		}
	}
	return config
}

func applyYAMLFolderDefaults(config *FolderConfig, root map[string]interface{}) {
	request, _ := mapValue(root["request"])
	if headers, ok := request["headers"]; ok {
		config.Headers = parseYAMLKeyValues(headers, false)
	}
	if variables, ok := request["variables"]; ok {
		config.Variables = parseYAMLVariables(variables)
	}
	config.ResVariables = append(config.ResVariables, parseYAMLPostResponseActions(request["actions"])...)
	if auth, ok := request["auth"]; ok {
		config.Auth = parseYAMLAuth(auth, config.Auth)
	}
	if scripts, ok := listValue(request["scripts"]); ok {
		for _, scriptValue := range scripts {
			script, ok := mapValue(scriptValue)
			if !ok {
				continue
			}
			code := yamlScalarString(script["code"])
			switch strings.ToLower(yamlScalarString(script["type"])) {
			case "before-request", "pre-request":
				config.PreScript = appendScript(config.PreScript, code)
			case "after-response", "post-response":
				config.PostScript = appendScript(config.PostScript, code)
			case "tests", "test":
				config.Tests = appendScript(config.Tests, code)
			}
		}
	}
	if docsMap, ok := mapValue(root["docs"]); ok {
		config.Docs = yamlScalarString(docsMap["content"])
	} else if docs := yamlScalarString(root["docs"]); strings.TrimSpace(docs) != "" {
		config.Docs = docs
	}
}

func folderDisplayPath(collectionPath, requestPath string, folders map[string]FolderConfig) string {
	relDir, err := filepath.Rel(collectionPath, filepath.Dir(requestPath))
	if err != nil || relDir == "." {
		return ""
	}
	relDir = filepath.ToSlash(relDir)
	if config, ok := folders[relDir]; ok && config.DisplayPath != "" {
		return config.DisplayPath
	}
	return relDir
}

func isFolderMetadataFile(base string) bool {
	return base == "folder.bru" || base == "folder.yml" || base == "folder.yaml"
}

func hydrateYAMLCollectionMetadata(collection *Collection, path string) error {
	root, err := parseYAMLMapFile(path)
	if err != nil {
		return err
	}
	request, _ := mapValue(root["request"])
	if version, ok := nestedString(root, "info", "version"); ok && strings.TrimSpace(version) != "" {
		collection.Version = version
	}
	if headers, ok := request["headers"]; ok {
		collection.Headers = parseYAMLKeyValues(headers, false)
	}
	if variables, ok := request["variables"]; ok {
		collection.Variables = parseYAMLVariables(variables)
	}
	collection.ResVariables = append(collection.ResVariables, parseYAMLPostResponseActions(request["actions"])...)
	if auth, ok := request["auth"]; ok {
		collection.Auth = parseYAMLAuth(auth, collection.Auth)
	}
	if scripts, ok := listValue(request["scripts"]); ok {
		for _, scriptValue := range scripts {
			script, ok := mapValue(scriptValue)
			if !ok {
				continue
			}
			code := yamlScalarString(script["code"])
			switch strings.ToLower(yamlScalarString(script["type"])) {
			case "before-request", "pre-request":
				collection.PreScript = appendScript(collection.PreScript, code)
			case "after-response", "post-response":
				collection.PostScript = appendScript(collection.PostScript, code)
			case "tests", "test":
				collection.Tests = appendScript(collection.Tests, code)
			}
		}
	}
	if docsMap, ok := mapValue(root["docs"]); ok {
		collection.Docs = yamlScalarString(docsMap["content"])
	} else if docs := yamlScalarString(root["docs"]); strings.TrimSpace(docs) != "" {
		collection.Docs = docs
	}
	config, _ := mapValue(root["config"])
	if environments, ok := config["environments"]; ok {
		collection.Environments = parseYAMLEnvironments(environments)
	}
	if proxy, ok := parseYAMLProxyConfig(config["proxy"]); ok {
		collection.Proxy = normalizeProxyConfig(proxy)
	}
	if certs, ok := parseYAMLClientCertificates(config["clientCertificates"]); ok {
		collection.ClientCertificates = normalizeClientCertificates(certs)
	}
	if presets, ok := parseCollectionPresets(config["presets"]); ok {
		collection.Presets = normalizeCollectionPresets(presets)
	}
	if protobuf, ok := parseCollectionProtobuf(config["protobuf"]); ok {
		collection.Protobuf = normalizeCollectionProtobuf(collection.Path, protobuf)
	}
	if extensions, ok := mapValue(root["extensions"]); ok {
		if bruno, ok := mapValue(extensions["bruno"]); ok {
			if openAPI := parseOpenAPISyncConfigs(bruno["openapi"]); len(openAPI) > 0 {
				collection.OpenAPI = openAPI
			}
		}
	}
	return nil
}

func parseYAMLMapFile(path string) (map[string]interface{}, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var raw map[string]interface{}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return nil, err
	}
	return raw, nil
}

func nestedString(raw map[string]interface{}, path ...string) (string, bool) {
	var current interface{} = raw
	for _, key := range path {
		asMap, ok := current.(map[string]interface{})
		if !ok {
			return "", false
		}
		current, ok = asMap[key]
		if !ok {
			return "", false
		}
	}
	value, ok := current.(string)
	return value, ok && strings.TrimSpace(value) != ""
}

func effectiveRequest(collection Collection, item RequestItem) RequestItem {
	effective := item
	folders := folderChain(collection, item)
	existingHeaders := map[string]bool{}
	for _, header := range effective.Headers {
		existingHeaders[strings.ToLower(header.Name)] = true
	}
	candidates := append([]KeyValue{}, collection.Headers...)
	for _, folder := range folders {
		candidates = append(candidates, folder.Headers...)
	}
	selectedReverse := []KeyValue{}
	for i := len(candidates) - 1; i >= 0; i-- {
		header := candidates[i]
		key := strings.ToLower(header.Name)
		if header.Enabled && header.Name != "" && !existingHeaders[key] {
			selectedReverse = append(selectedReverse, header)
			existingHeaders[key] = true
		}
	}
	mergedHeaders := make([]KeyValue, 0, len(selectedReverse)+len(effective.Headers))
	for i := len(selectedReverse) - 1; i >= 0; i-- {
		mergedHeaders = append(mergedHeaders, selectedReverse[i])
	}
	mergedHeaders = append(mergedHeaders, effective.Headers...)
	effective.Headers = mergedHeaders
	if effective.Auth.Mode == "inherit" || effective.Auth.Mode == "" {
		auth := collection.Auth
		for _, folder := range folders {
			if folder.Auth.Mode != "" {
				auth = folder.Auth
			}
		}
		if auth.Mode != "" {
			effective.Auth = auth
		}
	}
	return effective
}

func folderChain(collection Collection, item RequestItem) []FolderConfig {
	if len(collection.Folders) == 0 {
		return nil
	}
	targetPath := itemFolderPhysicalPath(collection, item)
	if targetPath == "" {
		return nil
	}
	byPath := map[string]FolderConfig{}
	for _, folder := range collection.Folders {
		byPath[folder.Path] = folder
	}
	parts := strings.Split(targetPath, "/")
	chain := []FolderConfig{}
	for i := range parts {
		path := strings.Join(parts[:i+1], "/")
		if folder, ok := byPath[path]; ok {
			chain = append(chain, folder)
		}
	}
	return chain
}

func itemFolderPhysicalPath(collection Collection, item RequestItem) string {
	if pathInside(collection.Path, item.FilePath) {
		rel, err := filepath.Rel(collection.Path, filepath.Dir(item.FilePath))
		if err == nil && rel != "." {
			return filepath.ToSlash(rel)
		}
	}
	return filepath.ToSlash(strings.Trim(item.FolderPath, "/"))
}

func importOpenAPI(content, fallbackName, groupBy string) (Collection, error) {
	var raw map[string]interface{}
	if err := yaml.Unmarshal([]byte(content), &raw); err != nil {
		return Collection{}, fmt.Errorf("parse openapi: %w", err)
	}
	if _, ok := raw["info"]; !ok {
		return Collection{}, errors.New("openapi info is required")
	}
	var doc openAPIDoc
	if err := yaml.Unmarshal([]byte(content), &doc); err != nil {
		return Collection{}, fmt.Errorf("parse openapi: %w", err)
	}
	name := strings.TrimSpace(doc.Info.Title)
	if name == "" {
		name = fallbackName
	}
	if name == "" {
		name = "Untitled Collection"
	}
	variables := []Variable{{ID: newID("var"), Name: "baseUrl", Value: "{{baseUrl}}", DataType: "string", Enabled: true}}
	if len(doc.Servers) > 0 && doc.Servers[0].URL != "" {
		variables = openAPIServerVariables(doc.Servers[0])
	}
	collection := Collection{
		ID:             newID("collection"),
		Name:           name,
		Format:         "openapi",
		Variables:      variables,
		Auth:           AuthConfig{Mode: "none"},
		SecurityConfig: CollectionSecurityConfig{JSSandboxMode: "safe"},
		CreatedAt:      time.Now(),
		UpdatedAt:      time.Now(),
	}
	methods := []string{"get", "post", "put", "patch", "delete", "head", "options", "trace"}
	paths := make([]string, 0, len(doc.Paths))
	for path := range doc.Paths {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	seq := 1
	for _, pathName := range paths {
		pathItem := doc.Paths[pathName]
		for _, method := range methods {
			operation, ok := pathItem.Operation(method)
			if !ok {
				continue
			}
			operations := append([]openAPIOperation{operation}, operation.BrunoVariants...)
			for _, operation := range operations {
				item := openAPIRequestItem(doc, raw, pathItem, operation, method, pathName, groupBy, "", "", nil, seq)
				collection.Items = append(collection.Items, item)
				seq++
				openAPIAppendCallbackItems(&collection, doc, raw, operation, item, groupBy, &seq)
			}
		}
	}
	openAPIAppendWebhookItems(&collection, doc, raw, groupBy, &seq)
	if len(collection.Items) == 0 {
		return Collection{}, errors.New("openapi document contains no supported operations")
	}
	return collection, nil
}

type openAPIDoc struct {
	OpenAPI  string                 `json:"openapi" yaml:"openapi"`
	Swagger  string                 `json:"swagger" yaml:"swagger"`
	Info     openAPIInfo            `json:"info" yaml:"info"`
	Servers  []openAPIServer        `json:"servers" yaml:"servers"`
	Paths    map[string]openAPIPath `json:"paths" yaml:"paths"`
	Webhooks map[string]openAPIPath `json:"webhooks" yaml:"webhooks"`
	Security []map[string][]string  `json:"security" yaml:"security"`
}

type openAPIInfo struct {
	Title   string `json:"title" yaml:"title"`
	Version string `json:"version" yaml:"version"`
}

type openAPIServer struct {
	URL       string                           `json:"url" yaml:"url"`
	Variables map[string]openAPIServerVariable `json:"variables" yaml:"variables"`
}

type openAPIServerVariable struct {
	Default interface{}   `json:"default" yaml:"default"`
	Enum    []interface{} `json:"enum" yaml:"enum"`
}

type openAPIPath struct {
	Parameters []openAPIParameter `json:"parameters" yaml:"parameters"`
	Servers    []openAPIServer    `json:"servers" yaml:"servers"`
	Get        *openAPIOperation  `json:"get" yaml:"get"`
	Post       *openAPIOperation  `json:"post" yaml:"post"`
	Put        *openAPIOperation  `json:"put" yaml:"put"`
	Patch      *openAPIOperation  `json:"patch" yaml:"patch"`
	Delete     *openAPIOperation  `json:"delete" yaml:"delete"`
	Head       *openAPIOperation  `json:"head" yaml:"head"`
	Options    *openAPIOperation  `json:"options" yaml:"options"`
	Trace      *openAPIOperation  `json:"trace" yaml:"trace"`
}

func (p openAPIPath) Operation(method string) (openAPIOperation, bool) {
	var op *openAPIOperation
	switch strings.ToLower(method) {
	case "get":
		op = p.Get
	case "post":
		op = p.Post
	case "put":
		op = p.Put
	case "patch":
		op = p.Patch
	case "delete":
		op = p.Delete
	case "head":
		op = p.Head
	case "options":
		op = p.Options
	case "trace":
		op = p.Trace
	}
	if op == nil {
		return openAPIOperation{}, false
	}
	return *op, true
}

func openAPIRequestItem(doc openAPIDoc, root map[string]interface{}, pathItem openAPIPath, operation openAPIOperation, method, pathName, groupBy, folderPrefix, urlOverride string, extraVars []Variable, seq int) RequestItem {
	item := defaultRequest(openAPIOperationName(operation, method, pathName), "http", seq)
	item.Method = strings.ToUpper(method)
	item.URL = firstNonEmpty(strings.TrimSpace(urlOverride), "{{baseUrl}}"+convertOpenAPIPath(pathName))
	if serverVars := openAPIOperationServerVariables(operation, pathItem); len(serverVars) > 0 {
		item.Vars.Req = append(item.Vars.Req, serverVars...)
	}
	item.Vars.Req = append(item.Vars.Req, extraVars...)
	item.Tags = sanitizeOpenAPITags(operation.Tags)
	item.FolderPath = openAPIJoinFolderPath(folderPrefix, openAPIFolderPath(operation, pathName, groupBy))
	params := mergeOpenAPIParams(pathItem.Parameters, operation.Parameters)
	item.PathParams = openAPIParams(params, "path")
	item.Params = openAPIParams(params, "query")
	item.Headers = openAPIParams(params, "header")
	if auth, ok := openAPIAuth(operation, doc, root); ok {
		item.Auth = auth
		item.Headers, item.Params = openAPIVisibleAuthRows(item.Auth, item.Headers, item.Params)
	}
	item.Docs = operation.Description
	if item.Docs == "" {
		item.Docs = operation.Summary
	}
	if operation.RequestBody != nil {
		if body, contentType, ok := openAPIRequestBody(operation.RequestBody, root); ok {
			item.Body = body
			if contentType != "" {
				item.Headers = appendHeaderIfMissing(item.Headers, "Content-Type", contentType)
			}
		}
	}
	if linkScript := openAPIResponseLinkScript(operation, root); linkScript != "" {
		item.PostScript = appendScript(item.PostScript, linkScript)
	}
	item.Examples = openAPIResponseExamples(operation, item, root)
	return item
}

func openAPIAppendCallbackItems(collection *Collection, doc openAPIDoc, root map[string]interface{}, operation openAPIOperation, parent RequestItem, groupBy string, seq *int) {
	if len(operation.Callbacks) == 0 {
		return
	}
	methods := []string{"get", "post", "put", "patch", "delete", "head", "options", "trace"}
	names := make([]string, 0, len(operation.Callbacks))
	for name := range operation.Callbacks {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		expressions := operation.Callbacks[name]
		keys := make([]string, 0, len(expressions))
		for expression := range expressions {
			keys = append(keys, expression)
		}
		sort.Strings(keys)
		for _, expression := range keys {
			pathItem := expressions[expression]
			urlValue, vars := openAPIEventURL(expression)
			folderPrefix := openAPIJoinFolderPath(parent.FolderPath, "Callbacks", sanitizeFilename(firstNonEmpty(name, "callback")))
			for _, method := range methods {
				callbackOperation, ok := pathItem.Operation(method)
				if !ok {
					continue
				}
				item := openAPIRequestItem(doc, root, pathItem, callbackOperation, method, expression, groupBy, folderPrefix, urlValue, vars, *seq)
				collection.Items = append(collection.Items, item)
				*seq = *seq + 1
			}
		}
	}
}

func openAPIAppendWebhookItems(collection *Collection, doc openAPIDoc, root map[string]interface{}, groupBy string, seq *int) {
	if len(doc.Webhooks) == 0 {
		return
	}
	methods := []string{"get", "post", "put", "patch", "delete", "head", "options", "trace"}
	names := make([]string, 0, len(doc.Webhooks))
	for name := range doc.Webhooks {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		pathItem := doc.Webhooks[name]
		urlValue, vars := openAPIWebhookURL(name)
		folderName := sanitizeFilename(strings.TrimPrefix(name, "/"))
		if folderName == "" || folderName == "untitled" {
			folderName = "webhook"
		}
		folderPrefix := openAPIJoinFolderPath("Webhooks", folderName)
		pathName := name
		if !strings.HasPrefix(strings.TrimSpace(pathName), "/") {
			pathName = "/webhooks/" + pathName
		}
		for _, method := range methods {
			operation, ok := pathItem.Operation(method)
			if !ok {
				continue
			}
			item := openAPIRequestItem(doc, root, pathItem, operation, method, pathName, groupBy, folderPrefix, urlValue, vars, *seq)
			collection.Items = append(collection.Items, item)
			*seq = *seq + 1
		}
	}
}

func openAPIJoinFolderPath(parts ...string) string {
	cleaned := []string{}
	for _, part := range parts {
		part = strings.Trim(strings.TrimSpace(part), "/")
		if part == "" {
			continue
		}
		cleaned = append(cleaned, part)
	}
	return strings.Join(cleaned, "/")
}

func openAPIEventURL(expression string) (string, []Variable) {
	value := strings.TrimSpace(expression)
	if value == "" {
		return "{{callbackUrl}}", []Variable{openAPIEventURLVariable("callbackUrl", expression)}
	}
	if strings.HasPrefix(value, "http://") || strings.HasPrefix(value, "https://") || strings.HasPrefix(value, "{{") {
		return value, nil
	}
	if strings.HasPrefix(value, "/") {
		return "{{baseUrl}}" + convertOpenAPIPath(value), nil
	}
	if name := openAPIEventExpressionVariableName(value); name != "" {
		return "{{" + name + "}}", []Variable{openAPIEventURLVariable(name, expression)}
	}
	return "{{" + sanitizeVariableName(firstNonEmpty(value, "callbackUrl")) + "}}", []Variable{openAPIEventURLVariable(sanitizeVariableName(firstNonEmpty(value, "callbackUrl")), expression)}
}

func openAPIWebhookURL(name string) (string, []Variable) {
	value := strings.TrimSpace(name)
	if value == "" {
		return "{{baseUrl}}/webhooks/webhook", nil
	}
	if strings.HasPrefix(value, "http://") || strings.HasPrefix(value, "https://") || strings.HasPrefix(value, "{{") {
		return value, nil
	}
	if strings.HasPrefix(value, "/") {
		return "{{baseUrl}}" + convertOpenAPIPath(value), nil
	}
	return "{{baseUrl}}" + convertOpenAPIPath("/webhooks/"+value), nil
}

func openAPIEventExpressionVariableName(expression string) string {
	inner := strings.TrimSpace(expression)
	if strings.HasPrefix(inner, "{") && strings.HasSuffix(inner, "}") {
		inner = strings.TrimSpace(strings.TrimSuffix(strings.TrimPrefix(inner, "{"), "}"))
	}
	if inner == "" {
		return ""
	}
	if strings.Contains(inner, "#/") {
		_, pointer, _ := strings.Cut(inner, "#/")
		if name := sanitizeVariableName(lastPathToken(pointer)); name != "" {
			return name
		}
	}
	if strings.Contains(inner, ".") {
		if name := sanitizeVariableName(lastPathToken(strings.ReplaceAll(inner, ".", "/"))); name != "" {
			return name
		}
	}
	return sanitizeVariableName(inner)
}

func lastPathToken(value string) string {
	parts := strings.FieldsFunc(value, func(r rune) bool {
		return r == '/' || r == '.' || r == '[' || r == ']' || r == '\'' || r == '"' || r == '#'
	})
	for index := len(parts) - 1; index >= 0; index-- {
		if strings.TrimSpace(parts[index]) != "" {
			return parts[index]
		}
	}
	return ""
}

func sanitizeVariableName(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return ""
	}
	var b strings.Builder
	upperNext := false
	for _, r := range value {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' {
			if b.Len() == 0 && r >= '0' && r <= '9' {
				b.WriteString("value")
			}
			if upperNext && r >= 'a' && r <= 'z' {
				r = r - ('a' - 'A')
			}
			b.WriteRune(r)
			upperNext = false
			continue
		}
		upperNext = b.Len() > 0
	}
	if b.Len() == 0 {
		return ""
	}
	return b.String()
}

func openAPIEventURLVariable(name, expression string) Variable {
	return Variable{
		ID:       deterministicID("var", "openapi-event-url:"+name+":"+expression),
		Name:     name,
		Value:    strings.TrimSpace(expression),
		DataType: "string",
		Enabled:  true,
	}
}

type openAPIOperation struct {
	OperationID   string                            `json:"operationId" yaml:"operationId"`
	Summary       string                            `json:"summary" yaml:"summary"`
	Description   string                            `json:"description" yaml:"description"`
	Tags          []string                          `json:"tags" yaml:"tags"`
	Parameters    []openAPIParameter                `json:"parameters" yaml:"parameters"`
	RequestBody   map[string]interface{}            `json:"requestBody" yaml:"requestBody"`
	Responses     map[string]interface{}            `json:"responses" yaml:"responses"`
	Callbacks     map[string]map[string]openAPIPath `json:"callbacks" yaml:"callbacks"`
	Security      []map[string][]string             `json:"security" yaml:"security"`
	Servers       []openAPIServer                   `json:"servers" yaml:"servers"`
	BrunoVariants []openAPIOperation                `json:"x-bruno-variants" yaml:"x-bruno-variants"`
}

type openAPIParameter struct {
	Name        string                 `json:"name" yaml:"name"`
	In          string                 `json:"in" yaml:"in"`
	Required    bool                   `json:"required" yaml:"required"`
	Description string                 `json:"description" yaml:"description"`
	Example     interface{}            `json:"example" yaml:"example"`
	Examples    map[string]interface{} `json:"examples" yaml:"examples"`
	Schema      map[string]interface{} `json:"schema" yaml:"schema"`
}

func openAPIOperationName(operation openAPIOperation, method, pathName string) string {
	if operation.Summary != "" {
		return normalizeWhitespace(operation.Summary)
	}
	if operation.OperationID != "" {
		return normalizeWhitespace(operation.OperationID)
	}
	if operation.Description != "" {
		return normalizeWhitespace(operation.Description)
	}
	return strings.ToUpper(method) + " " + pathName
}

func sanitizeOpenAPITags(tags []string) []string {
	result := make([]string, 0, len(tags))
	seen := map[string]bool{}
	for _, tag := range tags {
		cleaned := sanitizeFilename(normalizeWhitespace(tag))
		if cleaned == "" || cleaned == "untitled" || seen[cleaned] {
			continue
		}
		seen[cleaned] = true
		result = append(result, cleaned)
	}
	return result
}

func openAPIFolderPath(operation openAPIOperation, pathName, groupBy string) string {
	if strings.EqualFold(strings.TrimSpace(groupBy), "path") {
		return openAPIPathFolder(pathName)
	}
	tags := sanitizeOpenAPITags(operation.Tags)
	if len(tags) == 0 {
		return ""
	}
	return tags[0]
}

func openAPIPathFolder(pathName string) string {
	parts := strings.Split(strings.Trim(pathName, "/"), "/")
	cleaned := make([]string, 0, len(parts))
	for _, part := range parts {
		name := sanitizeFilename(part)
		if name == "" || name == "untitled" {
			continue
		}
		cleaned = append(cleaned, name)
	}
	return strings.Join(cleaned, "/")
}

func openAPIParams(params []openAPIParameter, location string) []KeyValue {
	rows := []KeyValue{}
	for _, param := range params {
		if param.In == location && param.Name != "" {
			rows = append(rows, KeyValue{Name: param.Name, Value: openAPIParameterValue(param), Enabled: param.Required, Description: param.Description})
		}
	}
	return rows
}

func openAPIParameterValue(param openAPIParameter) string {
	if value, ok := openAPIStringValue(param.Example); ok {
		return value
	}
	if value, ok := openAPIExampleValue(param.Examples); ok {
		return value
	}
	if value, ok := openAPIStringValue(firstMapValue(param.Schema, "default", "example")); ok {
		return value
	}
	if value, ok := openAPIExampleValueFromRaw(param.Schema["examples"]); ok {
		return value
	}
	if value, ok := openAPIStringValue(param.Schema["minimum"]); ok {
		return value
	}
	if strings.EqualFold(yamlScalarString(param.Schema["type"]), "array") {
		if items, ok := mapValue(param.Schema["items"]); ok {
			if value, ok := openAPIStringValue(firstMapValue(items, "default", "example", "minimum")); ok {
				return value
			}
		}
	}
	return ""
}

func openAPIExampleValueFromRaw(raw interface{}) (string, bool) {
	value, ok := openAPIExampleRawValue(raw)
	if !ok {
		return "", false
	}
	return openAPIStringValue(value)
}

func resolveOpenAPIRequestBody(raw map[string]interface{}, root map[string]interface{}) map[string]interface{} {
	if ref := yamlScalarString(raw["$ref"]); ref != "" {
		if resolved, ok := openAPIResolveRef(root, ref); ok {
			if resolvedMap, ok := mapValue(resolved); ok {
				return resolvedMap
			}
		}
	}
	return raw
}

func openAPIParameterValueFromSchema(raw interface{}) string {
	schema, ok := mapValue(raw)
	if !ok {
		return ""
	}
	if value, ok := openAPIStringValue(firstMapValue(schema, "default", "example")); ok {
		return value
	}
	if value, ok := openAPIExampleValueFromRaw(schema["examples"]); ok {
		return value
	}
	if value, ok := openAPIStringValue(schema["minimum"]); ok {
		return value
	}
	return ""
}

func openAPIAuth(operation openAPIOperation, doc openAPIDoc, root map[string]interface{}) (AuthConfig, bool) {
	security := operation.Security
	if security == nil {
		security = doc.Security
	}
	if security == nil {
		return AuthConfig{}, false
	}
	if len(security) == 0 {
		return AuthConfig{Mode: "none", APILocation: "header"}, true
	}
	for _, requirement := range security {
		if len(requirement) == 0 {
			return AuthConfig{Mode: "none", APILocation: "header"}, true
		}
		names := make([]string, 0, len(requirement))
		for name := range requirement {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			if auth, ok := openAPISecuritySchemeAuth(name, root); ok {
				return auth, true
			}
		}
	}
	return AuthConfig{}, false
}

func openAPISecuritySchemeAuth(name string, root map[string]interface{}) (AuthConfig, bool) {
	components, ok := mapValue(root["components"])
	if !ok {
		return AuthConfig{}, false
	}
	schemes, ok := mapValue(components["securitySchemes"])
	if !ok {
		return AuthConfig{}, false
	}
	scheme, ok := mapValue(schemes[name])
	if !ok {
		return AuthConfig{}, false
	}
	switch strings.ToLower(yamlScalarString(scheme["type"])) {
	case "apikey":
		location := strings.ToLower(firstNonEmpty(yamlScalarString(scheme["in"]), "header"))
		if location != "query" {
			location = "header"
		}
		return AuthConfig{Mode: "apikey", APIKey: yamlScalarString(scheme["name"]), APILocation: location}, true
	case "http":
		switch strings.ToLower(yamlScalarString(scheme["scheme"])) {
		case "bearer":
			return AuthConfig{Mode: "bearer", APILocation: "header"}, true
		case "basic":
			return AuthConfig{Mode: "basic", APILocation: "header"}, true
		case "digest":
			return AuthConfig{Mode: "digest", APILocation: "header"}, true
		}
	case "oauth2", "openidconnect":
		auth := AuthConfig{Mode: "oauth2", APILocation: "header"}
		if flows, ok := mapValue(scheme["flows"]); ok {
			if flow, ok := mapValue(firstMapValue(flows, "clientCredentials", "client_credentials", "password", "authorizationCode", "authorization_code")); ok {
				auth.OAuth2.AccessTokenURL = firstYAMLString(flow, "tokenUrl", "token_url")
				auth.OAuth2.Scope = strings.Join(openAPIScopeNames(flow["scopes"]), " ")
			}
		}
		return auth, true
	}
	return AuthConfig{}, false
}

func openAPIVisibleAuthRows(auth AuthConfig, headers, params []KeyValue) ([]KeyValue, []KeyValue) {
	if auth.Mode != "apikey" || strings.TrimSpace(auth.APIKey) == "" {
		return headers, params
	}
	row := KeyValue{Name: auth.APIKey, Value: auth.APIValue, Enabled: true}
	if strings.EqualFold(auth.APILocation, "query") {
		return headers, appendKeyValueIfMissing(params, row)
	}
	return appendKeyValueIfMissing(headers, row), params
}

func appendKeyValueIfMissing(rows []KeyValue, row KeyValue) []KeyValue {
	for _, existing := range rows {
		if strings.EqualFold(existing.Name, row.Name) {
			return rows
		}
	}
	return append(rows, row)
}

func openAPIScopeNames(raw interface{}) []string {
	scopes, ok := mapValue(raw)
	if !ok {
		return nil
	}
	names := make([]string, 0, len(scopes))
	for name := range scopes {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func openAPIRequestBody(raw map[string]interface{}, root map[string]interface{}) (RequestBody, string, bool) {
	raw = resolveOpenAPIRequestBody(raw, root)
	content, ok := mapValue(raw["content"])
	if !ok || len(content) == 0 {
		return RequestBody{}, "", false
	}
	contentType, media := openAPIPreferredMedia(content)
	if contentType == "" {
		return RequestBody{}, "", false
	}
	value := openAPIMediaExample(media, root)
	mode := openAPIBodyMode(contentType)
	body := RequestBody{Mode: mode}
	switch mode {
	case "json":
		if value == nil {
			value = map[string]interface{}{}
		}
		body.JSON = openAPIJSONString(value)
	case "xml":
		if text, ok := openAPIStringValue(value); ok {
			body.XML = text
		} else {
			body.XML = "<root></root>"
		}
	case "formUrlEncoded":
		body.FormURLEncoded = openAPIFormValues(value)
	case "multipartForm":
		body.Multipart = openAPIMultipartValues(value)
	case "text":
		body.Text, _ = openAPIStringValue(value)
	}
	return body, contentType, true
}

func openAPIPreferredMedia(content map[string]interface{}) (string, map[string]interface{}) {
	preferred := []string{"application/json", "application/*+json", "application/x-www-form-urlencoded", "multipart/form-data", "application/xml", "text/xml", "text/plain"}
	for _, mediaType := range preferred {
		if media, ok := openAPIMedia(content, mediaType); ok {
			return mediaType, media
		}
	}
	keys := make([]string, 0, len(content))
	for key := range content {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		if media, ok := mapValue(content[key]); ok {
			return key, media
		}
	}
	return "", nil
}

func openAPIMedia(content map[string]interface{}, mediaType string) (map[string]interface{}, bool) {
	if media, ok := mapValue(content[mediaType]); ok {
		return media, true
	}
	if !strings.Contains(mediaType, "*") {
		return nil, false
	}
	prefix, suffix, _ := strings.Cut(mediaType, "*")
	keys := make([]string, 0, len(content))
	for key := range content {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	for _, key := range keys {
		if strings.HasPrefix(key, prefix) && strings.HasSuffix(key, suffix) {
			if media, ok := mapValue(content[key]); ok {
				return media, true
			}
		}
	}
	return nil, false
}

func openAPIMediaExample(media map[string]interface{}, root map[string]interface{}) interface{} {
	if value, ok := media["example"]; ok {
		return value
	}
	if value, ok := openAPIExampleRawValue(media["examples"]); ok {
		return value
	}
	if schema, ok := media["schema"]; ok {
		return openAPISchemaTemplate(schema, root, map[string]bool{})
	}
	return nil
}

type openAPINamedExample struct {
	Key         string
	Name        string
	Description string
	Value       interface{}
}

func openAPIResponseExamples(operation openAPIOperation, item RequestItem, root map[string]interface{}) []ResponseExample {
	if len(operation.Responses) == 0 {
		return nil
	}
	requestExamples := openAPIRequestBodyExampleBodies(operation.RequestBody, root, item.Body.Mode)
	statuses := make([]string, 0, len(operation.Responses))
	for status := range operation.Responses {
		statuses = append(statuses, status)
	}
	sort.Strings(statuses)
	result := []ResponseExample{}
	for _, statusCode := range statuses {
		responseMap, ok := openAPIResponseMap(operation.Responses[statusCode], root)
		if !ok {
			continue
		}
		content, _ := mapValue(responseMap["content"])
		contentType, media := openAPIPreferredMedia(content)
		if contentType == "" {
			continue
		}
		bodyType := openAPIExampleBodyType(contentType)
		responseHeaders := openAPIResponseExampleHeaders(responseMap, contentType, root)
		examples := openAPIMediaNamedExamples(media, root)
		for index, example := range examples {
			body := openAPIExampleBodyString(example.Value, bodyType)
			if strings.TrimSpace(body) == "" {
				continue
			}
			status := openAPIStatusCode(statusCode)
			name := firstNonEmpty(example.Name, fmt.Sprintf("%s %s", statusCode, cleanStatusText(status, "")))
			if len(examples) > 1 && example.Key != "" && example.Name == "" {
				name = example.Key
			}
			requestBody := requestBodySnapshot(item.Body)
			if matched, ok := requestExamples[example.Key]; ok {
				requestBody = matched
			} else if len(requestExamples) == 1 {
				for _, matched := range requestExamples {
					requestBody = matched
				}
			}
			result = append(result, ResponseExample{
				ID:          deterministicID("example", item.Name+"#openapi#"+statusCode+"#"+strconv.Itoa(index)+"#"+name),
				Name:        name,
				Description: firstNonEmpty(example.Description, yamlScalarString(responseMap["description"])),
				Type:        firstNonEmpty(item.Type, "http"),
				Request: ResponseExampleRequest{
					Method:         strings.ToUpper(firstNonEmpty(item.Method, http.MethodGet)),
					URL:            item.URL,
					BodyMode:       firstNonEmpty(item.Body.Mode, "none"),
					Body:           requestBody,
					Headers:        cloneKeyValues(item.Headers),
					Params:         cloneKeyValues(item.Params),
					FormURLEncoded: cloneKeyValues(item.Body.FormURLEncoded),
					MultipartForm:  cloneFormParts(item.Body.Multipart),
					File:           cloneFileBodyEntries(fileBodyEntries(item.Body)),
				},
				Response: ResponseExamplePayload{
					Status:     status,
					StatusText: cleanStatusText(status, ""),
					Headers:    cloneKeyValues(responseHeaders),
					BodyType:   bodyType,
					Body:       body,
					Size:       len([]byte(body)),
				},
			})
		}
	}
	return result
}

func openAPIResponseExampleHeaders(responseMap map[string]interface{}, contentType string, root map[string]interface{}) []KeyValue {
	headers := []KeyValue{}
	if strings.TrimSpace(contentType) != "" {
		headers = append(headers, KeyValue{Name: "Content-Type", Value: contentType, Enabled: true})
	}
	headerMap, ok := mapValue(responseMap["headers"])
	if !ok || len(headerMap) == 0 {
		return headers
	}
	names := make([]string, 0, len(headerMap))
	for name := range headerMap {
		if strings.TrimSpace(name) == "" || strings.EqualFold(name, "Content-Type") {
			continue
		}
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		header, ok := openAPIHeaderMap(headerMap[name], root)
		if !ok {
			continue
		}
		headers = append(headers, KeyValue{
			Name:        name,
			Value:       openAPIHeaderExampleValue(header, root),
			Enabled:     true,
			Description: yamlScalarString(header["description"]),
		})
	}
	return headers
}

func openAPIHeaderMap(raw interface{}, root map[string]interface{}) (map[string]interface{}, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return nil, false
	}
	if ref := yamlScalarString(valueMap["$ref"]); ref != "" {
		if resolved, ok := openAPIResolveRef(root, ref); ok {
			return mapValue(resolved)
		}
	}
	return valueMap, true
}

func openAPIHeaderExampleValue(header map[string]interface{}, root map[string]interface{}) string {
	if value, ok := openAPIStringValue(header["example"]); ok {
		return value
	}
	if value, ok := openAPIExampleValueFromRaw(header["examples"]); ok {
		return value
	}
	if value := openAPIParameterValueFromSchema(header["schema"]); value != "" {
		return value
	}
	if template := openAPISchemaTemplate(header["schema"], root, map[string]bool{}); template != nil {
		if value, ok := openAPIStringValue(template); ok {
			return value
		}
	}
	return ""
}

func openAPIResponseMap(raw interface{}, root map[string]interface{}) (map[string]interface{}, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return nil, false
	}
	if ref := yamlScalarString(valueMap["$ref"]); ref != "" {
		if resolved, ok := openAPIResolveRef(root, ref); ok {
			return mapValue(resolved)
		}
	}
	return valueMap, true
}

func openAPIResponseLinkScript(operation openAPIOperation, root map[string]interface{}) string {
	if len(operation.Responses) == 0 {
		return ""
	}
	statuses := make([]string, 0, len(operation.Responses))
	for status := range operation.Responses {
		statuses = append(statuses, status)
	}
	sort.Strings(statuses)
	lines := []string{}
	for _, statusCode := range statuses {
		responseMap, ok := openAPIResponseMap(operation.Responses[statusCode], root)
		if !ok {
			continue
		}
		links, ok := mapValue(responseMap["links"])
		if !ok || len(links) == 0 {
			continue
		}
		status := openAPIStatusCode(statusCode)
		indent := ""
		if status > 0 {
			lines = append(lines, fmt.Sprintf("if (res.status === %d) {", status))
			indent = "  "
		}
		names := make([]string, 0, len(links))
		for name := range links {
			names = append(names, name)
		}
		sort.Strings(names)
		for _, name := range names {
			link, ok := openAPIResponseLinkMap(links[name], root)
			if !ok {
				continue
			}
			parameters, ok := mapValue(link["parameters"])
			if !ok || len(parameters) == 0 {
				continue
			}
			operationID := firstNonEmpty(yamlScalarString(link["operationId"]), name)
			paramNames := make([]string, 0, len(parameters))
			for paramName := range parameters {
				paramNames = append(paramNames, paramName)
			}
			sort.Strings(paramNames)
			for _, paramName := range paramNames {
				expression := openAPILinkExpressionToScript(parameters[paramName])
				if expression == "" {
					continue
				}
				variableName := operationID + "_" + paramName
				lines = append(lines, fmt.Sprintf("%sbru.setVar(%s, %s);", indent, jsStringLiteral(variableName), expression))
			}
		}
		if status > 0 {
			lines = append(lines, "}")
		}
	}
	return strings.Join(lines, "\n")
}

func openAPIResponseLinkMap(raw interface{}, root map[string]interface{}) (map[string]interface{}, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return nil, false
	}
	if ref := yamlScalarString(valueMap["$ref"]); ref != "" {
		if resolved, ok := openAPIResolveRef(root, ref); ok {
			return mapValue(resolved)
		}
	}
	return valueMap, true
}

func openAPILinkExpressionToScript(raw interface{}) string {
	switch value := raw.(type) {
	case string:
		return openAPIRuntimeExpressionToScript(value)
	case []byte:
		return openAPIRuntimeExpressionToScript(string(value))
	}
	if valueMap, ok := mapValue(raw); ok {
		if data, ok := valueMap["data"]; ok {
			return openAPILinkExpressionToScript(data)
		}
	}
	encoded, err := json.Marshal(raw)
	if err != nil {
		return ""
	}
	return string(encoded)
}

func openAPIRuntimeExpressionToScript(expression string) string {
	switch {
	case expression == "$response.body":
		return "res.body"
	case strings.HasPrefix(expression, "$response.body#"):
		pointer := strings.TrimPrefix(expression, "$response.body#")
		return "res.json" + openAPIJSONPointerScript(pointer)
	case expression == "$statusCode":
		return "res.status"
	case expression == "$method":
		return "req.method"
	case expression == "$url":
		return "req.url"
	case strings.HasPrefix(expression, "$response.header."):
		return "res.getHeader(" + jsStringLiteral(strings.TrimPrefix(expression, "$response.header.")) + ")"
	case strings.HasPrefix(expression, "$request.header."):
		return "req.getHeader(" + jsStringLiteral(strings.TrimPrefix(expression, "$request.header.")) + ")"
	case expression == "$request.body":
		return "req.body"
	case strings.HasPrefix(expression, "$request.body#"):
		pointer := strings.TrimPrefix(expression, "$request.body#")
		return "req.body" + openAPIJSONPointerScript(pointer)
	default:
		return jsStringLiteral(expression)
	}
}

func openAPIJSONPointerScript(pointer string) string {
	if pointer == "" {
		return ""
	}
	pointer = strings.TrimPrefix(pointer, "#")
	if pointer == "" {
		return ""
	}
	if !strings.HasPrefix(pointer, "/") {
		return ""
	}
	parts := strings.Split(strings.TrimPrefix(pointer, "/"), "/")
	var b strings.Builder
	for _, part := range parts {
		part = strings.ReplaceAll(strings.ReplaceAll(part, "~1", "/"), "~0", "~")
		if index, err := strconv.Atoi(part); err == nil && strconv.Itoa(index) == part {
			b.WriteString("[")
			b.WriteString(part)
			b.WriteString("]")
			continue
		}
		b.WriteString("[")
		b.WriteString(jsStringLiteral(part))
		b.WriteString("]")
	}
	return b.String()
}

func jsStringLiteral(value string) string {
	encoded, err := json.Marshal(value)
	if err != nil {
		return `""`
	}
	return string(encoded)
}

func openAPIMediaNamedExamples(media map[string]interface{}, root map[string]interface{}) []openAPINamedExample {
	if value, ok := media["example"]; ok {
		return []openAPINamedExample{{Key: "example", Name: "Example", Value: value}}
	}
	if examples, ok := mapValue(media["examples"]); ok && len(examples) > 0 {
		names := make([]string, 0, len(examples))
		for name := range examples {
			names = append(names, name)
		}
		sort.Strings(names)
		result := make([]openAPINamedExample, 0, len(names))
		for _, key := range names {
			named := openAPINamedExample{Key: key, Name: key, Value: examples[key]}
			if valueMap, ok := mapValue(examples[key]); ok {
				if value, ok := valueMap["value"]; ok {
					named.Value = value
				}
				named.Name = firstNonEmpty(yamlScalarString(valueMap["summary"]), key)
				named.Description = yamlScalarString(valueMap["description"])
			}
			result = append(result, named)
		}
		return result
	}
	if schema, ok := media["schema"]; ok {
		return []openAPINamedExample{{Key: "schema", Name: "Schema example", Value: openAPISchemaTemplate(schema, root, map[string]bool{})}}
	}
	return nil
}

func openAPIRequestBodyExampleBodies(raw map[string]interface{}, root map[string]interface{}, mode string) map[string]string {
	if raw == nil {
		return nil
	}
	raw = resolveOpenAPIRequestBody(raw, root)
	content, ok := mapValue(raw["content"])
	if !ok || len(content) == 0 {
		return nil
	}
	_, media := openAPIPreferredMedia(content)
	if media == nil {
		return nil
	}
	bodyType := openAPIExampleBodyType(mode)
	result := map[string]string{}
	for _, example := range openAPIMediaNamedExamples(media, root) {
		result[example.Key] = openAPIExampleBodyString(example.Value, bodyType)
	}
	return result
}

func openAPIExampleBodyType(contentTypeOrMode string) string {
	switch openAPIBodyMode(contentTypeOrMode) {
	case "json":
		return "json"
	case "xml":
		return "xml"
	default:
		if contentTypeOrMode == "json" || contentTypeOrMode == "xml" {
			return contentTypeOrMode
		}
		return "text"
	}
}

func openAPIExampleBodyString(value interface{}, bodyType string) string {
	switch bodyType {
	case "json":
		return openAPIJSONString(value)
	case "xml":
		if text, ok := openAPIStringValue(value); ok {
			return text
		}
		return "<root></root>"
	default:
		text, _ := openAPIStringValue(value)
		return text
	}
}

func openAPIStatusCode(value string) int {
	if strings.EqualFold(value, "default") {
		return 0
	}
	status, err := strconv.Atoi(value)
	if err != nil {
		return 0
	}
	return status
}

func openAPIExampleValue(examples map[string]interface{}) (string, bool) {
	value, ok := openAPIExampleRawValue(examples)
	if !ok {
		return "", false
	}
	return openAPIStringValue(value)
}

func openAPIExampleRawValue(raw interface{}) (interface{}, bool) {
	examples, ok := mapValue(raw)
	if !ok || len(examples) == 0 {
		return nil, false
	}
	names := make([]string, 0, len(examples))
	for name := range examples {
		names = append(names, name)
	}
	// Map iteration order is random, so pick the lowest-sorting name to make the
	// chosen example deterministic across runs.
	sort.Strings(names)
	first := examples[names[0]]
	if valueMap, ok := mapValue(first); ok {
		if value, ok := valueMap["value"]; ok {
			return value, true
		}
	}
	return first, true
}

func openAPISchemaTemplate(raw interface{}, root map[string]interface{}, seen map[string]bool) interface{} {
	schema, ok := mapValue(raw)
	if !ok {
		return nil
	}
	if ref := yamlScalarString(schema["$ref"]); ref != "" {
		if seen[ref] {
			return nil
		}
		seen[ref] = true
		if resolved, ok := openAPIResolveRef(root, ref); ok {
			return openAPISchemaTemplate(resolved, root, seen)
		}
	}
	if value, ok := firstMapValueOK(schema, "example", "default"); ok {
		return value
	}
	if enumValues, ok := listValue(schema["enum"]); ok && len(enumValues) > 0 {
		return enumValues[0]
	}
	if oneOf, ok := listValue(firstMapValue(schema, "oneOf", "anyOf", "allOf")); ok && len(oneOf) > 0 {
		return openAPISchemaTemplate(oneOf[0], root, seen)
	}
	schemaType := strings.ToLower(yamlScalarString(schema["type"]))
	if schemaType == "" && schema["properties"] != nil {
		schemaType = "object"
	}
	switch schemaType {
	case "object":
		result := map[string]interface{}{}
		if properties, ok := mapValue(schema["properties"]); ok {
			names := make([]string, 0, len(properties))
			for name := range properties {
				names = append(names, name)
			}
			sort.Strings(names)
			for _, name := range names {
				result[name] = openAPISchemaTemplate(properties[name], root, copyBoolMap(seen))
			}
		}
		return result
	case "array":
		return []interface{}{openAPISchemaTemplate(schema["items"], root, copyBoolMap(seen))}
	case "integer", "number":
		return 0
	case "boolean":
		return false
	case "string":
		return "string"
	default:
		return map[string]interface{}{}
	}
}

func openAPIResolveRef(root map[string]interface{}, ref string) (interface{}, bool) {
	if !strings.HasPrefix(ref, "#/") {
		return nil, false
	}
	var current interface{} = root
	for _, part := range strings.Split(strings.TrimPrefix(ref, "#/"), "/") {
		part = strings.ReplaceAll(strings.ReplaceAll(part, "~1", "/"), "~0", "~")
		currentMap, ok := mapValue(current)
		if !ok {
			return nil, false
		}
		current, ok = currentMap[part]
		if !ok {
			return nil, false
		}
	}
	return current, true
}

func firstMapValueOK(raw map[string]interface{}, keys ...string) (interface{}, bool) {
	for _, key := range keys {
		if value, ok := raw[key]; ok {
			return value, true
		}
	}
	return nil, false
}

func copyBoolMap(values map[string]bool) map[string]bool {
	out := make(map[string]bool, len(values))
	for key, value := range values {
		out[key] = value
	}
	return out
}

func openAPIJSONString(value interface{}) string {
	if text, ok := value.(string); ok && json.Valid([]byte(text)) {
		return text
	}
	data, err := json.MarshalIndent(value, "", "  ")
	if err != nil {
		return "{}"
	}
	return string(data)
}

func openAPIStringValue(raw interface{}) (string, bool) {
	if raw == nil {
		return "", false
	}
	switch value := raw.(type) {
	case string:
		return value, true
	case []byte:
		return string(value), true
	default:
		data, err := json.Marshal(value)
		if err == nil {
			return string(data), true
		}
		return fmt.Sprint(value), true
	}
}

func openAPIBodyMode(contentType string) string {
	lower := strings.ToLower(contentType)
	switch {
	case strings.Contains(lower, "json"):
		return "json"
	case strings.Contains(lower, "xml"):
		return "xml"
	case strings.Contains(lower, "x-www-form-urlencoded"):
		return "formUrlEncoded"
	case strings.Contains(lower, "multipart/form-data"):
		return "multipartForm"
	default:
		return "text"
	}
}

func openAPIFormValues(value interface{}) []KeyValue {
	valueMap, ok := mapValue(value)
	if !ok {
		return nil
	}
	names := make([]string, 0, len(valueMap))
	for name := range valueMap {
		names = append(names, name)
	}
	sort.Strings(names)
	result := make([]KeyValue, 0, len(names))
	for _, name := range names {
		text, _ := openAPIStringValue(valueMap[name])
		result = append(result, KeyValue{Name: name, Value: text, Enabled: true})
	}
	return result
}

func openAPIMultipartValues(value interface{}) []FormPart {
	valueMap, ok := mapValue(value)
	if !ok {
		return nil
	}
	names := make([]string, 0, len(valueMap))
	for name := range valueMap {
		names = append(names, name)
	}
	sort.Strings(names)
	result := make([]FormPart, 0, len(names))
	for _, name := range names {
		text, _ := openAPIStringValue(valueMap[name])
		result = append(result, FormPart{Name: name, Value: text, Enabled: true})
	}
	return result
}

func appendHeaderIfMissing(headers []KeyValue, name, value string) []KeyValue {
	for _, header := range headers {
		if strings.EqualFold(header.Name, name) {
			return headers
		}
	}
	return append(headers, KeyValue{Name: name, Value: value, Enabled: true})
}

func mergeOpenAPIParams(pathParams, operationParams []openAPIParameter) []openAPIParameter {
	merged := make([]openAPIParameter, 0, len(pathParams)+len(operationParams))
	seen := map[string]bool{}
	for _, param := range operationParams {
		key := param.In + ":" + param.Name
		seen[key] = true
		merged = append(merged, param)
	}
	for _, param := range pathParams {
		key := param.In + ":" + param.Name
		if !seen[key] {
			merged = append(merged, param)
		}
	}
	return merged
}

func convertOpenAPIPath(pathName string) string {
	parts := strings.Split(pathName, "/")
	for i, part := range parts {
		if strings.HasPrefix(part, "{") && strings.HasSuffix(part, "}") && len(part) > 2 {
			parts[i] = ":" + strings.TrimSuffix(strings.TrimPrefix(part, "{"), "}")
		}
	}
	return strings.Join(parts, "/")
}

func convertOpenAPIServerURL(rawURL string) string {
	var b strings.Builder
	for i := 0; i < len(rawURL); {
		if rawURL[i] == '{' {
			if i+1 < len(rawURL) && rawURL[i+1] == '{' {
				b.WriteByte(rawURL[i])
				i++
				continue
			}
			if endOffset := strings.IndexByte(rawURL[i+1:], '}'); endOffset >= 0 {
				end := i + 1 + endOffset
				b.WriteString("{{")
				b.WriteString(rawURL[i+1 : end])
				b.WriteString("}}")
				i = end + 1
				continue
			}
		}
		b.WriteByte(rawURL[i])
		i++
	}
	return b.String()
}

func openAPIOperationServerVariables(operation openAPIOperation, pathItem openAPIPath) []Variable {
	servers := operation.Servers
	if len(servers) == 0 {
		servers = pathItem.Servers
	}
	if len(servers) == 0 {
		return nil
	}
	return openAPIServerVariables(servers[0])
}

func openAPIServerVariables(server openAPIServer) []Variable {
	serverURL := strings.TrimRight(strings.TrimSpace(server.URL), "/")
	if serverURL == "" {
		return nil
	}
	variables := []Variable{openAPIServerVariableRow("baseUrl", convertOpenAPIServerURL(serverURL))}
	if len(server.Variables) == 0 {
		return variables
	}
	names := make([]string, 0, len(server.Variables))
	for name := range server.Variables {
		names = append(names, name)
	}
	sort.Strings(names)
	for _, name := range names {
		variables = append(variables, openAPIServerVariableRow(name, openAPIServerVariableValue(server.Variables[name])))
	}
	return variables
}

func openAPIServerVariableRow(name, value string) Variable {
	return Variable{ID: newID("var"), Name: name, Value: value, DataType: "string", Type: "string", Enabled: true}
}

func openAPIServerVariableValue(variable openAPIServerVariable) string {
	if variable.Default != nil {
		if value, ok := openAPIStringValue(variable.Default); ok {
			return value
		}
	}
	if len(variable.Enum) > 0 {
		if value, ok := openAPIStringValue(variable.Enum[0]); ok {
			return value
		}
	}
	return ""
}

func normalizeWhitespace(value string) string {
	return strings.Join(strings.Fields(value), " ")
}

func importPostman(content, name string) (Collection, error) {
	var raw struct {
		Info struct {
			Name string `json:"name"`
		} `json:"info"`
		Auth     *postmanAuth      `json:"auth"`
		Variable []postmanVariable `json:"variable"`
		Event    []postmanEvent    `json:"event"`
		Item     []postmanItem     `json:"item"`
	}
	if err := json.Unmarshal([]byte(content), &raw); err != nil {
		return Collection{}, err
	}
	if raw.Info.Name != "" {
		name = raw.Info.Name
	}
	collection := Collection{ID: newID("collection"), Name: name, Format: "postman", Auth: AuthConfig{Mode: "none"}, SecurityConfig: CollectionSecurityConfig{JSSandboxMode: "safe"}, CreatedAt: time.Now(), UpdatedAt: time.Now()}
	collection.Variables = postmanVariables(raw.Variable)
	if auth, ok := postmanAuthConfig(raw.Auth); ok {
		collection.Auth = auth
	}
	collection.PreScript, collection.PostScript = postmanEventScripts(raw.Event)
	seq := 1
	appendPostmanItems(&collection, raw.Item, "", &seq)
	return collection, nil
}

type postmanItem struct {
	Name     string            `json:"name"`
	Auth     *postmanAuth      `json:"auth"`
	Event    []postmanEvent    `json:"event"`
	Request  *postmanRequest   `json:"request"`
	Response []postmanResponse `json:"response"`
	Item     []postmanItem     `json:"item"`
}

type postmanRequest struct {
	Method string          `json:"method"`
	URL    interface{}     `json:"url"`
	Header []postmanHeader `json:"header"`
	Auth   *postmanAuth    `json:"auth"`
	Body   struct {
		Mode       string             `json:"mode"`
		Raw        string             `json:"raw"`
		URLEncoded []postmanHeader    `json:"urlencoded"`
		FormData   []postmanFormData  `json:"formdata"`
		GraphQL    postmanGraphQLBody `json:"graphql"`
		Options    postmanBodyOptions `json:"options"`
	} `json:"body"`
}

type postmanAuth struct {
	Type   string      `json:"type"`
	Basic  interface{} `json:"basic"`
	Bearer interface{} `json:"bearer"`
	APIKey interface{} `json:"apikey"`
	Digest interface{} `json:"digest"`
	AWSV4  interface{} `json:"awsv4"`
	OAuth1 interface{} `json:"oauth1"`
	OAuth2 interface{} `json:"oauth2"`
}

type postmanVariable struct {
	Key   string      `json:"key"`
	Value interface{} `json:"value"`
}

type postmanEvent struct {
	Listen string `json:"listen"`
	Script struct {
		Exec interface{} `json:"exec"`
	} `json:"script"`
}

type postmanGraphQLBody struct {
	Query     string      `json:"query"`
	Variables interface{} `json:"variables"`
}

type postmanBodyOptions struct {
	Raw struct {
		Language string `json:"language"`
	} `json:"raw"`
}

type postmanFormData struct {
	Key         string      `json:"key"`
	Value       interface{} `json:"value"`
	Type        string      `json:"type"`
	Src         interface{} `json:"src"`
	Description string      `json:"description"`
	Disabled    bool        `json:"disabled"`
}

type postmanHeader struct {
	Key         string `json:"key"`
	Value       string `json:"value"`
	Description string `json:"description"`
	Disabled    bool   `json:"disabled"`
}

type postmanResponse struct {
	Name            string          `json:"name"`
	Status          string          `json:"status"`
	Code            int             `json:"code"`
	Header          []postmanHeader `json:"header"`
	Body            string          `json:"body"`
	PreviewLanguage string          `json:"_postman_previewlanguage"`
}

func appendPostmanItems(collection *Collection, entries []postmanItem, folderPath string, seq *int) {
	for _, entry := range entries {
		if entry.Request != nil {
			item := postmanRequestItem(entry, folderPath, *seq)
			collection.Items = append(collection.Items, item)
			*seq = *seq + 1
		}
		if len(entry.Item) > 0 {
			childFolderPath := postmanFolderPath(folderPath, entry.Name)
			appendPostmanFolder(collection, entry, childFolderPath)
			appendPostmanItems(collection, entry.Item, childFolderPath, seq)
		}
	}
}

func postmanRequestItem(entry postmanItem, folderPath string, seq int) RequestItem {
	item := defaultRequest(entry.Name, "http", seq)
	item.FolderPath = folderPath
	item.Auth = AuthConfig{Mode: "inherit", APILocation: "header"}
	if entry.Request == nil {
		return item
	}
	item.Method = strings.ToUpper(firstNonEmpty(entry.Request.Method, http.MethodGet))
	item.URL = postmanURL(entry.Request.URL)
	item.Headers = postmanKeyValues(entry.Request.Header, false)
	item.Params = postmanURLParams(entry.Request.URL)
	item.PathParams = postmanURLPathParams(entry.Request.URL)
	item.Body = postmanRequestBody(*entry.Request, item.Headers)
	if auth, ok := postmanAuthConfig(entry.Request.Auth); ok {
		item.Auth = auth
	}
	item.PreScript, item.PostScript = postmanEventScripts(entry.Event)
	if item.Body.Mode == "graphql" {
		item.Type = "graphql"
	}
	item.Examples = postmanResponseExamples(entry.Response, item)
	return item
}

func appendPostmanFolder(collection *Collection, entry postmanItem, folderPath string) {
	if folderPath == "" {
		return
	}
	folder := FolderConfig{
		Path:        folderPath,
		DisplayPath: folderPath,
		Name:        firstNonEmpty(strings.TrimSpace(entry.Name), "Untitled Folder"),
		Seq:         len(collection.Folders) + 1,
	}
	if auth, ok := postmanAuthConfig(entry.Auth); ok {
		folder.Auth = auth
	}
	folder.PreScript, folder.PostScript = postmanEventScripts(entry.Event)
	collection.Folders = append(collection.Folders, folder)
}

func postmanAuthConfig(auth *postmanAuth) (AuthConfig, bool) {
	if auth == nil {
		return AuthConfig{}, false
	}
	switch strings.ToLower(strings.TrimSpace(auth.Type)) {
	case "noauth":
		return AuthConfig{Mode: "none", APILocation: "header"}, true
	case "basic":
		return AuthConfig{Mode: "basic", Username: postmanAuthValue(auth.Basic, "username"), Password: postmanAuthValue(auth.Basic, "password"), APILocation: "header"}, true
	case "bearer":
		return AuthConfig{Mode: "bearer", Token: postmanAuthValue(auth.Bearer, "token"), APILocation: "header"}, true
	case "apikey":
		location := strings.ToLower(firstNonEmpty(postmanAuthValue(auth.APIKey, "in"), "header"))
		if location != "query" {
			location = "header"
		}
		return AuthConfig{Mode: "apikey", APIKey: postmanAuthValue(auth.APIKey, "key"), APIValue: postmanAuthValue(auth.APIKey, "value"), APILocation: location}, true
	case "digest":
		return AuthConfig{Mode: "digest", Username: postmanAuthValue(auth.Digest, "username"), Password: postmanAuthValue(auth.Digest, "password"), APILocation: "header"}, true
	case "awsv4":
		return AuthConfig{
			Mode:        "awsv4",
			APILocation: "header",
			AWSV4: AWSV4Auth{
				AccessKeyID:     postmanAuthValue(auth.AWSV4, "accessKey"),
				SecretAccessKey: postmanAuthValue(auth.AWSV4, "secretKey"),
				SessionToken:    postmanAuthValue(auth.AWSV4, "sessionToken"),
				Service:         postmanAuthValue(auth.AWSV4, "service"),
				Region:          postmanAuthValue(auth.AWSV4, "region"),
			},
		}, true
	case "oauth1":
		placement := "header"
		if !postmanAuthBoolValue(auth.OAuth1, "addParamsToHeader", true) {
			placement = "query"
		}
		return AuthConfig{
			Mode:        "oauth1",
			APILocation: "header",
			OAuth1: OAuth1Auth{
				ConsumerKey:       postmanAuthValue(auth.OAuth1, "consumerKey"),
				ConsumerSecret:    postmanAuthValue(auth.OAuth1, "consumerSecret"),
				AccessToken:       postmanAuthValue(auth.OAuth1, "token"),
				AccessTokenSecret: postmanAuthValue(auth.OAuth1, "tokenSecret"),
				CallbackURL:       postmanAuthValue(auth.OAuth1, "callback"),
				Verifier:          postmanAuthValue(auth.OAuth1, "verifier"),
				SignatureMethod:   firstNonEmpty(postmanAuthValue(auth.OAuth1, "signatureMethod"), "HMAC-SHA1"),
				PrivateKey:        postmanAuthValue(auth.OAuth1, "privateKey"),
				PrivateKeyType:    "text",
				Timestamp:         postmanAuthValue(auth.OAuth1, "timestamp"),
				Nonce:             postmanAuthValue(auth.OAuth1, "nonce"),
				Version:           firstNonEmpty(postmanAuthValue(auth.OAuth1, "version"), "1.0"),
				Realm:             postmanAuthValue(auth.OAuth1, "realm"),
				Placement:         placement,
				IncludeBodyHash:   postmanAuthBoolValue(auth.OAuth1, "includeBodyHash", false),
			},
		}, true
	case "oauth2":
		return AuthConfig{Mode: "oauth2", APILocation: "header", OAuth2: postmanOAuth2Auth(auth.OAuth2)}, true
	}
	return AuthConfig{}, false
}

func postmanAuthValue(values interface{}, key string) string {
	raw, ok := postmanAuthRawValue(values, key)
	if !ok {
		return ""
	}
	return yamlScalarString(raw)
}

func postmanAuthRawValue(values interface{}, key string) (interface{}, bool) {
	if valueMap, ok := mapValue(values); ok {
		value, exists := valueMap[key]
		return value, exists
	}
	if valueList, ok := listValue(values); ok {
		for _, raw := range valueList {
			valueMap, ok := mapValue(raw)
			if !ok {
				continue
			}
			if yamlScalarString(valueMap["key"]) == key {
				value, exists := valueMap["value"]
				return value, exists
			}
		}
	}
	return nil, false
}

func postmanAuthBoolValue(values interface{}, key string, fallback bool) bool {
	raw, ok := postmanAuthRawValue(values, key)
	if !ok {
		return fallback
	}
	switch value := raw.(type) {
	case bool:
		return value
	case string:
		if parsed, err := strconv.ParseBool(strings.TrimSpace(value)); err == nil {
			return parsed
		}
	}
	switch strings.ToLower(strings.TrimSpace(yamlScalarString(raw))) {
	case "true", "1", "yes", "on":
		return true
	case "false", "0", "no", "off":
		return false
	}
	return fallback
}

func postmanOAuth2Auth(values interface{}) OAuth2Auth {
	postmanGrantType := postmanAuthValue(values, "grant_type")
	grantType := mapPostmanOAuth2GrantType(postmanGrantType)
	tokenPlacement := "url"
	if postmanAuthValue(values, "addTokenTo") == "header" {
		tokenPlacement = "header"
	}
	credentialsPlacement := "basic_auth_header"
	if postmanAuthValue(values, "client_authentication") == "body" {
		credentialsPlacement = "body"
	}
	auth := OAuth2Auth{
		GrantType:            grantType,
		AccessTokenURL:       postmanAuthValue(values, "accessTokenUrl"),
		RefreshTokenURL:      postmanAuthValue(values, "refreshTokenUrl"),
		ClientID:             postmanAuthValue(values, "clientId"),
		ClientSecret:         postmanAuthValue(values, "clientSecret"),
		Scope:                postmanAuthValue(values, "scope"),
		State:                postmanAuthValue(values, "state"),
		TokenPlacement:       tokenPlacement,
		TokenHeaderPrefix:    postmanAuthValue(values, "headerPrefix"),
		TokenQueryKey:        "access_token",
		CredentialsPlacement: credentialsPlacement,
	}
	switch postmanGrantType {
	case "authorization_code":
		auth.AuthorizationURL = postmanAuthValue(values, "authUrl")
		auth.CallbackURL = postmanAuthValue(values, "redirect_uri")
	case "authorization_code_with_pkce":
		auth.AuthorizationURL = postmanAuthValue(values, "authUrl")
		auth.CallbackURL = postmanAuthValue(values, "redirect_uri")
		auth.PKCE = true
	case "password_credentials":
		auth.Username = postmanAuthValue(values, "username")
		auth.Password = postmanAuthValue(values, "password")
	case "implicit":
		auth.AuthorizationURL = postmanAuthValue(values, "authUrl")
		auth.CallbackURL = postmanAuthValue(values, "redirect_uri")
	}
	return auth
}

func mapPostmanOAuth2GrantType(grantType string) string {
	switch grantType {
	case "authorization_code", "authorization_code_with_pkce":
		return "authorization_code"
	case "client_credentials":
		return "client_credentials"
	case "password_credentials":
		return "password"
	case "implicit":
		return "implicit"
	default:
		return "client_credentials"
	}
}

func postmanVariables(values []postmanVariable) []Variable {
	variables := make([]Variable, 0, len(values))
	for _, value := range values {
		if value.Key == "" && value.Value == nil {
			continue
		}
		name := postmanVariableName(value.Key)
		if name == "" {
			continue
		}
		variables = append(variables, Variable{
			ID:       newID("var"),
			Name:     name,
			Value:    yamlScalarString(value.Value),
			Type:     "string",
			DataType: "string",
			Enabled:  true,
		})
	}
	return variables
}

func postmanVariableName(name string) string {
	var b strings.Builder
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r >= '0' && r <= '9', r == '_', r == '-', r == '.':
			b.WriteRune(r)
		default:
			b.WriteByte('_')
		}
	}
	return b.String()
}

func postmanEventScripts(events []postmanEvent) (string, string) {
	preScripts := []string{}
	postScripts := []string{}
	for _, event := range events {
		script := postmanScriptText(event.Script.Exec)
		if strings.TrimSpace(script) == "" {
			continue
		}
		switch strings.ToLower(strings.TrimSpace(event.Listen)) {
		case "prerequest", "pre-request":
			preScripts = append(preScripts, script)
		case "test", "tests":
			postScripts = append(postScripts, script)
		}
	}
	return strings.Join(preScripts, "\n"), strings.Join(postScripts, "\n")
}

func postmanScriptText(raw interface{}) string {
	var script string
	switch value := raw.(type) {
	case string:
		script = value
	case []interface{}:
		lines := make([]string, 0, len(value))
		for _, line := range value {
			lines = append(lines, yamlScalarString(line))
		}
		script = strings.Join(lines, "\n")
	case []string:
		script = strings.Join(value, "\n")
	default:
		script = yamlScalarString(raw)
	}
	return postmanTranslateScript(script)
}

func postmanTranslateScript(script string) string {
	replacements := []struct {
		from string
		to   string
	}{
		{"pm.variables.get", "bru.getVar"},
		{"pm.variables.set", "bru.setVar"},
		{"pm.variables.unset", "bru.deleteVar"},
		{"pm.variables.replaceIn", "bru.interpolate"},
		{"pm.environment.get", "bru.getVar"},
		{"pm.environment.set", "bru.setVar"},
		{"pm.environment.unset", "bru.deleteVar"},
		{"pm.environment.replaceIn", "bru.interpolate"},
		{"pm.collectionVariables.get", "bru.getVar"},
		{"pm.collectionVariables.set", "bru.setVar"},
		{"pm.collectionVariables.unset", "bru.deleteVar"},
		{"pm.collectionVariables.replaceIn", "bru.interpolate"},
		{"pm.globals.get", "bru.getVar"},
		{"pm.globals.set", "bru.setVar"},
		{"pm.globals.unset", "bru.deleteVar"},
		{"pm.globals.replaceIn", "bru.interpolate"},
		{"pm.test", "test"},
		{"pm.expect", "expect"},
		{"pm.cookies.get", "bru.cookies.get"},
		{"pm.cookies.has", "bru.cookies.has"},
		{"pm.cookies.toObject", "bru.cookies.toObject"},
		{"pm.cookies.toString", "bru.cookies.toString"},
		{"pm.cookies.all", "bru.cookies.all"},
		{"pm.cookies.count", "bru.cookies.count"},
		{"pm.getResponseHeader", "res.getHeader"},
		{"pm.response.headers.has", "res.headerList.has"},
		{"pm.response.headers.one", "res.headerList.one"},
		{"pm.response.headers.all", "res.headerList.all"},
		{"pm.response.headers.count", "res.headerList.count"},
		{"pm.response.headers.indexOf", "res.headerList.indexOf"},
		{"pm.response.headers.find", "res.headerList.find"},
		{"pm.response.headers.filter", "res.headerList.filter"},
		{"pm.response.headers.each", "res.headerList.each"},
		{"pm.response.headers.map", "res.headerList.map"},
		{"pm.response.headers.reduce", "res.headerList.reduce"},
		{"pm.response.headers.toObject", "res.headerList.toObject"},
		{"pm.response.headers.toString", "res.headerList.toString"},
		{"pm.response.headers.toJSON", "res.headerList.toJSON"},
		{"pm.response.headers.get", "res.getHeader"},
		{"pm.response.headers", "res.headers"},
		{"pm.response.text()", "res.body"},
		{"pm.response.json()", "res.json"},
		{"pm.response.code", "res.status"},
		{"pm.response.statusText", "res.statusText"},
		{"pm.response.status", "res.statusText"},
		{"pm.request.headers.has", "req.headerList.has"},
		{"pm.request.headers.one", "req.headerList.one"},
		{"pm.request.headers.all", "req.headerList.all"},
		{"pm.request.headers.count", "req.headerList.count"},
		{"pm.request.headers.indexOf", "req.headerList.indexOf"},
		{"pm.request.headers.find", "req.headerList.find"},
		{"pm.request.headers.filter", "req.headerList.filter"},
		{"pm.request.headers.each", "req.headerList.each"},
		{"pm.request.headers.map", "req.headerList.map"},
		{"pm.request.headers.reduce", "req.headerList.reduce"},
		{"pm.request.headers.toObject", "req.headerList.toObject"},
		{"pm.request.headers.toString", "req.headerList.toString"},
		{"pm.request.headers.toJSON", "req.headerList.toJSON"},
		{"pm.request.headers.get", "req.getHeader"},
		{"pm.request.headers.remove", "req.deleteHeader"},
		{"pm.request.url", "req.getUrl()"},
		{"pm.request.method", "req.getMethod()"},
		{"pm.request.body", "req.body"},
	}
	translated := script
	for _, replacement := range replacements {
		translated = strings.ReplaceAll(translated, replacement.from, replacement.to)
	}
	translated = regexp.MustCompile(`pm\.response\.to\.have\.status\(([^)]*)\)`).ReplaceAllString(translated, `expect(res.status).to.equal($1)`)
	translated = regexp.MustCompile(`pm\.response\.to\.not\.have\.status\(([^)]*)\)`).ReplaceAllString(translated, `expect(res.status).not.to.equal($1)`)
	translated = regexp.MustCompile(`pm\.response\.to\.have\.header\(([^)]*)\)`).ReplaceAllString(translated, `expect(res.getHeader($1)).not.to.equal("")`)
	translated = regexp.MustCompile(`pm\.request\.headers\.(?:add|upsert)\(\s*\{\s*key\s*:\s*([^,}]+)\s*,\s*value\s*:\s*([^}]+)\}\s*\)`).ReplaceAllString(translated, `req.setHeader($1, $2)`)
	return translated
}

func postmanFolderPath(parent, name string) string {
	cleaned := sanitizeFilename(normalizeWhitespace(name))
	if cleaned == "" || cleaned == "untitled" {
		return parent
	}
	if parent == "" {
		return cleaned
	}
	return parent + "/" + cleaned
}

func postmanURL(value interface{}) string {
	switch v := value.(type) {
	case string:
		return v
	case map[string]interface{}:
		if raw, ok := v["raw"].(string); ok {
			return raw
		}
	}
	return "{{host}}"
}

func postmanURLParams(value interface{}) []KeyValue {
	urlMap, ok := mapValue(value)
	if !ok {
		return nil
	}
	params := []KeyValue{}
	if query, ok := listValue(urlMap["query"]); ok {
		params = append(params, postmanParamRows(query, false)...)
	}
	return params
}

func postmanURLPathParams(value interface{}) []KeyValue {
	urlMap, ok := mapValue(value)
	if !ok {
		return nil
	}
	params := []KeyValue{}
	if variables, ok := listValue(urlMap["variable"]); ok {
		params = append(params, postmanParamRows(variables, true)...)
	}
	return params
}

func postmanParamRows(values []interface{}, forceEnabled bool) []KeyValue {
	rows := make([]KeyValue, 0, len(values))
	for _, raw := range values {
		valueMap, ok := mapValue(raw)
		if !ok {
			continue
		}
		name := yamlScalarString(firstMapValue(valueMap, "key", "name"))
		value := yamlScalarString(valueMap["value"])
		if name == "" && value == "" {
			continue
		}
		enabled := !boolValue(valueMap["disabled"], false)
		if forceEnabled {
			enabled = true
		}
		rows = append(rows, KeyValue{Name: name, Value: value, Description: yamlScalarString(valueMap["description"]), Enabled: enabled})
	}
	return rows
}

func postmanRequestBody(request postmanRequest, headers []KeyValue) RequestBody {
	body := RequestBody{Mode: "none"}
	switch strings.ToLower(strings.TrimSpace(request.Body.Mode)) {
	case "raw":
		mode := postmanRawBodyMode(headers, request.Body.Options.Raw.Language, request.Body.Raw)
		body.Mode = mode
		switch mode {
		case "json":
			body.JSON = request.Body.Raw
		case "xml":
			body.XML = request.Body.Raw
		default:
			body.Text = request.Body.Raw
		}
	case "urlencoded":
		body.Mode = "formUrlEncoded"
		body.FormURLEncoded = postmanKeyValues(request.Body.URLEncoded, false)
	case "formdata":
		body.Mode = "multipartForm"
		body.Multipart = postmanMultipartValues(request.Body.FormData)
	case "graphql":
		body.Mode = "graphql"
		body.GraphQLQuery = request.Body.GraphQL.Query
		body.GraphQLVariables = postmanGraphQLVariablesString(request.Body.GraphQL.Variables)
	}
	return body
}

func postmanGraphQLVariablesString(value interface{}) string {
	if value == nil {
		return ""
	}
	if text, ok := value.(string); ok {
		return text
	}
	return openAPIJSONString(value)
}

func postmanRawBodyMode(headers []KeyValue, language, raw string) string {
	switch strings.ToLower(strings.TrimSpace(language)) {
	case "json":
		return "json"
	case "xml":
		return "xml"
	case "text", "html", "javascript":
		return "text"
	}
	if contentType := getKeyValue(headers, "Content-Type"); contentType != "" {
		return openAPIExampleBodyType(contentType)
	}
	trimmed := strings.TrimSpace(raw)
	if json.Valid([]byte(trimmed)) {
		return "json"
	}
	if strings.HasPrefix(trimmed, "<") {
		return "xml"
	}
	return "text"
}

func postmanMultipartValues(values []postmanFormData) []FormPart {
	parts := make([]FormPart, 0, len(values))
	for _, value := range values {
		if value.Key == "" && value.Value == nil && value.Src == nil {
			continue
		}
		part := FormPart{Name: value.Key, Enabled: !value.Disabled}
		if strings.EqualFold(value.Type, "file") || (strings.EqualFold(value.Type, "default") && value.Src != nil) {
			part.FilePath = postmanFormDataString(value.Src)
		} else {
			part.Value = postmanFormDataString(value.Value)
		}
		parts = append(parts, part)
	}
	return parts
}

func postmanFormDataString(value interface{}) string {
	if values, ok := listValue(value); ok {
		parts := make([]string, 0, len(values))
		for _, raw := range values {
			parts = append(parts, yamlScalarString(raw))
		}
		return strings.Join(parts, "")
	}
	return yamlScalarString(value)
}

func postmanResponseExamples(responses []postmanResponse, item RequestItem) []ResponseExample {
	examples := make([]ResponseExample, 0, len(responses))
	for index, response := range responses {
		headers := postmanKeyValues(response.Header, true)
		bodyType := postmanResponseBodyType(headers, response.PreviewLanguage, response.Body)
		statusText := firstNonEmpty(response.Status, cleanStatusText(response.Code, ""))
		name := firstNonEmpty(response.Name, strings.TrimSpace(fmt.Sprintf("%d %s", response.Code, statusText)))
		if strings.TrimSpace(name) == "" {
			name = fmt.Sprintf("Response %d", index+1)
		}
		examples = append(examples, ResponseExample{
			ID:   deterministicID("example", item.Name+"#postman#"+strconv.Itoa(index)+"#"+name),
			Name: name,
			Type: firstNonEmpty(item.Type, "http"),
			Request: ResponseExampleRequest{
				Method:         strings.ToUpper(firstNonEmpty(item.Method, http.MethodGet)),
				URL:            item.URL,
				BodyMode:       firstNonEmpty(item.Body.Mode, "none"),
				Body:           requestBodySnapshot(item.Body),
				Headers:        cloneKeyValues(item.Headers),
				Params:         cloneKeyValues(item.Params),
				FormURLEncoded: cloneKeyValues(item.Body.FormURLEncoded),
				MultipartForm:  cloneFormParts(item.Body.Multipart),
				File:           cloneFileBodyEntries(fileBodyEntries(item.Body)),
			},
			Response: ResponseExamplePayload{
				Status:     response.Code,
				StatusText: statusText,
				Headers:    headers,
				BodyType:   bodyType,
				Body:       response.Body,
				Size:       len([]byte(response.Body)),
			},
		})
	}
	return examples
}

func postmanKeyValues(headers []postmanHeader, responseHeaders bool) []KeyValue {
	rows := make([]KeyValue, 0, len(headers))
	for _, header := range headers {
		if header.Key == "" && header.Value == "" {
			continue
		}
		enabled := !header.Disabled
		if responseHeaders {
			enabled = true
		}
		rows = append(rows, KeyValue{Name: header.Key, Value: header.Value, Description: header.Description, Enabled: enabled})
	}
	return rows
}

func postmanResponseBodyType(headers []KeyValue, previewLanguage, body string) string {
	if contentType := getKeyValue(headers, "Content-Type"); contentType != "" {
		return openAPIExampleBodyType(contentType)
	}
	switch strings.ToLower(strings.TrimSpace(previewLanguage)) {
	case "json":
		return "json"
	case "xml":
		return "xml"
	}
	if json.Valid([]byte(strings.TrimSpace(body))) {
		return "json"
	}
	if strings.HasPrefix(strings.TrimSpace(body), "<") {
		return "xml"
	}
	return "text"
}

type insomniaExport struct {
	Type         string              `json:"type" yaml:"type"`
	Name         string              `json:"name" yaml:"name"`
	Collection   []insomniaV5Item    `json:"collection" yaml:"collection"`
	Environments insomniaEnvironment `json:"environments" yaml:"environments"`
	Resources    []insomniaResource  `json:"resources" yaml:"resources"`
}

type insomniaResource struct {
	ID             string                 `json:"_id" yaml:"_id"`
	Type           string                 `json:"_type" yaml:"_type"`
	ParentID       string                 `json:"parentId" yaml:"parentId"`
	Name           string                 `json:"name" yaml:"name"`
	Method         string                 `json:"method" yaml:"method"`
	URL            string                 `json:"url" yaml:"url"`
	Headers        []insomniaNameValue    `json:"headers" yaml:"headers"`
	Parameters     []insomniaNameValue    `json:"parameters" yaml:"parameters"`
	PathParameters []insomniaNameValue    `json:"pathParameters" yaml:"pathParameters"`
	Authentication insomniaAuth           `json:"authentication" yaml:"authentication"`
	Body           insomniaBody           `json:"body" yaml:"body"`
	Data           map[string]interface{} `json:"data" yaml:"data"`
}

type insomniaV5Item struct {
	Name           string              `json:"name" yaml:"name"`
	Method         string              `json:"method" yaml:"method"`
	URL            string              `json:"url" yaml:"url"`
	Headers        []insomniaNameValue `json:"headers" yaml:"headers"`
	Parameters     []insomniaNameValue `json:"parameters" yaml:"parameters"`
	PathParameters []insomniaNameValue `json:"pathParameters" yaml:"pathParameters"`
	Authentication insomniaAuth        `json:"authentication" yaml:"authentication"`
	Body           insomniaBody        `json:"body" yaml:"body"`
	Children       []insomniaV5Item    `json:"children" yaml:"children"`
}

type insomniaNameValue struct {
	Name        string      `json:"name" yaml:"name"`
	Value       interface{} `json:"value" yaml:"value"`
	Description string      `json:"description" yaml:"description"`
	Disabled    bool        `json:"disabled" yaml:"disabled"`
}

type insomniaAuth struct {
	Type     string `json:"type" yaml:"type"`
	Username string `json:"username" yaml:"username"`
	Password string `json:"password" yaml:"password"`
	Token    string `json:"token" yaml:"token"`
}

type insomniaBody struct {
	MimeType string              `json:"mimeType" yaml:"mimeType"`
	Text     string              `json:"text" yaml:"text"`
	Params   []insomniaNameValue `json:"params" yaml:"params"`
}

type insomniaEnvironment struct {
	Name            string                 `json:"name" yaml:"name"`
	ParentID        string                 `json:"parentId" yaml:"parentId"`
	Data            map[string]interface{} `json:"data" yaml:"data"`
	SubEnvironments []insomniaEnvironment  `json:"subEnvironments" yaml:"subEnvironments"`
}

func importInsomnia(content, fallbackName string) (Collection, error) {
	var raw insomniaExport
	if err := yaml.Unmarshal([]byte(content), &raw); err != nil {
		return Collection{}, err
	}
	now := time.Now()
	collection := Collection{
		ID:             newID("collection"),
		Name:           firstNonEmpty(strings.TrimSpace(raw.Name), strings.TrimSpace(fallbackName), "Insomnia Collection"),
		Format:         "insomnia",
		Auth:           AuthConfig{Mode: "none"},
		SecurityConfig: CollectionSecurityConfig{JSSandboxMode: "safe"},
		CreatedAt:      now,
		UpdatedAt:      now,
	}
	seq := 1
	if strings.HasPrefix(raw.Type, "collection.insomnia.rest/5") || len(raw.Collection) > 0 {
		appendInsomniaV5Items(&collection, raw.Collection, "", &seq)
		collection.Environments = insomniaV5Environments(raw.Environments)
		return collection, nil
	}
	workspace := insomniaWorkspace(raw.Resources)
	if workspace.ID == "" {
		return Collection{}, errors.New("collection not found inside Insomnia export")
	}
	collection.Name = firstNonEmpty(strings.TrimSpace(workspace.Name), collection.Name)
	appendInsomniaV4Items(&collection, raw.Resources, workspace.ID, "", &seq)
	collection.Environments = insomniaV4Environments(raw.Resources, workspace.ID)
	return collection, nil
}

func appendInsomniaV4Items(collection *Collection, resources []insomniaResource, parentID, folderPath string, seq *int) {
	for _, folder := range insomniaChildFolders(resources, parentID) {
		childPath := postmanFolderPath(folderPath, folder.Name)
		appendInsomniaFolder(collection, folder.Name, childPath)
		appendInsomniaV4Items(collection, resources, folder.ID, childPath, seq)
	}
	for _, request := range insomniaChildRequests(resources, parentID) {
		item := insomniaRequestItem(insomniaRequestData{
			Name:           request.Name,
			Method:         request.Method,
			URL:            request.URL,
			Headers:        request.Headers,
			Parameters:     request.Parameters,
			PathParameters: request.PathParameters,
			Authentication: request.Authentication,
			Body:           request.Body,
		}, folderPath, *seq)
		collection.Items = append(collection.Items, item)
		*seq = *seq + 1
	}
}

func appendInsomniaV5Items(collection *Collection, items []insomniaV5Item, folderPath string, seq *int) {
	for _, raw := range items {
		if len(raw.Children) > 0 {
			childPath := postmanFolderPath(folderPath, raw.Name)
			appendInsomniaFolder(collection, raw.Name, childPath)
			appendInsomniaV5Items(collection, raw.Children, childPath, seq)
			continue
		}
		if strings.TrimSpace(raw.Method) == "" && strings.TrimSpace(raw.URL) == "" {
			continue
		}
		item := insomniaRequestItem(insomniaRequestData{
			Name:           raw.Name,
			Method:         raw.Method,
			URL:            raw.URL,
			Headers:        raw.Headers,
			Parameters:     raw.Parameters,
			PathParameters: raw.PathParameters,
			Authentication: raw.Authentication,
			Body:           raw.Body,
		}, folderPath, *seq)
		collection.Items = append(collection.Items, item)
		*seq = *seq + 1
	}
}

type insomniaRequestData struct {
	Name           string
	Method         string
	URL            string
	Headers        []insomniaNameValue
	Parameters     []insomniaNameValue
	PathParameters []insomniaNameValue
	Authentication insomniaAuth
	Body           insomniaBody
}

func insomniaRequestItem(request insomniaRequestData, folderPath string, seq int) RequestItem {
	item := defaultRequest(firstNonEmpty(request.Name, "Untitled Request"), "http", seq)
	item.FolderPath = folderPath
	item.Method = strings.ToUpper(firstNonEmpty(request.Method, http.MethodGet))
	item.URL = insomniaNormalizeVariables(request.URL)
	item.Headers = insomniaKeyValues(request.Headers, false)
	item.Params = insomniaKeyValues(request.Parameters, false)
	item.PathParams = insomniaPathParams(request.PathParameters)
	item.Auth = insomniaAuthConfig(request.Authentication)
	item.Body = insomniaRequestBody(request.Body)
	if item.Body.Mode == "graphql" {
		item.Type = "graphql"
	}
	return item
}

func appendInsomniaFolder(collection *Collection, name, folderPath string) {
	if folderPath == "" {
		return
	}
	collection.Folders = append(collection.Folders, FolderConfig{
		Path:        folderPath,
		DisplayPath: folderPath,
		Name:        firstNonEmpty(strings.TrimSpace(name), "Untitled Folder"),
		Seq:         len(collection.Folders) + 1,
	})
}

func insomniaWorkspace(resources []insomniaResource) insomniaResource {
	for _, resource := range resources {
		if resource.Type == "workspace" {
			return resource
		}
	}
	return insomniaResource{}
}

func insomniaChildFolders(resources []insomniaResource, parentID string) []insomniaResource {
	result := []insomniaResource{}
	for _, resource := range resources {
		if resource.Type == "request_group" && resource.ParentID == parentID {
			result = append(result, resource)
		}
	}
	return result
}

func insomniaChildRequests(resources []insomniaResource, parentID string) []insomniaResource {
	result := []insomniaResource{}
	for _, resource := range resources {
		if resource.Type == "request" && resource.ParentID == parentID {
			result = append(result, resource)
		}
	}
	return result
}

func insomniaKeyValues(values []insomniaNameValue, forceEnabled bool) []KeyValue {
	rows := make([]KeyValue, 0, len(values))
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" && value.Value == nil {
			continue
		}
		enabled := !value.Disabled
		if forceEnabled {
			enabled = true
		}
		rows = append(rows, KeyValue{
			Name:        value.Name,
			Value:       insomniaNormalizeVariables(yamlScalarString(value.Value)),
			Enabled:     enabled,
			Description: value.Description,
		})
	}
	return rows
}

func insomniaPathParams(values []insomniaNameValue) []KeyValue {
	rows := make([]KeyValue, 0, len(values))
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" && value.Value == nil {
			continue
		}
		rows = append(rows, KeyValue{
			Name:        value.Name,
			Value:       insomniaNormalizeVariables(yamlScalarString(value.Value)),
			Enabled:     true,
			Description: value.Description,
		})
	}
	return rows
}

func insomniaAuthConfig(auth insomniaAuth) AuthConfig {
	switch strings.ToLower(strings.TrimSpace(auth.Type)) {
	case "basic":
		return AuthConfig{Mode: "basic", Username: insomniaNormalizeVariables(auth.Username), Password: insomniaNormalizeVariables(auth.Password), APILocation: "header"}
	case "bearer":
		return AuthConfig{Mode: "bearer", Token: insomniaNormalizeVariables(auth.Token), APILocation: "header"}
	default:
		return AuthConfig{Mode: "none", APILocation: "header"}
	}
}

func insomniaRequestBody(body insomniaBody) RequestBody {
	result := RequestBody{Mode: "none"}
	mimeType := strings.ToLower(strings.TrimSpace(strings.Split(body.MimeType, ";")[0]))
	text := insomniaNormalizeVariables(body.Text)
	switch {
	case mimeType == "application/json":
		result.Mode = "json"
		result.JSON = text
	case mimeType == "application/x-www-form-urlencoded":
		result.Mode = "formUrlEncoded"
		result.FormURLEncoded = insomniaKeyValues(body.Params, false)
	case mimeType == "multipart/form-data":
		result.Mode = "multipartForm"
		result.Multipart = insomniaMultipartValues(body.Params)
	case mimeType == "text/xml" || mimeType == "application/xml":
		result.Mode = "xml"
		result.XML = text
	case mimeType == "application/graphql":
		result.Mode = "graphql"
		result.GraphQLQuery, result.GraphQLVariables = insomniaGraphQLBody(text)
	case mimeType == "text/plain" || (mimeType == "" && strings.TrimSpace(text) != ""):
		result.Mode = "text"
		result.Text = text
	}
	return result
}

func insomniaMultipartValues(values []insomniaNameValue) []FormPart {
	parts := make([]FormPart, 0, len(values))
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" && value.Value == nil {
			continue
		}
		parts = append(parts, FormPart{Name: value.Name, Value: insomniaNormalizeVariables(yamlScalarString(value.Value)), Enabled: !value.Disabled})
	}
	return parts
}

func insomniaGraphQLBody(text string) (string, string) {
	payload := map[string]interface{}{}
	if err := json.Unmarshal([]byte(text), &payload); err != nil {
		return "", ""
	}
	query := insomniaNormalizeVariables(yamlScalarString(payload["query"]))
	variables := ""
	if rawVars, ok := payload["variables"]; ok {
		if data, err := json.MarshalIndent(rawVars, "", "  "); err == nil {
			variables = string(data)
		}
	}
	return query, variables
}

func insomniaV4Environments(resources []insomniaResource, workspaceID string) []Environment {
	envs := []insomniaEnvironment{}
	var base insomniaEnvironment
	for _, resource := range resources {
		if resource.Type != "environment" {
			continue
		}
		env := insomniaEnvironment{Name: resource.Name, ParentID: resource.ParentID, Data: resource.Data}
		if resource.ParentID == workspaceID && base.Data == nil {
			base = env
			envs = append(envs, env)
		}
	}
	baseFlat := flattenInsomniaEnv(base.Data)
	for _, resource := range resources {
		if resource.Type != "environment" || resource.ParentID == workspaceID {
			continue
		}
		merged := map[string]interface{}{}
		for key, value := range baseFlat {
			merged[key] = value
		}
		for key, value := range flattenInsomniaEnv(resource.Data) {
			merged[key] = value
		}
		envs = append(envs, insomniaEnvironment{Name: resource.Name, Data: merged})
	}
	return insomniaEnvironments(envs)
}

func insomniaV5Environments(base insomniaEnvironment) []Environment {
	if base.Data == nil && len(base.SubEnvironments) == 0 && strings.TrimSpace(base.Name) == "" {
		return nil
	}
	envs := []insomniaEnvironment{base}
	baseFlat := flattenInsomniaEnv(base.Data)
	for _, sub := range base.SubEnvironments {
		merged := map[string]interface{}{}
		for key, value := range baseFlat {
			merged[key] = value
		}
		for key, value := range flattenInsomniaEnv(sub.Data) {
			merged[key] = value
		}
		envs = append(envs, insomniaEnvironment{Name: sub.Name, Data: merged})
	}
	return insomniaEnvironments(envs)
}

func insomniaEnvironments(values []insomniaEnvironment) []Environment {
	result := make([]Environment, 0, len(values))
	for index, env := range values {
		flat := flattenInsomniaEnv(env.Data)
		names := make([]string, 0, len(flat))
		for name := range flat {
			names = append(names, name)
		}
		sort.Strings(names)
		variables := make([]Variable, 0, len(names))
		for _, name := range names {
			variables = append(variables, Variable{
				ID:       newID("var"),
				Name:     name,
				Value:    yamlScalarString(flat[name]),
				Type:     "text",
				DataType: "string",
				Enabled:  true,
			})
		}
		result = append(result, Environment{
			ID:        newID("env"),
			Name:      firstNonEmpty(strings.TrimSpace(env.Name), fmt.Sprintf("Environment %d", index+1)),
			Variables: variables,
		})
	}
	return result
}

func flattenInsomniaEnv(values map[string]interface{}) map[string]interface{} {
	result := map[string]interface{}{}
	var walk func(prefix string, raw interface{})
	walk = func(prefix string, raw interface{}) {
		if valueMap, ok := mapValue(raw); ok {
			keys := make([]string, 0, len(valueMap))
			for key := range valueMap {
				keys = append(keys, key)
			}
			sort.Strings(keys)
			for _, key := range keys {
				next := key
				if prefix != "" {
					next = prefix + "." + key
				}
				walk(next, valueMap[key])
			}
			return
		}
		if prefix != "" {
			result[prefix] = raw
		}
	}
	walk("", values)
	return result
}

func insomniaNormalizeVariables(value string) string {
	return regexp.MustCompile(`\{\{.*?\}\}`).ReplaceAllStringFunc(value, func(match string) string {
		cleaned := strings.ReplaceAll(match, "_.", "")
		cleaned = strings.ReplaceAll(cleaned, " ", "")
		return cleaned
	})
}

func parseYAMLRequest(content string) (RequestItem, error) {
	var raw map[string]interface{}
	if err := yaml.Unmarshal([]byte(content), &raw); err != nil {
		return RequestItem{}, err
	}
	info, ok := mapValue(raw["info"])
	if !ok {
		return RequestItem{}, errors.New("yaml info is required")
	}
	name := strings.TrimSpace(yamlScalarString(info["name"]))
	if name == "" {
		name = "Imported request"
	}
	requestType := strings.ToLower(strings.TrimSpace(yamlScalarString(info["type"])))
	if requestType == "" {
		requestType = "http"
	}
	seq := intValue(info["seq"], 1)
	item := defaultRequest(name, requestType, seq)
	item.Auth = AuthConfig{Mode: "none", APILocation: "header"}

	switch requestType {
	case "graphql":
		if section, ok := mapValue(raw["graphql"]); ok {
			applyYAMLGraphQL(&item, section)
		}
	case "websocket":
		if section, ok := mapValue(raw["websocket"]); ok {
			applyYAMLWebSocket(&item, section)
		}
	case "grpc":
		if section, ok := mapValue(raw["grpc"]); ok {
			applyYAMLGrpc(&item, section)
		}
	default:
		if section, ok := mapValue(raw["http"]); ok {
			applyYAMLHTTP(&item, section)
		}
	}

	if runtime, ok := mapValue(raw["runtime"]); ok {
		if variables, ok := runtime["variables"]; ok {
			item.Vars.Req = parseYAMLVariables(variables)
		}
		item.Vars.Res = append(item.Vars.Res, parseYAMLPostResponseActions(runtime["actions"])...)
		if scripts, ok := listValue(runtime["scripts"]); ok {
			for _, scriptValue := range scripts {
				script, ok := mapValue(scriptValue)
				if !ok {
					continue
				}
				code := yamlScalarString(script["code"])
				switch strings.ToLower(yamlScalarString(script["type"])) {
				case "before-request", "pre-request":
					item.PreScript = appendScript(item.PreScript, code)
				case "after-response", "post-response":
					item.PostScript = appendScript(item.PostScript, code)
				case "tests", "test":
					item.Tests = appendScript(item.Tests, code)
				}
			}
		}
	}
	if settings, ok := mapValue(raw["settings"]); ok {
		applyYAMLSettings(&item, settings)
	}
	if docs := strings.TrimSpace(yamlScalarString(raw["docs"])); docs != "" {
		item.Docs = docs
	}
	return item, nil
}

func applyYAMLHTTP(item *RequestItem, section map[string]interface{}) {
	if method := strings.TrimSpace(yamlScalarString(section["method"])); method != "" {
		item.Method = strings.ToUpper(method)
	}
	if targetURL := strings.TrimSpace(yamlScalarString(section["url"])); targetURL != "" {
		item.URL = targetURL
	}
	if headers, ok := section["headers"]; ok {
		item.Headers = parseYAMLKeyValues(headers, false)
	}
	if params, ok := section["params"]; ok {
		item.Params, item.PathParams = parseYAMLParams(params)
	}
	if body, ok := section["body"]; ok {
		item.Body = parseYAMLBody(body)
	}
	if auth, ok := section["auth"]; ok {
		item.Auth = parseYAMLAuth(auth, item.Auth)
	}
}

func applyYAMLGraphQL(item *RequestItem, section map[string]interface{}) {
	if method := strings.TrimSpace(yamlScalarString(section["method"])); method != "" {
		item.Method = strings.ToUpper(method)
	}
	if targetURL := strings.TrimSpace(yamlScalarString(section["url"])); targetURL != "" {
		item.URL = targetURL
	}
	item.Body.Mode = "graphql"
	if body, ok := mapValue(section["body"]); ok {
		item.Body.GraphQLQuery = yamlScalarString(body["query"])
		item.Body.GraphQLVariables = yamlScalarString(body["variables"])
	}
	if headers, ok := section["headers"]; ok {
		item.Headers = parseYAMLKeyValues(headers, false)
	}
	if auth, ok := section["auth"]; ok {
		item.Auth = parseYAMLAuth(auth, item.Auth)
	}
}

func applyYAMLWebSocket(item *RequestItem, section map[string]interface{}) {
	item.Body.Mode = "ws"
	if targetURL := strings.TrimSpace(yamlScalarString(section["url"])); targetURL != "" {
		item.URL = targetURL
	}
	if headers, ok := section["headers"]; ok {
		item.Headers = parseYAMLKeyValues(headers, false)
	}
	if rawMessage := firstMapValue(section, "message", "messages"); rawMessage != nil {
		item.WSMessages = parseYAMLWSMessages(rawMessage)
		if len(item.WSMessages) == 0 {
			if message, ok := mapValue(rawMessage); ok {
				mode := normalizeBodyMode(yamlScalarString(message["type"]))
				item.Body.Mode = mode
				assignYAMLBodyData(&item.Body, mode, message["data"])
			}
		}
	}
	if auth, ok := section["auth"]; ok {
		item.Auth = parseYAMLAuth(auth, item.Auth)
	}
}

func applyYAMLGrpc(item *RequestItem, section map[string]interface{}) {
	item.Type = "grpc"
	item.Body.Mode = "grpc"
	if method := strings.TrimSpace(yamlScalarString(section["method"])); method != "" {
		item.Method = method
	}
	if targetURL := strings.TrimSpace(yamlScalarString(section["url"])); targetURL != "" {
		item.URL = targetURL
	}
	item.GrpcMethodType = firstYAMLString(section, "methodType", "method_type")
	item.ProtoPath = firstYAMLString(section, "protoFilePath", "protoPath", "proto_file_path")
	if metadata, ok := section["metadata"]; ok {
		item.Headers = parseYAMLKeyValues(metadata, false)
	} else if headers, ok := section["headers"]; ok {
		item.Headers = parseYAMLKeyValues(headers, false)
	}
	item.GrpcMessages = parseYAMLGrpcMessages(firstMapValue(section, "message", "messages"))
	if auth, ok := section["auth"]; ok {
		item.Auth = parseYAMLAuth(auth, item.Auth)
	}
}

func parseYAMLBody(raw interface{}) RequestBody {
	body := RequestBody{Mode: "none"}
	bodyMap, ok := mapValue(raw)
	if !ok {
		body.Mode = "text"
		body.Text = yamlScalarString(raw)
		return body
	}
	mode := normalizeBodyMode(yamlScalarString(bodyMap["type"]))
	body.Mode = mode
	assignYAMLBodyData(&body, mode, bodyMap["data"])
	return body
}

func assignYAMLBodyData(body *RequestBody, mode string, data interface{}) {
	switch mode {
	case "json":
		body.JSON = yamlScalarString(data)
	case "xml":
		body.XML = yamlScalarString(data)
	case "formUrlEncoded":
		body.FormURLEncoded = parseYAMLKeyValues(data, false)
	case "multipartForm":
		body.Multipart = parseYAMLMultipart(data)
	case "file":
		body.Files = parseYAMLFileBody(data)
		body.FilePath, body.FileContentType = selectedFileBodyFields(body.Files)
	case "none", "":
		body.Mode = "none"
	default:
		body.Text = yamlScalarString(data)
	}
}

func parseYAMLFileBody(raw interface{}) []FileBodyEntry {
	if values, ok := listValue(raw); ok {
		result := make([]FileBodyEntry, 0, len(values))
		for _, entry := range values {
			valueMap, ok := mapValue(entry)
			if !ok {
				continue
			}
			filePath := firstYAMLString(valueMap, "filePath", "path", "value")
			contentType := firstYAMLString(valueMap, "contentType", "content_type")
			if strings.TrimSpace(filePath) == "" && strings.TrimSpace(contentType) == "" {
				continue
			}
			result = append(result, FileBodyEntry{
				FilePath:    filePath,
				ContentType: contentType,
				Selected:    boolValue(valueMap["selected"], false),
			})
		}
		return result
	}
	if filePath := yamlScalarString(raw); strings.TrimSpace(filePath) != "" {
		return []FileBodyEntry{{FilePath: filePath, Selected: true}}
	}
	return nil
}

func normalizeBodyMode(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "", "none":
		return "none"
	case "json":
		return "json"
	case "xml":
		return "xml"
	case "sparql":
		return "sparql"
	case "grpc":
		return "grpc"
	case "form-urlencoded", "formurlencoded", "urlencoded", "x-www-form-urlencoded":
		return "formUrlEncoded"
	case "multipart-form", "multipartform", "multipart":
		return "multipartForm"
	case "file", "binary":
		return "file"
	default:
		return "text"
	}
}

func normalizeWSMessageType(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "json":
		return "json"
	case "xml":
		return "xml"
	case "binary", "bin":
		return "binary"
	default:
		return "text"
	}
}

func parseYAMLKeyValues(raw interface{}, queryOnly bool) []KeyValue {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	result := make([]KeyValue, 0, len(values))
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		if queryOnly {
			paramType := strings.ToLower(yamlScalarString(valueMap["type"]))
			if paramType != "" && paramType != "query" {
				continue
			}
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		enabled := yamlEnabled(valueMap)
		result = append(result, KeyValue{
			Name:        name,
			Value:       yamlScalarString(valueMap["value"]),
			Enabled:     enabled,
			Secret:      boolValue(valueMap["secret"], false),
			Description: yamlScalarString(valueMap["description"]),
		})
	}
	return result
}

func parseYAMLParams(raw interface{}) ([]KeyValue, []KeyValue) {
	values, ok := listValue(raw)
	if !ok {
		return nil, nil
	}
	queryParams := []KeyValue{}
	pathParams := []KeyValue{}
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		param := KeyValue{
			Name:        name,
			Value:       yamlScalarString(valueMap["value"]),
			Enabled:     yamlEnabled(valueMap),
			Secret:      boolValue(valueMap["secret"], false),
			Description: yamlScalarString(valueMap["description"]),
		}
		switch strings.ToLower(yamlScalarString(valueMap["type"])) {
		case "path":
			pathParams = append(pathParams, param)
		default:
			queryParams = append(queryParams, param)
		}
	}
	return queryParams, pathParams
}

func parseYAMLWSMessages(raw interface{}) []WSMessage {
	if raw == nil {
		return nil
	}
	if values, ok := listValue(raw); ok {
		result := make([]WSMessage, 0, len(values))
		for index, entry := range values {
			message, ok := parseYAMLWSMessage(entry, index)
			if ok {
				result = append(result, message)
			}
		}
		return result
	}
	if message, ok := parseYAMLWSMessage(raw, 0); ok {
		return []WSMessage{message}
	}
	return nil
}

func parseYAMLWSMessage(raw interface{}, index int) (WSMessage, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		content := yamlScalarString(raw)
		if strings.TrimSpace(content) == "" {
			return WSMessage{}, false
		}
		return WSMessage{Name: fmt.Sprintf("message %d", index+1), Type: "text", Content: content}, true
	}
	name := firstYAMLString(valueMap, "title", "name")
	selected := boolValue(valueMap["selected"], false)
	messageMap := valueMap
	fromVariant := false
	if nested, ok := mapValue(valueMap["message"]); ok {
		messageMap = nested
		fromVariant = true
	}
	content := firstYAMLString(messageMap, "data", "content", "message", "value")
	messageType := normalizeWSMessageType(firstYAMLString(messageMap, "type"))
	if strings.TrimSpace(name) == "" && strings.TrimSpace(content) == "" {
		return WSMessage{}, false
	}
	if strings.TrimSpace(name) == "" && fromVariant {
		name = fmt.Sprintf("message %d", index+1)
	}
	return WSMessage{Name: name, Type: messageType, Content: content, Selected: selected}, true
}

func parseYAMLGrpcMessages(raw interface{}) []GrpcMessage {
	if raw == nil {
		return nil
	}
	if values, ok := listValue(raw); ok {
		result := make([]GrpcMessage, 0, len(values))
		for index, entry := range values {
			if valueMap, ok := mapValue(entry); ok {
				name := firstYAMLString(valueMap, "title", "name")
				content := firstYAMLString(valueMap, "message", "content", "value")
				if strings.TrimSpace(name) == "" && strings.TrimSpace(content) == "" {
					continue
				}
				if strings.TrimSpace(name) == "" {
					name = fmt.Sprintf("message %d", index+1)
				}
				result = append(result, GrpcMessage{Name: name, Content: content})
				continue
			}
			content := yamlScalarString(entry)
			if strings.TrimSpace(content) != "" {
				result = append(result, GrpcMessage{Name: fmt.Sprintf("message %d", index+1), Content: content})
			}
		}
		return result
	}
	if valueMap, ok := mapValue(raw); ok {
		name := firstYAMLString(valueMap, "title", "name")
		content := firstYAMLString(valueMap, "message", "content", "value")
		if strings.TrimSpace(name) == "" && strings.TrimSpace(content) == "" {
			return nil
		}
		return []GrpcMessage{{Name: name, Content: content}}
	}
	content := yamlScalarString(raw)
	if strings.TrimSpace(content) == "" {
		return nil
	}
	return []GrpcMessage{{Content: content}}
}

func parseYAMLOAuth2AdditionalGroup(raw interface{}) []OAuth2AdditionalParam {
	if valueMap, ok := mapValue(raw); ok {
		result := []OAuth2AdditionalParam{}
		result = append(result, parseYAMLOAuth2AdditionalParams(firstMapValue(valueMap, "headers", "header"), "headers")...)
		result = append(result, parseYAMLOAuth2AdditionalParams(firstMapValue(valueMap, "queryparams", "queryParams", "query", "params"), "queryparams")...)
		result = append(result, parseYAMLOAuth2AdditionalParams(firstMapValue(valueMap, "body", "form", "formData"), "body")...)
		return result
	}
	return parseYAMLOAuth2AdditionalParams(raw, "body")
}

func parseYAMLOAuth2AdditionalParams(raw interface{}, fallbackSendIn string) []OAuth2AdditionalParam {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	result := make([]OAuth2AdditionalParam, 0, len(values))
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		sendIn := firstYAMLString(valueMap, "sendIn", "send_in", "placement", "type")
		if sendIn == "" {
			sendIn = fallbackSendIn
		}
		result = append(result, OAuth2AdditionalParam{
			Name:        name,
			Value:       yamlScalarString(valueMap["value"]),
			SendIn:      normalizeOAuth2AdditionalPlacement(sendIn),
			Enabled:     yamlEnabled(valueMap),
			Secret:      boolValue(valueMap["secret"], false),
			Description: yamlScalarString(valueMap["description"]),
		})
	}
	return result
}

func parseYAMLMultipart(raw interface{}) []FormPart {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	parts := make([]FormPart, 0, len(values))
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		part := FormPart{Name: name, Enabled: yamlEnabled(valueMap)}
		part.ContentType = firstYAMLString(valueMap, "contentType", "content_type")
		partType := strings.ToLower(yamlScalarString(valueMap["type"]))
		if partType == "file" {
			part.FilePath = firstYAMLString(valueMap, "filePath", "path", "value")
		} else {
			part.Value = yamlScalarString(valueMap["value"])
		}
		parts = append(parts, part)
	}
	return parts
}

func parseYAMLVariables(raw interface{}) []Variable {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	variables := make([]Variable, 0, len(values))
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		value, dataType := parseYAMLTypedValue(valueMap["value"])
		if dataType == "string" {
			if topLevelType := strings.ToLower(strings.TrimSpace(yamlScalarString(valueMap["type"]))); topLevelType != "" {
				dataType = topLevelType
			}
		}
		variables = append(variables, Variable{
			ID:       newID("var"),
			Name:     name,
			Value:    value,
			DataType: dataType,
			Type:     dataType,
			Enabled:  yamlEnabled(valueMap),
			Secret:   boolValue(valueMap["secret"], false),
		})
	}
	return variables
}

func parseYAMLPostResponseActions(raw interface{}) []Variable {
	actions, ok := listValue(raw)
	if !ok {
		return nil
	}
	variables := make([]Variable, 0, len(actions))
	for _, actionValue := range actions {
		action, ok := mapValue(actionValue)
		if !ok {
			continue
		}
		if !strings.EqualFold(yamlScalarString(action["type"]), "set-variable") {
			continue
		}
		phase := strings.ToLower(strings.TrimSpace(yamlScalarString(action["phase"])))
		if phase != "after-response" && phase != "post-response" {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(action["name"]))
		secret := boolValue(action["secret"], false)
		if variable, ok := mapValue(action["variable"]); ok {
			if variableName := strings.TrimSpace(yamlScalarString(variable["name"])); variableName != "" {
				name = variableName
			}
			secret = boolValue(variable["secret"], secret)
		}
		if name == "" {
			continue
		}
		valueRaw := action["value"]
		if selector, ok := mapValue(action["selector"]); ok {
			if expression, ok := selector["expression"]; ok {
				valueRaw = expression
			}
		}
		value, dataType := parseYAMLTypedValue(valueRaw)
		if dataType == "string" {
			dataType = "response"
		}
		variables = append(variables, Variable{
			ID:       newID("var"),
			Name:     responseVariableRuntimeName(name),
			Value:    value,
			DataType: dataType,
			Type:     dataType,
			Enabled:  yamlEnabled(action),
			Secret:   secret,
		})
	}
	return variables
}

func parseYAMLEnvironments(raw interface{}) []Environment {
	values, ok := listValue(raw)
	if !ok {
		return nil
	}
	environments := make([]Environment, 0, len(values))
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			continue
		}
		environments = append(environments, Environment{
			ID:        newID("env"),
			Name:      name,
			Color:     yamlScalarString(valueMap["color"]),
			Variables: parseYAMLVariables(valueMap["variables"]),
		})
	}
	return environments
}

func parseYAMLTypedValue(raw interface{}) (interface{}, string) {
	if valueMap, ok := mapValue(raw); ok {
		dataType := strings.ToLower(strings.TrimSpace(yamlScalarString(valueMap["type"])))
		data := valueMap["data"]
		switch dataType {
		case "number":
			text := yamlScalarString(data)
			if strings.ContainsAny(text, ".eE") {
				if parsed, err := strconv.ParseFloat(text, 64); err == nil {
					return parsed, "number"
				}
			}
			if parsed, err := strconv.Atoi(text); err == nil {
				return parsed, "number"
			}
			return text, "number"
		case "boolean":
			if parsed, err := strconv.ParseBool(yamlScalarString(data)); err == nil {
				return parsed, "boolean"
			}
			return yamlScalarString(data), "boolean"
		case "object":
			return yamlScalarString(data), "object"
		case "":
			return yamlScalarString(data), "string"
		default:
			return yamlScalarString(data), dataType
		}
	}
	switch v := raw.(type) {
	case bool:
		return v, "boolean"
	case int, int8, int16, int32, int64, float32, float64:
		return v, "number"
	case nil:
		return "", "string"
	default:
		return yamlScalarString(v), "string"
	}
}

func parseYAMLAuth(raw interface{}, fallback AuthConfig) AuthConfig {
	auth := fallback
	if auth.Mode == "" {
		auth.Mode = "none"
	}
	if auth.APILocation == "" {
		auth.APILocation = "header"
	}
	if valueMap, ok := mapValue(raw); ok {
		mode := strings.ToLower(firstYAMLString(valueMap, "mode", "type", "auth"))
		if mode != "" {
			auth.Mode = mode
		}
		auth.Username = firstYAMLString(valueMap, "username", "user")
		auth.Password = firstYAMLString(valueMap, "password", "pass")
		auth.Domain = firstYAMLString(valueMap, "domain")
		if nested, ok := mapValue(valueMap["wsse"]); ok {
			auth.Username = firstYAMLString(nested, "username", "user")
			auth.Password = firstYAMLString(nested, "password", "pass")
		}
		if nested, ok := mapValue(valueMap["ntlm"]); ok {
			auth.Username = firstYAMLString(nested, "username", "user")
			auth.Password = firstYAMLString(nested, "password", "pass")
			auth.Domain = firstYAMLString(nested, "domain")
		}
		auth.Token = firstYAMLString(valueMap, "token", "bearerToken", "accessToken")
		auth.APIKey = firstYAMLString(valueMap, "key", "apiKey", "name")
		auth.APIValue = firstYAMLString(valueMap, "value", "apiValue")
		if location := firstYAMLString(valueMap, "location", "placement"); location != "" {
			auth.APILocation = strings.ToLower(location)
		}
		oauth2Map := valueMap
		if nested, ok := mapValue(valueMap["oauth2"]); ok {
			oauth2Map = nested
		}
		auth.OAuth2.GrantType = firstYAMLString(oauth2Map, "grantType", "grant_type", "flow")
		auth.OAuth2.CallbackURL = firstYAMLString(oauth2Map, "callbackUrl", "callback_url")
		auth.OAuth2.AuthorizationURL = firstYAMLString(oauth2Map, "authorizationUrl", "authorization_url", "authUrl", "auth_url")
		auth.OAuth2.AccessTokenURL = firstYAMLString(oauth2Map, "accessTokenUrl", "access_token_url", "tokenUrl", "token_url")
		auth.OAuth2.RefreshTokenURL = firstYAMLString(oauth2Map, "refreshTokenUrl", "refresh_token_url")
		auth.OAuth2.Username = firstYAMLString(oauth2Map, "username", "user")
		auth.OAuth2.Password = firstYAMLString(oauth2Map, "password", "pass")
		auth.OAuth2.ClientID = firstYAMLString(oauth2Map, "clientId", "client_id")
		auth.OAuth2.ClientSecret = firstYAMLString(oauth2Map, "clientSecret", "client_secret")
		auth.OAuth2.Scope = firstYAMLString(oauth2Map, "scope")
		auth.OAuth2.State = firstYAMLString(oauth2Map, "state")
		if pkce, ok := boolValueOK(oauth2Map["pkce"]); ok {
			auth.OAuth2.PKCE = pkce
		}
		auth.OAuth2.CredentialsPlacement = firstYAMLString(oauth2Map, "credentialsPlacement", "credentials_placement")
		auth.OAuth2.CredentialsID = firstYAMLString(oauth2Map, "credentialsId", "credentials_id")
		auth.OAuth2.TokenSource = firstYAMLString(oauth2Map, "tokenSource", "token_source")
		auth.OAuth2.TokenPlacement = firstYAMLString(oauth2Map, "tokenPlacement", "token_placement")
		auth.OAuth2.TokenHeaderPrefix = firstYAMLString(oauth2Map, "tokenHeaderPrefix", "token_header_prefix")
		auth.OAuth2.TokenQueryKey = firstYAMLString(oauth2Map, "tokenQueryKey", "token_query_key")
		if autoFetchToken, ok := boolValueOK(oauth2Map["autoFetchToken"]); ok {
			auth.OAuth2.AutoFetchToken = autoFetchToken
		} else if autoFetchToken, ok := boolValueOK(oauth2Map["auto_fetch_token"]); ok {
			auth.OAuth2.AutoFetchToken = autoFetchToken
		}
		if autoRefreshToken, ok := boolValueOK(oauth2Map["autoRefreshToken"]); ok {
			auth.OAuth2.AutoRefreshToken = autoRefreshToken
		} else if autoRefreshToken, ok := boolValueOK(oauth2Map["auto_refresh_token"]); ok {
			auth.OAuth2.AutoRefreshToken = autoRefreshToken
		}
		if rows := parseYAMLKeyValues(firstMapValue(oauth2Map, "additionalParams", "additional_params"), false); len(rows) > 0 {
			auth.OAuth2.AdditionalParams = rows
		}
		if additionalMap, ok := mapValue(firstMapValue(oauth2Map, "additionalParameters", "additional_parameters")); ok {
			auth.OAuth2.AuthorizationAdditionalParams = parseYAMLOAuth2AdditionalGroup(firstMapValue(additionalMap, "authorization", "authorizationRequest", "authRequest", "auth_req"))
			auth.OAuth2.TokenAdditionalParams = parseYAMLOAuth2AdditionalGroup(firstMapValue(additionalMap, "token", "accessTokenRequest", "access_token_req"))
			auth.OAuth2.RefreshAdditionalParams = parseYAMLOAuth2AdditionalGroup(firstMapValue(additionalMap, "refresh", "refreshTokenRequest", "refresh_token_req"))
		}
		awsMap := valueMap
		if nested, ok := mapValue(valueMap["awsv4"]); ok {
			awsMap = nested
		}
		auth.AWSV4.AccessKeyID = firstYAMLString(awsMap, "accessKeyId", "accessKey")
		auth.AWSV4.SecretAccessKey = firstYAMLString(awsMap, "secretAccessKey", "secretKey")
		auth.AWSV4.SessionToken = firstYAMLString(awsMap, "sessionToken")
		auth.AWSV4.Service = firstYAMLString(awsMap, "service")
		auth.AWSV4.Region = firstYAMLString(awsMap, "region")
		auth.AWSV4.ProfileName = firstYAMLString(awsMap, "profileName")
		oauth1Map := valueMap
		if nested, ok := mapValue(valueMap["oauth1"]); ok {
			oauth1Map = nested
		}
		auth.OAuth1.ConsumerKey = firstYAMLString(oauth1Map, "consumerKey", "consumer_key")
		auth.OAuth1.ConsumerSecret = firstYAMLString(oauth1Map, "consumerSecret", "consumer_secret")
		auth.OAuth1.AccessToken = firstYAMLString(oauth1Map, "accessToken", "access_token")
		auth.OAuth1.AccessTokenSecret = firstYAMLString(oauth1Map, "accessTokenSecret", "token_secret")
		auth.OAuth1.CallbackURL = firstYAMLString(oauth1Map, "callbackUrl", "callback_url")
		auth.OAuth1.Verifier = firstYAMLString(oauth1Map, "verifier")
		auth.OAuth1.SignatureMethod = firstYAMLString(oauth1Map, "signatureMethod", "signature_method")
		auth.OAuth1.PrivateKey = firstYAMLString(oauth1Map, "privateKey", "private_key")
		auth.OAuth1.PrivateKeyType = firstYAMLString(oauth1Map, "privateKeyType", "private_key_type")
		auth.OAuth1.Timestamp = firstYAMLString(oauth1Map, "timestamp")
		auth.OAuth1.Nonce = firstYAMLString(oauth1Map, "nonce")
		auth.OAuth1.Version = firstYAMLString(oauth1Map, "version")
		auth.OAuth1.Realm = firstYAMLString(oauth1Map, "realm")
		auth.OAuth1.Placement = firstYAMLString(oauth1Map, "placement")
		if includeBodyHash, ok := boolValueOK(oauth1Map["includeBodyHash"]); ok {
			auth.OAuth1.IncludeBodyHash = includeBodyHash
		} else if includeBodyHash, ok := boolValueOK(oauth1Map["include_body_hash"]); ok {
			auth.OAuth1.IncludeBodyHash = includeBodyHash
		}
		return auth
	}
	mode := strings.ToLower(strings.TrimSpace(yamlScalarString(raw)))
	if mode != "" {
		auth.Mode = mode
	}
	return auth
}

func applyYAMLSettings(item *RequestItem, settings map[string]interface{}) {
	if encodeURL, ok := boolValueOK(settings["encodeUrl"]); ok {
		item.Settings.EncodeURL = encodeURL
	}
	if timeout, ok := intValueOK(settings["timeout"]); ok {
		item.Settings.TimeoutMs = timeout
	}
	if follow, ok := boolValueOK(settings["followRedirects"]); ok {
		item.Settings.FollowRedirects = follow
	}
	if maxRedirects, ok := intValueOK(settings["maxRedirects"]); ok {
		item.Settings.MaxRedirects = maxRedirects
	}
	if storeCookies, ok := boolValueOK(settings["storeCookies"]); ok {
		item.Settings.StoreCookies = storeCookies
	}
	if verifyTLS, ok := boolValueOK(settings["verifyTls"]); ok {
		item.Settings.VerifyTLS = verifyTLS
	}
	if keepAliveInterval, ok := intValueOK(settings["keepAliveInterval"]); ok {
		item.Settings.KeepAliveInterval = keepAliveInterval
	}
}

func collectionShareSnapshot(collection Collection) Collection {
	snapshot := collection
	snapshot.Remote = ""
	snapshot.NotFoundLocally = false
	snapshot.RuntimeVariables = nil
	snapshot.Items = make([]RequestItem, 0, len(collection.Items))
	for _, item := range collection.Items {
		if item.Transient {
			continue
		}
		item.Response = nil
		item.Timeline = nil
		item.Draft = false
		item.Transient = false
		item.FilePath = ""
		snapshot.Items = append(snapshot.Items, item)
	}
	snapshot.Folders = append([]FolderConfig(nil), collection.Folders...)
	snapshot.Environments = make([]Environment, 0, len(collection.Environments))
	for _, env := range collection.Environments {
		env.Variables = append([]Variable(nil), env.Variables...)
		for index := range env.Variables {
			if env.Variables[index].Secret {
				env.Variables[index].Value = ""
			}
		}
		snapshot.Environments = append(snapshot.Environments, env)
	}
	return snapshot
}

func buildCollectionShareYAML(collection Collection, generatedAt time.Time) (string, int, int, error) {
	content, folderCount, requestCount, err := buildCollectionDocsYAML(collection, nil, generatedAt)
	if err != nil {
		return "", 0, 0, err
	}
	root, err := yamlMapFromString(content)
	if err != nil {
		return "", 0, 0, err
	}
	root["bundled"] = true
	data, err := yaml.Marshal(root)
	if err != nil {
		return "", 0, 0, err
	}
	return string(data), folderCount, requestCount, nil
}

func buildCollectionZipExportFiles(collection Collection) ([]collectionExportFile, int, int, error) {
	files := []collectionExportFile{}
	used := map[string]bool{}
	exportRoot := filepath.Join(os.TempDir(), "liteapi-export-root")
	collection.Path = exportRoot
	format := strings.ToLower(strings.TrimSpace(collection.Format))
	if format == "" {
		format = "yml"
	}
	if format == "yml" || format == "yaml" {
		root, err := yamlMapFromString(stringifyYAMLCollection(collection))
		if err != nil {
			return nil, 0, 0, err
		}
		root["bundled"] = false
		extensions, _ := mapValue(root["extensions"])
		if extensions == nil {
			extensions = map[string]interface{}{}
		}
		bruno, _ := mapValue(extensions["bruno"])
		if bruno == nil {
			bruno = map[string]interface{}{}
		}
		bruno["exportedAt"] = time.Now().UTC().Format(time.RFC3339)
		bruno["exportedUsing"] = "LiteAPI"
		extensions["bruno"] = bruno
		root["extensions"] = extensions
		data, err := yaml.Marshal(root)
		if err != nil {
			return nil, 0, 0, err
		}
		addCollectionExportFile(&files, used, "opencollection.yml", data)
		for _, folder := range collection.Folders {
			if folderPath := exportFolderPath(folder); folderPath != "" {
				addCollectionExportFile(&files, used, filepath.ToSlash(filepath.Join(filepath.FromSlash(folderPath), "folder.yml")), []byte(stringifyYAMLFolder(folder)))
			}
		}
		ensureRequestFilePaths(&collection, ".yml")
		for _, item := range collection.Items {
			content, err := stringifyYAMLRequest(item)
			if err != nil {
				return nil, 0, 0, err
			}
			rel, ok := exportRelativePath(collection.Path, item.FilePath)
			if !ok {
				continue
			}
			addCollectionExportFile(&files, used, rel, []byte(content))
		}
		return files, len(collection.Folders), len(collection.Items), nil
	}

	config := map[string]interface{}{
		"name":    collection.Name,
		"type":    "collection",
		"version": firstNonEmpty(collection.Version, "1"),
		"ignore":  []string{"node_modules", ".git"},
	}
	if hasProxyConfig(collection.Proxy) {
		config["proxy"] = jsonProxyConfig(collection.Proxy)
	}
	if hasClientCertificates(collection.ClientCertificates) {
		config["clientCertificates"] = jsonClientCertificates(collection.ClientCertificates)
	}
	if hasCollectionPresets(collection.Presets) {
		config["presets"] = jsonCollectionPresets(collection.Presets)
	}
	if hasCollectionProtobuf(collection.Protobuf) {
		config["protobuf"] = jsonCollectionProtobuf(collection.Protobuf)
	}
	if len(collection.OpenAPI) > 0 {
		config["openapi"] = jsonOpenAPISyncConfigs(collection.OpenAPI)
	}
	configData, err := json.MarshalIndent(config, "", "  ")
	if err != nil {
		return nil, 0, 0, err
	}
	addCollectionExportFile(&files, used, "bruno.json", configData)
	addCollectionExportFile(&files, used, "collection.bru", []byte(stringifyBruCollection(collection)))
	for _, env := range collection.Environments {
		name := sanitizeFilename(env.Name)
		if name == "" {
			name = env.ID
		}
		addCollectionExportFile(&files, used, filepath.ToSlash(filepath.Join("environments", name+".bru")), []byte(stringifyBruEnvironment(env)))
	}
	for _, folder := range collection.Folders {
		if folderPath := exportFolderPath(folder); folderPath != "" {
			addCollectionExportFile(&files, used, filepath.ToSlash(filepath.Join(filepath.FromSlash(folderPath), "folder.bru")), []byte(stringifyBruFolder(folder)))
		}
	}
	ensureRequestFilePaths(&collection, ".bru")
	for _, item := range collection.Items {
		rel, ok := exportRelativePath(collection.Path, item.FilePath)
		if !ok {
			continue
		}
		addCollectionExportFile(&files, used, rel, []byte(stringifyBru(item)))
	}
	return files, len(collection.Folders), len(collection.Items), nil
}

func addCollectionExportFile(files *[]collectionExportFile, used map[string]bool, name string, content []byte) {
	name = cleanExportArchivePath(name)
	if name == "" {
		return
	}
	name = uniqueCollectionExportPath(name, used)
	used[name] = true
	*files = append(*files, collectionExportFile{Name: name, Content: append([]byte(nil), content...)})
}

func cleanExportArchivePath(name string) string {
	name = filepath.ToSlash(filepath.Clean(filepath.FromSlash(strings.TrimSpace(name))))
	if name == "." || name == "" || strings.HasPrefix(name, "../") || name == ".." || strings.HasPrefix(name, "/") || filepath.IsAbs(name) {
		return ""
	}
	parts := strings.Split(name, "/")
	for _, part := range parts {
		if part == ".git" || part == "node_modules" {
			return ""
		}
	}
	return name
}

func uniqueCollectionExportPath(name string, used map[string]bool) string {
	if !used[name] {
		return name
	}
	ext := filepath.Ext(name)
	base := strings.TrimSuffix(name, ext)
	for index := 2; ; index++ {
		candidate := fmt.Sprintf("%s %d%s", base, index, ext)
		if !used[candidate] {
			return candidate
		}
	}
}

func exportFolderPath(folder FolderConfig) string {
	folderPath := normalizeFolderPathKey(firstNonEmpty(folder.DisplayPath, folder.Path))
	if folderPath == "" {
		return ""
	}
	return cleanExportArchivePath(folderPath)
}

func exportRelativePath(root, target string) (string, bool) {
	rel, err := filepath.Rel(filepath.Clean(root), filepath.Clean(target))
	if err != nil {
		return "", false
	}
	clean := cleanExportArchivePath(rel)
	return clean, clean != ""
}

func zipCollectionExportFiles(files []collectionExportFile) ([]byte, error) {
	var buffer bytes.Buffer
	archive := zip.NewWriter(&buffer)
	for _, file := range files {
		name := cleanExportArchivePath(file.Name)
		if name == "" {
			continue
		}
		header := &zip.FileHeader{Name: name, Method: zip.Deflate}
		header.SetMode(0o600)
		writer, err := archive.CreateHeader(header)
		if err != nil {
			_ = archive.Close()
			return nil, err
		}
		if _, err := writer.Write(file.Content); err != nil {
			_ = archive.Close()
			return nil, err
		}
	}
	if err := archive.Close(); err != nil {
		return nil, err
	}
	return buffer.Bytes(), nil
}

func collectionExportBytes(result CollectionExportResult) ([]byte, error) {
	if strings.TrimSpace(result.ContentBase64) != "" {
		return base64.StdEncoding.DecodeString(result.ContentBase64)
	}
	return []byte(result.Content), nil
}

func buildPostmanCollectionExport(collection Collection) (string, int, []string, error) {
	skipped := []string{}
	skippedSeen := map[string]bool{}
	items, count := postmanCollectionItems(collection, "", &skipped, skippedSeen)
	payload := map[string]interface{}{
		"info": map[string]interface{}{
			"name":   collection.Name,
			"schema": "https://schema.getpostman.com/json/collection/v2.1.0/collection.json",
		},
		"item": items,
	}
	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return "", 0, nil, err
	}
	return string(data), count, skipped, nil
}

func postmanCollectionItems(collection Collection, parentPath string, skipped *[]string, skippedSeen map[string]bool) ([]interface{}, int) {
	out := []interface{}{}
	count := 0
	for _, folder := range collectionDocsChildFolders(collection.Folders, parentPath) {
		children, childCount := postmanCollectionItems(collection, folder.DisplayPath, skipped, skippedSeen)
		out = append(out, map[string]interface{}{
			"name": firstNonEmpty(folder.Name, filepath.Base(filepath.FromSlash(folder.DisplayPath)), filepath.Base(filepath.FromSlash(folder.Path))),
			"item": children,
		})
		count += childCount
	}
	for _, item := range collectionDocsChildRequests(collection.Items, parentPath) {
		switch item.Type {
		case "", "http", "graphql":
			out = append(out, sharePostmanRequestItem(item))
			count++
		case "grpc":
			addSkippedCollectionExportType(skipped, skippedSeen, "gRPC")
		case "websocket":
			addSkippedCollectionExportType(skipped, skippedSeen, "WebSocket")
		}
	}
	return out, count
}

func addSkippedCollectionExportType(skipped *[]string, seen map[string]bool, label string) {
	if seen[label] {
		return
	}
	seen[label] = true
	*skipped = append(*skipped, label)
}

func sharePostmanRequestItem(item RequestItem) map[string]interface{} {
	method := strings.ToUpper(firstNonEmpty(item.Method, http.MethodGet))
	request := map[string]interface{}{
		"method": method,
		"url":    sharePostmanURL(item),
	}
	if headers := sharePostmanKeyValues(item.Headers, "key"); len(headers) > 0 {
		request["header"] = headers
	}
	if body := sharePostmanBody(item); body != nil {
		request["body"] = body
	}
	if auth := sharePostmanAuth(item.Auth); auth != nil {
		request["auth"] = auth
	}
	return map[string]interface{}{
		"name":    item.Name,
		"request": request,
	}
}

func sharePostmanURL(item RequestItem) map[string]interface{} {
	url := map[string]interface{}{"raw": item.URL}
	if len(item.Params) > 0 {
		query := []map[string]interface{}{}
		for _, param := range item.Params {
			if strings.TrimSpace(param.Name) == "" {
				continue
			}
			entry := map[string]interface{}{"key": param.Name, "value": param.Value}
			if !param.Enabled {
				entry["disabled"] = true
			}
			query = append(query, entry)
		}
		if len(query) > 0 {
			url["query"] = query
		}
	}
	return url
}

func sharePostmanBody(item RequestItem) map[string]interface{} {
	if item.Type == "graphql" {
		return map[string]interface{}{
			"mode": "graphql",
			"graphql": map[string]interface{}{
				"query":     item.Body.GraphQLQuery,
				"variables": item.Body.GraphQLVariables,
			},
		}
	}
	switch item.Body.Mode {
	case "json":
		return sharePostmanRawBody(item.Body.JSON, "json")
	case "xml":
		return sharePostmanRawBody(item.Body.XML, "xml")
	case "text", "sparql":
		return sharePostmanRawBody(item.Body.Text, "text")
	case "formUrlEncoded":
		return map[string]interface{}{"mode": "urlencoded", "urlencoded": sharePostmanKeyValues(item.Body.FormURLEncoded, "key")}
	case "multipartForm":
		return map[string]interface{}{"mode": "formdata", "formdata": sharePostmanFormData(item.Body.Multipart)}
	case "file":
		if file := shareSelectedFileBodyEntry(item.Body); file != nil {
			return map[string]interface{}{"mode": "file", "file": map[string]interface{}{"src": file.FilePath}}
		}
	}
	return nil
}

func sharePostmanRawBody(body, language string) map[string]interface{} {
	if strings.TrimSpace(body) == "" {
		return nil
	}
	return map[string]interface{}{
		"mode": "raw",
		"raw":  body,
		"options": map[string]interface{}{
			"raw": map[string]interface{}{"language": language},
		},
	}
}

func sharePostmanKeyValues(values []KeyValue, keyName string) []map[string]interface{} {
	out := []map[string]interface{}{}
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" {
			continue
		}
		entry := map[string]interface{}{keyName: value.Name, "value": value.Value}
		if !value.Enabled {
			entry["disabled"] = true
		}
		out = append(out, entry)
	}
	return out
}

func sharePostmanFormData(values []FormPart) []map[string]interface{} {
	out := []map[string]interface{}{}
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" {
			continue
		}
		entry := map[string]interface{}{
			"key":   value.Name,
			"value": value.Value,
			"type":  "text",
		}
		if strings.TrimSpace(value.FilePath) != "" {
			entry["type"] = "file"
			entry["src"] = value.FilePath
			delete(entry, "value")
		}
		if !value.Enabled {
			entry["disabled"] = true
		}
		out = append(out, entry)
	}
	return out
}

func shareSelectedFileBodyEntry(body RequestBody) *FileBodyEntry {
	for _, file := range fileBodyEntries(body) {
		if file.Selected && strings.TrimSpace(file.FilePath) != "" {
			copy := file
			return &copy
		}
	}
	return nil
}

func sharePostmanAuth(auth AuthConfig) map[string]interface{} {
	switch strings.ToLower(strings.TrimSpace(auth.Mode)) {
	case "basic":
		return map[string]interface{}{"type": "basic", "basic": []map[string]interface{}{
			{"key": "username", "value": auth.Username, "type": "string"},
			{"key": "password", "value": auth.Password, "type": "string"},
		}}
	case "bearer":
		return map[string]interface{}{"type": "bearer", "bearer": []map[string]interface{}{
			{"key": "token", "value": auth.Token, "type": "string"},
		}}
	case "apikey":
		return map[string]interface{}{"type": "apikey", "apikey": []map[string]interface{}{
			{"key": "key", "value": auth.APIKey, "type": "string"},
			{"key": "value", "value": auth.APIValue, "type": "string"},
			{"key": "in", "value": firstNonEmpty(auth.APILocation, "header"), "type": "string"},
		}}
	default:
		return nil
	}
}

func buildCollectionDocsYAML(collection Collection, selectedEnvironmentIDs []string, generatedAt time.Time) (string, int, int, error) {
	root, err := yamlMapFromString(stringifyYAMLCollection(collection))
	if err != nil {
		return "", 0, 0, err
	}
	info, _ := mapValue(root["info"])
	if info == nil {
		info = map[string]interface{}{}
	}
	info["name"] = collection.Name
	if strings.TrimSpace(collection.Version) != "" {
		info["version"] = strings.TrimSpace(collection.Version)
	}
	root["info"] = info

	items, folderCount, requestCount, err := collectionDocsItems(collection, "")
	if err != nil {
		return "", 0, 0, err
	}
	root["items"] = items

	config, _ := mapValue(root["config"])
	if config == nil {
		config = map[string]interface{}{}
	}
	config["environments"] = yamlDocsEnvironments(collection.Environments, selectedEnvironmentIDs)
	root["config"] = config

	extensions, _ := mapValue(root["extensions"])
	if extensions == nil {
		extensions = map[string]interface{}{}
	}
	bruno, _ := mapValue(extensions["bruno"])
	if bruno == nil {
		bruno = map[string]interface{}{}
	}
	bruno["exportedAt"] = generatedAt.Format(time.RFC3339)
	bruno["exportedUsing"] = "LiteAPI"
	extensions["bruno"] = bruno
	root["extensions"] = extensions

	data, err := yaml.Marshal(root)
	if err != nil {
		return "", 0, 0, err
	}
	return string(data), folderCount, requestCount, nil
}

func buildCollectionDocsHTML(collectionName, yamlContent string) (string, error) {
	encoded, err := json.Marshal(yamlContent)
	if err != nil {
		return "", err
	}
	escapedYAML := strings.ReplaceAll(string(encoded), `</`, `<\/`)
	title := html.EscapeString(collectionName)
	return fmt.Sprintf(`<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>%s - API Documentation</title>
    <style>
        body { margin: 0; padding: 0; }
        #opencollection-container { width: 100vw; height: 100vh; }
    </style>
    <link rel="stylesheet" href="https://cdn.opencollection.com/docs.css">
    <script src="https://cdn.opencollection.com/docs.js"></script>
</head>
<body>
    <div id="opencollection-container"></div>
    <script>
        const collectionData = %s;
        new window.OpenCollection({
            target: document.getElementById('opencollection-container'),
            opencollection: collectionData,
            theme: 'light'
        });
    </script>
</body>
</html>`, title, escapedYAML), nil
}

func yamlMapFromString(content string) (map[string]interface{}, error) {
	var raw map[string]interface{}
	if err := yaml.Unmarshal([]byte(content), &raw); err != nil {
		return nil, err
	}
	if raw == nil {
		raw = map[string]interface{}{}
	}
	return raw, nil
}

func collectionDocsItems(collection Collection, parentPath string) ([]map[string]interface{}, int, int, error) {
	folders := collectionDocsChildFolders(collection.Folders, parentPath)
	requests := collectionDocsChildRequests(collection.Items, parentPath)
	items := make([]map[string]interface{}, 0, len(folders)+len(requests))
	folderCount := 0
	requestCount := 0
	for _, folder := range folders {
		node, err := yamlMapFromString(stringifyYAMLFolder(folder))
		if err != nil {
			return nil, 0, 0, err
		}
		children, childFolders, childRequests, err := collectionDocsItems(collection, folder.DisplayPath)
		if err != nil {
			return nil, 0, 0, err
		}
		if len(children) > 0 {
			node["items"] = children
		}
		items = append(items, node)
		folderCount += 1 + childFolders
		requestCount += childRequests
	}
	for _, request := range requests {
		content, err := stringifyYAMLRequest(request)
		if err != nil {
			return nil, 0, 0, err
		}
		node, err := yamlMapFromString(content)
		if err != nil {
			return nil, 0, 0, err
		}
		items = append(items, node)
		requestCount++
	}
	return items, folderCount, requestCount, nil
}

func collectionDocsChildFolders(folders []FolderConfig, parentPath string) []FolderConfig {
	parentPath = normalizeFolderPathKey(parentPath)
	children := make([]FolderConfig, 0)
	for _, folder := range folders {
		displayPath := normalizeFolderPathKey(firstNonEmpty(folder.DisplayPath, folder.Path))
		if displayPath == "" {
			continue
		}
		if normalizeFolderPathKey(parentFolderDisplayPath(displayPath)) == parentPath {
			if folder.DisplayPath == "" {
				folder.DisplayPath = displayPath
			}
			children = append(children, folder)
		}
	}
	sortFoldersLikeBruno(children)
	return children
}

func collectionDocsChildRequests(items []RequestItem, parentPath string) []RequestItem {
	parentPath = normalizeFolderPathKey(parentPath)
	children := make([]RequestItem, 0)
	for _, item := range items {
		if item.Transient {
			continue
		}
		if !collectionDocsRequestIsExportable(item) {
			continue
		}
		if normalizeFolderPathKey(item.FolderPath) == parentPath {
			children = append(children, item)
		}
	}
	sort.SliceStable(children, func(i, j int) bool {
		if children[i].Seq != children[j].Seq {
			return children[i].Seq < children[j].Seq
		}
		return strings.ToLower(children[i].Name) < strings.ToLower(children[j].Name)
	})
	return children
}

func collectionDocsRequestIsExportable(item RequestItem) bool {
	return item.Type == "" || item.Type == "http" || item.Type == "graphql" || item.Type == "websocket" || item.Type == "grpc"
}

func sortFoldersLikeBruno(folders []FolderConfig) {
	sort.SliceStable(folders, func(i, j int) bool {
		leftValid := folders[i].Seq > 0
		rightValid := folders[j].Seq > 0
		if leftValid && rightValid && folders[i].Seq != folders[j].Seq {
			return folders[i].Seq < folders[j].Seq
		}
		if leftValid != rightValid {
			return leftValid
		}
		return strings.ToLower(firstNonEmpty(folders[i].Name, folders[i].DisplayPath, folders[i].Path)) < strings.ToLower(firstNonEmpty(folders[j].Name, folders[j].DisplayPath, folders[j].Path))
	})
}

func parentFolderDisplayPath(path string) string {
	path = normalizeFolderPathKey(path)
	parent := filepath.ToSlash(filepath.Dir(path))
	if parent == "." {
		return ""
	}
	return parent
}

func yamlDocsEnvironments(environments []Environment, selectedEnvironmentIDs []string) []map[string]interface{} {
	includeAll := selectedEnvironmentIDs == nil
	selected := map[string]bool{}
	for _, id := range selectedEnvironmentIDs {
		selected[id] = true
	}
	out := make([]map[string]interface{}, 0, len(environments))
	for _, env := range environments {
		if !includeAll && !selected[env.ID] {
			continue
		}
		out = append(out, map[string]interface{}{
			"name":      env.Name,
			"color":     env.Color,
			"variables": yamlVariables(env.Variables),
		})
	}
	return out
}

func collectionDisplayVersion(version string) string {
	version = strings.TrimSpace(strings.TrimPrefix(version, "v"))
	if version == "" {
		return "v1.0.0"
	}
	parts := strings.SplitN(version, "-", 2)
	numbers := strings.Split(parts[0], ".")
	for len(numbers) < 3 {
		numbers = append(numbers, "0")
	}
	for index := range numbers[:3] {
		if _, err := strconv.Atoi(numbers[index]); err != nil {
			return "v1.0.0"
		}
	}
	normalized := strings.Join(numbers[:3], ".")
	if len(parts) == 2 && strings.TrimSpace(parts[1]) != "" {
		normalized += "-" + strings.TrimSpace(parts[1])
	}
	return "v" + normalized
}

func stringifyYAMLCollection(collection Collection) string {
	brunoExtensions := map[string]interface{}{
		"ignore": []string{"node_modules", ".git"},
	}
	if len(collection.OpenAPI) > 0 {
		brunoExtensions["openapi"] = yamlOpenAPISyncConfigs(collection.OpenAPI)
	}
	root := map[string]interface{}{
		"opencollection": "1.0.0",
		"info": map[string]interface{}{
			"name":    collection.Name,
			"version": firstNonEmpty(collection.Version, "1"),
		},
		"extensions": map[string]interface{}{
			"bruno": brunoExtensions,
		},
	}
	request := map[string]interface{}{}
	if len(collection.Headers) > 0 {
		request["headers"] = yamlKeyValues(collection.Headers)
	}
	if len(collection.Variables) > 0 {
		request["variables"] = yamlVariables(collection.Variables)
	}
	if len(collection.ResVariables) > 0 {
		request["actions"] = yamlPostResponseActions(collection.ResVariables)
	}
	if collection.Auth.Mode != "" && collection.Auth.Mode != "none" {
		request["auth"] = yamlAuth(collection.Auth)
	}
	scripts := []map[string]interface{}{}
	if collection.PreScript != "" {
		scripts = append(scripts, map[string]interface{}{"type": "before-request", "code": collection.PreScript})
	}
	if collection.PostScript != "" {
		scripts = append(scripts, map[string]interface{}{"type": "after-response", "code": collection.PostScript})
	}
	if collection.Tests != "" {
		scripts = append(scripts, map[string]interface{}{"type": "tests", "code": collection.Tests})
	}
	if len(scripts) > 0 {
		request["scripts"] = scripts
	}
	if len(request) > 0 {
		root["request"] = request
	}
	if strings.TrimSpace(collection.Docs) != "" {
		root["docs"] = map[string]interface{}{"content": collection.Docs}
	}
	config := map[string]interface{}{}
	if len(collection.Environments) > 0 {
		envs := make([]map[string]interface{}, 0, len(collection.Environments))
		for _, env := range collection.Environments {
			envs = append(envs, map[string]interface{}{
				"name":      env.Name,
				"color":     env.Color,
				"variables": yamlVariables(env.Variables),
			})
		}
		config["environments"] = envs
	}
	if hasProxyConfig(collection.Proxy) {
		config["proxy"] = yamlProxyConfig(collection.Proxy)
	}
	if hasClientCertificates(collection.ClientCertificates) {
		config["clientCertificates"] = yamlClientCertificates(collection.ClientCertificates)
	}
	if hasCollectionPresets(collection.Presets) {
		config["presets"] = yamlCollectionPresets(collection.Presets)
	}
	if hasCollectionProtobuf(collection.Protobuf) {
		config["protobuf"] = yamlCollectionProtobuf(collection.Protobuf)
	}
	if len(config) > 0 {
		root["config"] = config
	}
	data, _ := yaml.Marshal(root)
	return string(data)
}

func stringifyYAMLFolder(folder FolderConfig) string {
	info := map[string]interface{}{
		"name": firstNonEmpty(folder.Name, filepath.Base(filepath.FromSlash(folder.Path))),
		"type": "folder",
	}
	if folder.Seq > 0 {
		info["seq"] = folder.Seq
	}
	root := map[string]interface{}{"info": info}
	request := map[string]interface{}{}
	if len(folder.Headers) > 0 {
		request["headers"] = yamlKeyValues(folder.Headers)
	}
	if len(folder.Variables) > 0 {
		request["variables"] = yamlVariables(folder.Variables)
	}
	if len(folder.ResVariables) > 0 {
		request["actions"] = yamlPostResponseActions(folder.ResVariables)
	}
	if folder.Auth.Mode != "" {
		request["auth"] = yamlAuth(folder.Auth)
	}
	scripts := []map[string]interface{}{}
	if folder.PreScript != "" {
		scripts = append(scripts, map[string]interface{}{"type": "before-request", "code": folder.PreScript})
	}
	if folder.PostScript != "" {
		scripts = append(scripts, map[string]interface{}{"type": "after-response", "code": folder.PostScript})
	}
	if folder.Tests != "" {
		scripts = append(scripts, map[string]interface{}{"type": "tests", "code": folder.Tests})
	}
	if len(scripts) > 0 {
		request["scripts"] = scripts
	}
	if len(request) > 0 {
		root["request"] = request
	}
	if strings.TrimSpace(folder.Docs) != "" {
		root["docs"] = map[string]interface{}{"content": folder.Docs}
	}
	data, _ := yaml.Marshal(root)
	return string(data)
}

func stringifyYAMLRequest(item RequestItem) (string, error) {
	requestType := item.Type
	if requestType == "" {
		requestType = "http"
	}
	root := map[string]interface{}{
		"info": map[string]interface{}{
			"name": item.Name,
			"type": requestType,
			"seq":  item.Seq,
		},
	}
	switch requestType {
	case "graphql":
		section := map[string]interface{}{
			"method": item.Method,
			"url":    item.URL,
			"body": map[string]interface{}{
				"query":     item.Body.GraphQLQuery,
				"variables": item.Body.GraphQLVariables,
			},
		}
		addCommonYAMLRequestFields(section, item)
		root["graphql"] = section
	case "websocket":
		section := map[string]interface{}{
			"url": item.URL,
		}
		if message := yamlWSMessage(item); message != nil {
			section["message"] = message
		}
		addCommonYAMLRequestFields(section, item)
		root["websocket"] = section
	case "grpc":
		section := map[string]interface{}{
			"url":    item.URL,
			"method": item.Method,
		}
		if strings.TrimSpace(item.GrpcMethodType) != "" {
			section["methodType"] = item.GrpcMethodType
		}
		if strings.TrimSpace(item.ProtoPath) != "" {
			section["protoFilePath"] = item.ProtoPath
		}
		if len(item.Headers) > 0 {
			section["metadata"] = yamlGrpcMetadata(item.Headers)
		}
		if len(item.GrpcMessages) > 0 {
			section["message"] = yamlGrpcMessages(item.GrpcMessages)
		}
		if item.Auth.Mode != "" && item.Auth.Mode != "none" {
			section["auth"] = yamlAuth(item.Auth)
		}
		root["grpc"] = section
	default:
		section := map[string]interface{}{
			"method": item.Method,
			"url":    item.URL,
		}
		addCommonYAMLRequestFields(section, item)
		if body := yamlBody(item.Body); len(body) > 0 {
			section["body"] = body
		}
		root["http"] = section
	}
	if len(item.Vars.Req) > 0 || len(item.Vars.Res) > 0 || item.PreScript != "" || item.PostScript != "" || item.Tests != "" {
		runtime := map[string]interface{}{}
		if len(item.Vars.Req) > 0 {
			runtime["variables"] = yamlVariables(item.Vars.Req)
		}
		if len(item.Vars.Res) > 0 {
			runtime["actions"] = yamlPostResponseActions(item.Vars.Res)
		}
		scripts := []map[string]interface{}{}
		if item.PreScript != "" {
			scripts = append(scripts, map[string]interface{}{"type": "before-request", "code": item.PreScript})
		}
		if item.PostScript != "" {
			scripts = append(scripts, map[string]interface{}{"type": "after-response", "code": item.PostScript})
		}
		if item.Tests != "" {
			scripts = append(scripts, map[string]interface{}{"type": "tests", "code": item.Tests})
		}
		if len(scripts) > 0 {
			runtime["scripts"] = scripts
		}
		root["runtime"] = runtime
	}
	root["settings"] = map[string]interface{}{
		"encodeUrl":         item.Settings.EncodeURL,
		"timeout":           item.Settings.TimeoutMs,
		"followRedirects":   item.Settings.FollowRedirects,
		"maxRedirects":      item.Settings.MaxRedirects,
		"storeCookies":      item.Settings.StoreCookies,
		"verifyTls":         item.Settings.VerifyTLS,
		"keepAliveInterval": item.Settings.KeepAliveInterval,
	}
	if strings.TrimSpace(item.Docs) != "" {
		root["docs"] = item.Docs
	}
	data, err := yaml.Marshal(root)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func addCommonYAMLRequestFields(section map[string]interface{}, item RequestItem) {
	if len(item.Headers) > 0 {
		section["headers"] = yamlKeyValues(item.Headers)
	}
	if len(item.Params) > 0 || len(item.PathParams) > 0 {
		section["params"] = yamlParams(item.Params, item.PathParams)
	}
	if item.Auth.Mode != "" && item.Auth.Mode != "none" {
		section["auth"] = yamlAuth(item.Auth)
	}
}

func yamlBody(body RequestBody) map[string]interface{} {
	mode := yamlBodyType(body.Mode)
	if mode == "" || mode == "none" {
		return nil
	}
	result := map[string]interface{}{"type": mode}
	switch body.Mode {
	case "formUrlEncoded":
		result["data"] = yamlKeyValues(body.FormURLEncoded)
	case "multipartForm":
		result["data"] = yamlMultipart(body.Multipart)
	case "file":
		result["data"] = yamlFileBody(body)
	default:
		result["data"] = yamlBodyText(body)
	}
	return result
}

func yamlFileBody(body RequestBody) []map[string]interface{} {
	entries := fileBodyEntries(body)
	if len(entries) == 0 {
		return nil
	}
	result := make([]map[string]interface{}, 0, len(entries))
	for _, file := range entries {
		if strings.TrimSpace(file.FilePath) == "" && strings.TrimSpace(file.ContentType) == "" {
			continue
		}
		entry := map[string]interface{}{
			"filePath": file.FilePath,
			"selected": file.Selected,
		}
		if strings.TrimSpace(file.ContentType) != "" {
			entry["contentType"] = file.ContentType
		}
		result = append(result, entry)
	}
	return result
}

func yamlBodyText(body RequestBody) string {
	switch body.Mode {
	case "json":
		return body.JSON
	case "xml":
		return body.XML
	default:
		return body.Text
	}
}

func yamlBodyType(mode string) string {
	switch mode {
	case "formUrlEncoded":
		return "form-urlencoded"
	case "multipartForm":
		return "multipart-form"
	case "":
		return "none"
	default:
		return mode
	}
}

func yamlWSMessage(item RequestItem) interface{} {
	messages := wsMessagesForStorage(item)
	if len(messages) == 0 {
		return nil
	}
	if len(messages) == 1 {
		message := messages[0]
		if strings.TrimSpace(message.Name) == "" && !message.Selected {
			return map[string]interface{}{
				"type": normalizeWSMessageType(message.Type),
				"data": message.Content,
			}
		}
	}
	return yamlWSMessages(messages)
}

func wsMessagesForStorage(item RequestItem) []WSMessage {
	if len(item.WSMessages) > 0 {
		return item.WSMessages
	}
	if content := websocketMessage(item.Body, nil); strings.TrimSpace(content) != "" {
		return []WSMessage{{Type: normalizeWSMessageType(item.Body.Mode), Content: content}}
	}
	return nil
}

func yamlWSMessages(messages []WSMessage) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(messages))
	for index, message := range messages {
		if strings.TrimSpace(message.Name) == "" && strings.TrimSpace(message.Content) == "" {
			continue
		}
		title := message.Name
		if strings.TrimSpace(title) == "" {
			title = fmt.Sprintf("message %d", index+1)
		}
		result = append(result, map[string]interface{}{
			"title":    title,
			"selected": message.Selected,
			"message": map[string]interface{}{
				"type": normalizeWSMessageType(message.Type),
				"data": message.Content,
			},
		})
	}
	return result
}

func yamlKeyValues(values []KeyValue) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(values))
	for _, value := range values {
		entry := map[string]interface{}{
			"name":    value.Name,
			"value":   value.Value,
			"enabled": value.Enabled,
		}
		if value.Secret {
			entry["secret"] = true
		}
		if value.Description != "" {
			entry["description"] = value.Description
		}
		result = append(result, entry)
	}
	return result
}

func yamlGrpcMetadata(values []KeyValue) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(values))
	for _, value := range values {
		entry := map[string]interface{}{
			"name":  value.Name,
			"value": value.Value,
		}
		if !value.Enabled {
			entry["disabled"] = true
		}
		if value.Description != "" {
			entry["description"] = value.Description
		}
		result = append(result, entry)
	}
	return result
}

func yamlGrpcMessages(messages []GrpcMessage) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(messages))
	for index, message := range messages {
		if strings.TrimSpace(message.Name) == "" && strings.TrimSpace(message.Content) == "" {
			continue
		}
		title := message.Name
		if strings.TrimSpace(title) == "" {
			title = fmt.Sprintf("message %d", index+1)
		}
		result = append(result, map[string]interface{}{
			"title":   title,
			"message": message.Content,
		})
	}
	return result
}

func yamlOAuth2AdditionalParameters(auth OAuth2Auth) map[string]interface{} {
	result := map[string]interface{}{}
	if rows := yamlOAuth2AdditionalParams(auth.AuthorizationAdditionalParams); len(rows) > 0 {
		result["authorization"] = rows
	}
	if rows := yamlOAuth2AdditionalParams(auth.TokenAdditionalParams); len(rows) > 0 {
		result["token"] = rows
	}
	if rows := yamlOAuth2AdditionalParams(auth.RefreshAdditionalParams); len(rows) > 0 {
		result["refresh"] = rows
	}
	if len(result) == 0 {
		return nil
	}
	return result
}

func yamlOAuth2AdditionalParams(params []OAuth2AdditionalParam) []map[string]interface{} {
	result := []map[string]interface{}{}
	for _, param := range params {
		if strings.TrimSpace(param.Name) == "" {
			continue
		}
		entry := map[string]interface{}{
			"name":    param.Name,
			"value":   param.Value,
			"sendIn":  normalizeOAuth2AdditionalPlacement(param.SendIn),
			"enabled": param.Enabled,
		}
		if param.Secret {
			entry["secret"] = true
		}
		if param.Description != "" {
			entry["description"] = param.Description
		}
		result = append(result, entry)
	}
	return result
}

func parseYAMLProxyConfig(raw interface{}) (ProxyConfig, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return ProxyConfig{}, false
	}
	proxy := ProxyConfig{
		Inherit:  boolValue(valueMap["inherit"], false),
		Disabled: boolValue(valueMap["disabled"], false),
	}
	configMap, _ := mapValue(valueMap["config"])
	if configMap == nil {
		configMap = valueMap
	}
	proxy.Protocol = firstNonEmpty(firstYAMLString(configMap, "protocol"), "http")
	proxy.Hostname = firstYAMLString(configMap, "hostname", "host")
	proxy.Port = strings.TrimSpace(yamlScalarString(configMap["port"]))
	proxy.BypassProxy = firstYAMLString(configMap, "bypassProxy", "bypass_proxy", "noProxy", "no_proxy")
	if authMap, ok := mapValue(configMap["auth"]); ok {
		proxy.Auth.Username = firstYAMLString(authMap, "username", "user")
		proxy.Auth.Password = firstYAMLString(authMap, "password", "pass")
		proxy.Auth.Disabled = boolValue(authMap["disabled"], false)
		if enabled, ok := boolValueOK(authMap["enabled"]); ok {
			proxy.Auth.Disabled = !enabled
		}
	}
	return normalizeProxyConfig(proxy), true
}

func parseJSONProxyConfig(raw interface{}) (ProxyConfig, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return ProxyConfig{}, false
	}
	if _, hasNewConfig := valueMap["config"]; hasNewConfig {
		return parseYAMLProxyConfig(valueMap)
	}
	proxy := ProxyConfig{
		Inherit:     false,
		Disabled:    !boolValue(valueMap["enabled"], false),
		Protocol:    firstNonEmpty(firstYAMLString(valueMap, "protocol"), "http"),
		Hostname:    firstYAMLString(valueMap, "hostname", "host"),
		Port:        strings.TrimSpace(yamlScalarString(valueMap["port"])),
		BypassProxy: firstYAMLString(valueMap, "bypassProxy", "bypass_proxy", "noProxy", "no_proxy"),
	}
	if mode := strings.ToLower(firstYAMLString(valueMap, "mode", "source")); mode != "" {
		switch mode {
		case "off", "disabled":
			proxy.Disabled = true
		case "system", "inherit":
			proxy.Inherit = true
			proxy.Disabled = false
		case "on", "manual":
			proxy.Inherit = false
			proxy.Disabled = false
		}
	}
	if authMap, ok := mapValue(valueMap["auth"]); ok {
		proxy.Auth.Username = firstYAMLString(authMap, "username", "user")
		proxy.Auth.Password = firstYAMLString(authMap, "password", "pass")
		proxy.Auth.Disabled = !boolValue(authMap["enabled"], true)
		if disabled, ok := boolValueOK(authMap["disabled"]); ok {
			proxy.Auth.Disabled = disabled
		}
	}
	return normalizeProxyConfig(proxy), true
}

func yamlProxyConfig(proxy ProxyConfig) map[string]interface{} {
	proxy = normalizeProxyConfig(proxy)
	config := map[string]interface{}{
		"protocol":    firstNonEmpty(proxy.Protocol, "http"),
		"hostname":    proxy.Hostname,
		"port":        proxyPortValue(proxy.Port),
		"auth":        map[string]interface{}{"username": proxy.Auth.Username, "password": proxy.Auth.Password},
		"bypassProxy": proxy.BypassProxy,
	}
	if proxy.Auth.Disabled {
		config["auth"].(map[string]interface{})["disabled"] = true
	}
	result := map[string]interface{}{"inherit": proxy.Inherit, "config": config}
	if proxy.Disabled {
		result["disabled"] = true
	}
	return result
}

func jsonProxyConfig(proxy ProxyConfig) map[string]interface{} {
	return yamlProxyConfig(proxy)
}

func parseYAMLClientCertificates(raw interface{}) ([]ClientCertificateConfig, bool) {
	values, ok := listValue(raw)
	if !ok {
		return nil, false
	}
	certs := make([]ClientCertificateConfig, 0, len(values))
	for _, value := range values {
		valueMap, ok := mapValue(value)
		if !ok {
			continue
		}
		cert := ClientCertificateConfig{
			Domain:     firstYAMLString(valueMap, "domain"),
			Type:       firstYAMLString(valueMap, "type"),
			Passphrase: firstYAMLString(valueMap, "passphrase"),
		}
		switch strings.ToLower(strings.TrimSpace(cert.Type)) {
		case "pem", "cert", "":
			cert.Type = "cert"
			cert.CertFilePath = firstYAMLString(valueMap, "certificateFilePath", "certFilePath", "cert")
			cert.KeyFilePath = firstYAMLString(valueMap, "privateKeyFilePath", "keyFilePath", "key")
		case "pkcs12", "pfx":
			cert.Type = "pfx"
			cert.PFXFilePath = firstYAMLString(valueMap, "pkcs12FilePath", "pfxFilePath", "pfx")
		default:
			cert.CertFilePath = firstYAMLString(valueMap, "certificateFilePath", "certFilePath", "cert")
			cert.KeyFilePath = firstYAMLString(valueMap, "privateKeyFilePath", "keyFilePath", "key")
			cert.PFXFilePath = firstYAMLString(valueMap, "pkcs12FilePath", "pfxFilePath", "pfx")
		}
		certs = append(certs, cert)
	}
	return normalizeClientCertificates(certs), true
}

func parseJSONClientCertificates(raw interface{}) ([]ClientCertificateConfig, bool) {
	valueMap, ok := mapValue(raw)
	if ok {
		return parseYAMLBrunoClientCertificateList(valueMap["certs"])
	}
	return parseYAMLBrunoClientCertificateList(raw)
}

func parseYAMLBrunoClientCertificateList(raw interface{}) ([]ClientCertificateConfig, bool) {
	values, ok := listValue(raw)
	if !ok {
		return nil, false
	}
	certs := make([]ClientCertificateConfig, 0, len(values))
	for _, value := range values {
		valueMap, ok := mapValue(value)
		if !ok {
			continue
		}
		certs = append(certs, ClientCertificateConfig{
			Domain:       firstYAMLString(valueMap, "domain"),
			Type:         firstNonEmpty(firstYAMLString(valueMap, "type"), "cert"),
			CertFilePath: firstYAMLString(valueMap, "certFilePath", "certificateFilePath", "cert"),
			KeyFilePath:  firstYAMLString(valueMap, "keyFilePath", "privateKeyFilePath", "key"),
			PFXFilePath:  firstYAMLString(valueMap, "pfxFilePath", "pkcs12FilePath", "pfx"),
			Passphrase:   firstYAMLString(valueMap, "passphrase"),
		})
	}
	return normalizeClientCertificates(certs), true
}

func yamlClientCertificates(certs []ClientCertificateConfig) []map[string]interface{} {
	normalized := normalizeClientCertificates(certs)
	result := make([]map[string]interface{}, 0, len(normalized))
	for _, cert := range normalized {
		entry := map[string]interface{}{
			"domain": cert.Domain,
		}
		if cert.Type == "pfx" {
			entry["type"] = "pkcs12"
			entry["pkcs12FilePath"] = cert.PFXFilePath
		} else {
			entry["type"] = "pem"
			entry["certificateFilePath"] = cert.CertFilePath
			entry["privateKeyFilePath"] = cert.KeyFilePath
		}
		if cert.Passphrase != "" {
			entry["passphrase"] = cert.Passphrase
		}
		result = append(result, entry)
	}
	return result
}

func jsonClientCertificates(certs []ClientCertificateConfig) map[string]interface{} {
	normalized := normalizeClientCertificates(certs)
	entries := make([]map[string]interface{}, 0, len(normalized))
	for _, cert := range normalized {
		entry := map[string]interface{}{
			"domain": cert.Domain,
			"type":   firstNonEmpty(cert.Type, "cert"),
		}
		if cert.Type == "pfx" {
			entry["pfxFilePath"] = cert.PFXFilePath
		} else {
			entry["certFilePath"] = cert.CertFilePath
			entry["keyFilePath"] = cert.KeyFilePath
		}
		if cert.Passphrase != "" {
			entry["passphrase"] = cert.Passphrase
		}
		entries = append(entries, entry)
	}
	return map[string]interface{}{"enabled": true, "certs": entries}
}

func parseCollectionPresets(raw interface{}) (CollectionPresets, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return CollectionPresets{}, false
	}
	presets := CollectionPresets{
		RequestType: firstYAMLString(valueMap, "requestType", "request_type", "type"),
		RequestURL:  firstYAMLString(valueMap, "requestUrl", "requestURL", "request_url", "url"),
	}
	return normalizeCollectionPresets(presets), true
}

func yamlCollectionPresets(presets CollectionPresets) map[string]interface{} {
	return jsonCollectionPresets(presets)
}

func jsonCollectionPresets(presets CollectionPresets) map[string]interface{} {
	normalized := normalizeCollectionPresets(presets)
	return map[string]interface{}{
		"requestType": brunoPresetRequestType(normalized.RequestType),
		"requestUrl":  normalized.RequestURL,
	}
}

func parseCollectionProtobuf(raw interface{}) (CollectionProtobufConfig, bool) {
	valueMap, ok := mapValue(raw)
	if !ok {
		return CollectionProtobufConfig{}, false
	}
	result := CollectionProtobufConfig{}
	if values, ok := listValue(valueMap["protoFiles"]); ok {
		result.ProtoFiles = make([]CollectionProtoFile, 0, len(values))
		for _, value := range values {
			if valueMap, ok := mapValue(value); ok {
				path := firstYAMLString(valueMap, "path", "filePath", "protoFilePath", "proto_file_path")
				if path == "" {
					continue
				}
				result.ProtoFiles = append(result.ProtoFiles, CollectionProtoFile{
					Path:   path,
					Type:   firstNonEmpty(firstYAMLString(valueMap, "type"), "file"),
					Exists: boolValue(valueMap["exists"], false),
				})
				continue
			}
			if path := strings.TrimSpace(yamlScalarString(value)); path != "" {
				result.ProtoFiles = append(result.ProtoFiles, CollectionProtoFile{Path: path, Type: "file"})
			}
		}
	}
	if values, ok := listValue(valueMap["importPaths"]); ok {
		result.ImportPaths = make([]CollectionProtoImportPath, 0, len(values))
		for _, value := range values {
			if valueMap, ok := mapValue(value); ok {
				path := firstYAMLString(valueMap, "path", "directoryPath", "directory", "dir")
				if path == "" {
					continue
				}
				enabled := true
				if parsed, ok := boolValueOK(valueMap["enabled"]); ok {
					enabled = parsed
				} else if disabled, ok := boolValueOK(valueMap["disabled"]); ok {
					enabled = !disabled
				}
				result.ImportPaths = append(result.ImportPaths, CollectionProtoImportPath{
					Path:    path,
					Enabled: enabled,
					Exists:  boolValue(valueMap["exists"], false),
				})
				continue
			}
			if path := strings.TrimSpace(yamlScalarString(value)); path != "" {
				result.ImportPaths = append(result.ImportPaths, CollectionProtoImportPath{Path: path, Enabled: true})
			}
		}
	}
	return result, true
}

func yamlCollectionProtobuf(protobuf CollectionProtobufConfig) map[string]interface{} {
	normalized := normalizeCollectionProtobuf("", protobuf)
	result := map[string]interface{}{}
	if len(normalized.ProtoFiles) > 0 {
		protoFiles := make([]map[string]interface{}, 0, len(normalized.ProtoFiles))
		for _, protoFile := range normalized.ProtoFiles {
			entry := map[string]interface{}{
				"path": protoFile.Path,
				"type": firstNonEmpty(protoFile.Type, "file"),
			}
			protoFiles = append(protoFiles, entry)
		}
		result["protoFiles"] = protoFiles
	}
	if len(normalized.ImportPaths) > 0 {
		importPaths := make([]map[string]interface{}, 0, len(normalized.ImportPaths))
		for _, importPath := range normalized.ImportPaths {
			importPaths = append(importPaths, map[string]interface{}{
				"path":    importPath.Path,
				"enabled": importPath.Enabled,
			})
		}
		result["importPaths"] = importPaths
	}
	return result
}

func jsonCollectionProtobuf(protobuf CollectionProtobufConfig) map[string]interface{} {
	return yamlCollectionProtobuf(protobuf)
}

func parseOpenAPISyncConfigs(raw interface{}) []OpenAPISyncConfig {
	values, ok := listValue(raw)
	if !ok {
		if valueMap, mapOK := mapValue(raw); mapOK {
			values = []interface{}{valueMap}
			ok = true
		}
	}
	if !ok {
		return nil
	}
	configs := make([]OpenAPISyncConfig, 0, len(values))
	for _, value := range values {
		valueMap, ok := mapValue(value)
		if !ok {
			continue
		}
		config := OpenAPISyncConfig{
			SourceURL:         firstYAMLString(valueMap, "sourceUrl", "sourceURL", "source_url", "url"),
			GroupBy:           firstYAMLString(valueMap, "groupBy", "group_by"),
			LastSyncDate:      firstYAMLString(valueMap, "lastSyncDate", "last_sync_date"),
			SpecHash:          firstYAMLString(valueMap, "specHash", "spec_hash"),
			AutoCheck:         boolValue(valueMap["autoCheck"], true),
			AutoCheckInterval: intValue(valueMap["autoCheckInterval"], 5),
		}
		config = normalizeOpenAPISyncConfig(config)
		if strings.TrimSpace(config.SourceURL) == "" && strings.TrimSpace(config.SpecHash) == "" {
			continue
		}
		configs = append(configs, config)
	}
	return configs
}

func yamlOpenAPISyncConfigs(configs []OpenAPISyncConfig) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(configs))
	for _, config := range configs {
		normalized := normalizeOpenAPISyncConfig(config)
		entry := map[string]interface{}{
			"sourceUrl":         normalized.SourceURL,
			"groupBy":           normalized.GroupBy,
			"autoCheck":         normalized.AutoCheck,
			"autoCheckInterval": normalized.AutoCheckInterval,
		}
		if strings.TrimSpace(normalized.LastSyncDate) != "" {
			entry["lastSyncDate"] = normalized.LastSyncDate
		}
		if strings.TrimSpace(normalized.SpecHash) != "" {
			entry["specHash"] = normalized.SpecHash
		}
		result = append(result, entry)
	}
	return result
}

func jsonOpenAPISyncConfigs(configs []OpenAPISyncConfig) []map[string]interface{} {
	return yamlOpenAPISyncConfigs(configs)
}

func proxyPortValue(port string) interface{} {
	port = strings.TrimSpace(port)
	if port == "" {
		return ""
	}
	if parsed, err := strconv.Atoi(port); err == nil {
		return parsed
	}
	return port
}

func yamlParams(queryParams, pathParams []KeyValue) []map[string]interface{} {
	result := yamlParamsOfType(queryParams, "query")
	result = append(result, yamlParamsOfType(pathParams, "path")...)
	return result
}

func yamlParamsOfType(values []KeyValue, paramType string) []map[string]interface{} {
	result := yamlKeyValues(values)
	for _, value := range result {
		value["type"] = paramType
	}
	return result
}

func yamlMultipart(values []FormPart) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(values))
	for _, part := range values {
		entry := map[string]interface{}{
			"name":    part.Name,
			"enabled": part.Enabled,
		}
		if part.FilePath != "" {
			entry["type"] = "file"
			entry["value"] = part.FilePath
		} else {
			entry["type"] = "text"
			entry["value"] = part.Value
		}
		if strings.TrimSpace(part.ContentType) != "" {
			entry["contentType"] = part.ContentType
		}
		result = append(result, entry)
	}
	return result
}

func yamlVariables(values []Variable) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(values))
	for _, value := range values {
		entry := map[string]interface{}{
			"name":    value.Name,
			"value":   yamlVariableValue(value),
			"enabled": value.Enabled,
		}
		if value.Secret {
			entry["secret"] = true
		}
		result = append(result, entry)
	}
	return result
}

func yamlPostResponseActions(values []Variable) []map[string]interface{} {
	result := make([]map[string]interface{}, 0, len(values))
	for _, value := range values {
		action := map[string]interface{}{
			"type":  "set-variable",
			"phase": "after-response",
			"selector": map[string]interface{}{
				"expression": fmt.Sprint(value.Value),
				"method":     "jsonq",
			},
			"variable": map[string]interface{}{
				"name":  value.Name,
				"scope": "runtime",
			},
		}
		if !value.Enabled {
			action["disabled"] = true
		}
		if value.Secret {
			action["variable"].(map[string]interface{})["secret"] = true
		}
		result = append(result, action)
	}
	return result
}

func yamlVariableValue(value Variable) interface{} {
	dataType := value.DataType
	if dataType == "" {
		dataType = value.Type
	}
	switch dataType {
	case "number", "boolean", "object":
		return map[string]interface{}{"type": dataType, "data": fmt.Sprint(value.Value)}
	default:
		return value.Value
	}
}

func yamlAuth(auth AuthConfig) interface{} {
	switch auth.Mode {
	case "inherit", "none":
		return auth.Mode
	case "basic", "digest", "wsse":
		return map[string]interface{}{"mode": auth.Mode, "username": auth.Username, "password": auth.Password}
	case "ntlm":
		return map[string]interface{}{"mode": "ntlm", "username": auth.Username, "password": auth.Password, "domain": auth.Domain}
	case "bearer", "oauth2":
		if auth.Mode == "oauth2" {
			result := map[string]interface{}{
				"mode":                 "oauth2",
				"token":                auth.Token,
				"grantType":            auth.OAuth2.GrantType,
				"callbackUrl":          auth.OAuth2.CallbackURL,
				"authorizationUrl":     auth.OAuth2.AuthorizationURL,
				"accessTokenUrl":       auth.OAuth2.AccessTokenURL,
				"refreshTokenUrl":      auth.OAuth2.RefreshTokenURL,
				"username":             auth.OAuth2.Username,
				"password":             auth.OAuth2.Password,
				"clientId":             auth.OAuth2.ClientID,
				"clientSecret":         auth.OAuth2.ClientSecret,
				"scope":                auth.OAuth2.Scope,
				"state":                auth.OAuth2.State,
				"pkce":                 auth.OAuth2.PKCE,
				"credentialsPlacement": auth.OAuth2.CredentialsPlacement,
				"credentialsId":        auth.OAuth2.CredentialsID,
				"tokenSource":          auth.OAuth2.TokenSource,
				"tokenPlacement":       auth.OAuth2.TokenPlacement,
				"tokenHeaderPrefix":    auth.OAuth2.TokenHeaderPrefix,
				"tokenQueryKey":        auth.OAuth2.TokenQueryKey,
				"autoFetchToken":       auth.OAuth2.AutoFetchToken,
				"autoRefreshToken":     auth.OAuth2.AutoRefreshToken,
			}
			if additional := yamlOAuth2AdditionalParameters(auth.OAuth2); len(additional) > 0 {
				result["additionalParameters"] = additional
			}
			return result
		}
		return map[string]interface{}{"mode": auth.Mode, "token": auth.Token}
	case "apikey":
		return map[string]interface{}{"mode": "apikey", "key": auth.APIKey, "value": auth.APIValue, "location": auth.APILocation}
	case "awsv4":
		return map[string]interface{}{
			"mode":            "awsv4",
			"accessKeyId":     firstNonEmpty(auth.AWSV4.AccessKeyID, auth.AWSV4.AccessKey),
			"secretAccessKey": firstNonEmpty(auth.AWSV4.SecretAccessKey, auth.AWSV4.SecretKey),
			"sessionToken":    auth.AWSV4.SessionToken,
			"service":         auth.AWSV4.Service,
			"region":          auth.AWSV4.Region,
			"profileName":     auth.AWSV4.ProfileName,
		}
	case "oauth1":
		return map[string]interface{}{
			"mode":              "oauth1",
			"consumerKey":       auth.OAuth1.ConsumerKey,
			"consumerSecret":    auth.OAuth1.ConsumerSecret,
			"accessToken":       auth.OAuth1.AccessToken,
			"accessTokenSecret": auth.OAuth1.AccessTokenSecret,
			"callbackUrl":       auth.OAuth1.CallbackURL,
			"verifier":          auth.OAuth1.Verifier,
			"signatureMethod":   auth.OAuth1.SignatureMethod,
			"privateKey":        auth.OAuth1.PrivateKey,
			"privateKeyType":    auth.OAuth1.PrivateKeyType,
			"timestamp":         auth.OAuth1.Timestamp,
			"nonce":             auth.OAuth1.Nonce,
			"version":           auth.OAuth1.Version,
			"realm":             auth.OAuth1.Realm,
			"placement":         auth.OAuth1.Placement,
			"includeBodyHash":   auth.OAuth1.IncludeBodyHash,
		}
	default:
		return auth.Mode
	}
}

func appendScript(existing, next string) string {
	if strings.TrimSpace(next) == "" {
		return existing
	}
	if strings.TrimSpace(existing) == "" {
		return next
	}
	return existing + "\n" + next
}

func mapValue(raw interface{}) (map[string]interface{}, bool) {
	value, ok := raw.(map[string]interface{})
	if ok {
		return value, true
	}
	legacy, ok := raw.(map[interface{}]interface{})
	if !ok {
		return nil, false
	}
	out := map[string]interface{}{}
	for key, value := range legacy {
		out[fmt.Sprint(key)] = value
	}
	return out, true
}

func listValue(raw interface{}) ([]interface{}, bool) {
	values, ok := raw.([]interface{})
	return values, ok
}

func yamlScalarString(raw interface{}) string {
	if raw == nil {
		return ""
	}
	if valueMap, ok := mapValue(raw); ok {
		if data, ok := valueMap["data"]; ok {
			return yamlScalarString(data)
		}
	}
	switch value := raw.(type) {
	case string:
		return value
	case []byte:
		return string(value)
	case bool:
		return strconv.FormatBool(value)
	case int:
		return strconv.Itoa(value)
	case int64:
		return strconv.FormatInt(value, 10)
	case float64:
		return strconv.FormatFloat(value, 'f', -1, 64)
	default:
		data, err := json.Marshal(value)
		if err == nil {
			return string(data)
		}
		return fmt.Sprint(value)
	}
}

func firstYAMLString(raw map[string]interface{}, keys ...string) string {
	for _, key := range keys {
		if value := strings.TrimSpace(yamlScalarString(raw[key])); value != "" {
			return value
		}
	}
	return ""
}

func firstMapValue(raw map[string]interface{}, keys ...string) interface{} {
	for _, key := range keys {
		if value, ok := raw[key]; ok {
			return value
		}
	}
	return nil
}

func yamlEnabled(raw map[string]interface{}) bool {
	if enabled, ok := boolValueOK(raw["enabled"]); ok {
		return enabled
	}
	if disabled, ok := boolValueOK(raw["disabled"]); ok {
		return !disabled
	}
	return true
}

func intValue(raw interface{}, fallback int) int {
	if value, ok := intValueOK(raw); ok {
		return value
	}
	return fallback
}

func intValueOK(raw interface{}) (int, bool) {
	switch value := raw.(type) {
	case int:
		return value, true
	case int64:
		return int(value), true
	case float64:
		return int(value), true
	case string:
		parsed, err := strconv.Atoi(strings.TrimSpace(value))
		return parsed, err == nil
	default:
		return 0, false
	}
}

func boolValue(raw interface{}, fallback bool) bool {
	if value, ok := boolValueOK(raw); ok {
		return value
	}
	return fallback
}

func boolValueOK(raw interface{}) (bool, bool) {
	switch value := raw.(type) {
	case bool:
		return value, true
	case string:
		parsed, err := strconv.ParseBool(strings.TrimSpace(value))
		return parsed, err == nil
	default:
		return false, false
	}
}

func parseBruSections(content string) map[string][]string {
	sections := map[string][]string{}
	active := ""
	closeToken := ""
	for _, line := range strings.Split(content, "\n") {
		trimmed := strings.TrimSpace(line)
		if active != "" {
			if isBruSectionClose(line, closeToken) {
				active = ""
				closeToken = ""
				continue
			}
			sections[active] = append(sections[active], line)
			continue
		}
		if name, close, ok := bruSectionOpen(line); ok {
			active = name
			closeToken = close
			if _, ok := sections[active]; !ok {
				sections[active] = []string{}
			}
			continue
		}
		if trimmed == "" {
			continue
		}
	}
	return sections
}

func parseBruNamedBlocks(content, target string) [][]string {
	blocks := [][]string{}
	active := false
	closeToken := ""
	current := []string{}
	for _, line := range strings.Split(content, "\n") {
		if active {
			if isBruSectionClose(line, closeToken) {
				blocks = append(blocks, current)
				active = false
				closeToken = ""
				current = []string{}
				continue
			}
			current = append(current, line)
			continue
		}
		if name, close, ok := bruSectionOpen(line); ok && name == target {
			active = true
			closeToken = close
			current = []string{}
		}
	}
	return blocks
}

func bruSectionOpen(line string) (string, string, bool) {
	if strings.TrimLeft(line, " \t") != line {
		return "", "", false
	}
	trimmed := strings.TrimSpace(line)
	if strings.HasSuffix(trimmed, "{") {
		return strings.TrimSpace(strings.TrimSuffix(trimmed, "{")), "}", true
	}
	if strings.HasSuffix(trimmed, "[") {
		return strings.TrimSpace(strings.TrimSuffix(trimmed, "[")), "]", true
	}
	return "", "", false
}

func isBruSectionClose(line, closeToken string) bool {
	return strings.TrimLeft(line, " \t") == line && strings.TrimSpace(line) == closeToken
}

func parseOAuth1PrivateKeyValue(value string) (string, string) {
	value = strings.TrimSpace(value)
	if strings.HasPrefix(value, "@file(") && strings.HasSuffix(value, ")") {
		return strings.TrimSuffix(strings.TrimPrefix(value, "@file("), ")"), "file"
	}
	return value, "text"
}

func oauth1PrivateKeyBruValue(auth OAuth1Auth) string {
	if auth.PrivateKeyType == "file" && auth.PrivateKey != "" {
		return "@file(" + auth.PrivateKey + ")"
	}
	return auth.PrivateKey
}

func parseBruScalarMap(lines []string) map[string]string {
	values := map[string]string{}
	for i := 0; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed == "" || strings.HasPrefix(trimmed, "@") {
			continue
		}
		key, value, ok := strings.Cut(trimmed, ":")
		if !ok {
			continue
		}
		key = strings.TrimSpace(key)
		value = strings.TrimSpace(value)
		if value == "'''" {
			collected := []string{}
			for i++; i < len(lines); i++ {
				if strings.TrimSpace(lines[i]) == "'''" {
					break
				}
				collected = append(collected, strings.TrimPrefix(lines[i], "    "))
			}
			value = strings.TrimRight(strings.Join(collected, "\n"), "\n")
		}
		values[key] = strings.TrimSuffix(value, ",")
	}
	return values
}

func parseBruScalarMapDedented(lines []string) map[string]string {
	values := map[string]string{}
	for i := 0; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed == "" || strings.HasPrefix(trimmed, "@") || strings.HasSuffix(trimmed, "{") {
			continue
		}
		key, value, ok := strings.Cut(trimmed, ":")
		if !ok {
			continue
		}
		key = strings.TrimSpace(key)
		value = strings.TrimSpace(value)
		if value == "'''" {
			collected := []string{}
			for i++; i < len(lines); i++ {
				if strings.TrimSpace(lines[i]) == "'''" {
					break
				}
				collected = append(collected, lines[i])
			}
			value = strings.TrimRight(dedentBruLines(collected), "\n")
		}
		values[key] = strings.TrimSuffix(value, ",")
	}
	return values
}

func dedentBruLines(lines []string) string {
	minIndent := -1
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			continue
		}
		indent := leadingWhitespace(line)
		if minIndent < 0 || indent < minIndent {
			minIndent = indent
		}
	}
	if minIndent < 0 {
		minIndent = 0
	}
	out := make([]string, 0, len(lines))
	for _, line := range lines {
		if len(line) >= minIndent {
			out = append(out, line[minIndent:])
		} else {
			out = append(out, strings.TrimLeft(line, " \t"))
		}
	}
	return strings.Join(out, "\n")
}

func leadingWhitespace(line string) int {
	count := 0
	for count < len(line) && (line[count] == ' ' || line[count] == '\t') {
		count++
	}
	return count
}

func collectBruColonBlock(lines []string, name string) []string {
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed != name+": {" && trimmed != name+" {" {
			continue
		}
		indent := leadingWhitespace(line)
		collected := []string{}
		for j := i + 1; j < len(lines); j++ {
			if leadingWhitespace(lines[j]) == indent && strings.TrimSpace(lines[j]) == "}" {
				return collected
			}
			collected = append(collected, lines[j])
		}
		return collected
	}
	return nil
}

func parseBruKeyValues(lines []string) []KeyValue {
	result := []KeyValue{}
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "@") {
			continue
		}
		key, value, ok := strings.Cut(trimmed, ":")
		if !ok {
			continue
		}
		name := strings.TrimSpace(key)
		enabled := true
		if strings.HasPrefix(name, "~") {
			enabled = false
			name = strings.TrimPrefix(name, "~")
		}
		if name == "" {
			continue
		}
		result = append(result, KeyValue{Name: name, Value: strings.TrimSpace(value), Enabled: enabled})
	}
	return result
}

func parseBruMultipartValues(lines []string) []FormPart {
	result := []FormPart{}
	filePattern := regexp.MustCompile(`@file\(([^)]*)\)`)
	contentTypePattern := regexp.MustCompile(`@contentType\(([^)]*)\)`)
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "@") {
			continue
		}
		key, value, ok := strings.Cut(trimmed, ":")
		if !ok {
			continue
		}
		name := strings.TrimSpace(key)
		enabled := true
		if strings.HasPrefix(name, "~") {
			enabled = false
			name = strings.TrimPrefix(name, "~")
		}
		if name == "" {
			continue
		}
		value = strings.TrimSpace(value)
		part := FormPart{Name: name, Enabled: enabled}
		if match := contentTypePattern.FindStringSubmatch(value); len(match) == 2 {
			part.ContentType = strings.TrimSpace(match[1])
			value = strings.TrimSpace(contentTypePattern.ReplaceAllString(value, ""))
		}
		if match := filePattern.FindStringSubmatch(value); len(match) == 2 {
			part.FilePath = strings.TrimSpace(match[1])
		} else {
			part.Value = strings.TrimSpace(value)
		}
		result = append(result, part)
	}
	return result
}

func parseBruFileBody(lines []string) []FileBodyEntry {
	parts := parseBruMultipartValues(lines)
	result := make([]FileBodyEntry, 0, len(parts))
	for i := range parts {
		if strings.TrimSpace(parts[i].FilePath) == "" && strings.TrimSpace(parts[i].ContentType) == "" {
			continue
		}
		result = append(result, FileBodyEntry{
			FilePath:    parts[i].FilePath,
			ContentType: parts[i].ContentType,
			Selected:    parts[i].Enabled,
		})
	}
	return result
}

func parseBruGrpcMessages(content string) []GrpcMessage {
	blocks := parseBruNamedBlocks(content, "body:grpc")
	if len(blocks) == 0 {
		return nil
	}
	result := make([]GrpcMessage, 0, len(blocks))
	for index, block := range blocks {
		values := parseBruScalarMap(block)
		name := strings.TrimSpace(firstNonEmpty(values["name"], values["title"]))
		messageContent := values["content"]
		if strings.TrimSpace(name) == "" && strings.TrimSpace(messageContent) == "" {
			continue
		}
		if strings.TrimSpace(name) == "" {
			name = fmt.Sprintf("message %d", index+1)
		}
		result = append(result, GrpcMessage{Name: name, Content: messageContent})
	}
	return result
}

func parseBruWSMessages(content string) []WSMessage {
	blocks := parseBruNamedBlocks(content, "body:ws")
	if len(blocks) == 0 {
		return nil
	}
	result := make([]WSMessage, 0, len(blocks))
	for index, block := range blocks {
		values := parseBruScalarMap(block)
		name := strings.TrimSpace(firstNonEmpty(values["name"], values["title"]))
		messageContent := firstNonEmpty(values["content"], values["data"])
		if strings.TrimSpace(name) == "" && strings.TrimSpace(messageContent) == "" {
			continue
		}
		if strings.TrimSpace(name) == "" && len(blocks) > 1 {
			name = fmt.Sprintf("message %d", index+1)
		}
		result = append(result, WSMessage{
			Name:     name,
			Type:     normalizeWSMessageType(values["type"]),
			Content:  messageContent,
			Selected: strings.EqualFold(values["selected"], "true"),
		})
	}
	return result
}

func oauth2AdditionalParamsFromKeyValues(rows []KeyValue, sendIn string) []OAuth2AdditionalParam {
	result := make([]OAuth2AdditionalParam, 0, len(rows))
	for _, row := range rows {
		result = append(result, OAuth2AdditionalParam{
			Name:        row.Name,
			Value:       row.Value,
			SendIn:      normalizeOAuth2AdditionalPlacement(sendIn),
			Enabled:     row.Enabled,
			Secret:      row.Secret,
			Description: row.Description,
		})
	}
	return result
}

func oauth2KeyValuesFromAdditionalParams(params []OAuth2AdditionalParam, sendIn string) []KeyValue {
	sendIn = normalizeOAuth2AdditionalPlacement(sendIn)
	result := []KeyValue{}
	for _, param := range params {
		if normalizeOAuth2AdditionalPlacement(param.SendIn) != sendIn || strings.TrimSpace(param.Name) == "" {
			continue
		}
		result = append(result, KeyValue{
			Name:        param.Name,
			Value:       param.Value,
			Enabled:     param.Enabled,
			Secret:      param.Secret,
			Description: param.Description,
		})
	}
	return result
}

func parseBruVariables(lines []string, secret bool) []Variable {
	variables := []Variable{}
	currentType := "string"
	for i := 0; i < len(lines); i++ {
		trimmed := strings.TrimSpace(lines[i])
		if trimmed == "" {
			continue
		}
		if strings.HasPrefix(trimmed, "@") && !strings.Contains(trimmed, ":") {
			currentType = strings.ToLower(strings.TrimSpace(strings.TrimPrefix(trimmed, "@")))
			if currentType == "" {
				currentType = "string"
			}
			continue
		}
		if secret {
			name := strings.Trim(strings.TrimSuffix(trimmed, ","), " \t")
			if name == "" {
				continue
			}
			variables = append(variables, Variable{ID: newID("var"), Name: name, Value: "", DataType: currentType, Type: currentType, Enabled: true, Secret: true})
			currentType = "string"
			continue
		}
		key, value, ok := strings.Cut(trimmed, ":")
		if !ok {
			continue
		}
		name := strings.TrimSpace(key)
		enabled := true
		if strings.HasPrefix(name, "~") {
			enabled = false
			name = strings.TrimPrefix(name, "~")
		}
		name = responseVariableRuntimeName(name)
		value = strings.TrimSpace(value)
		if value == "'''" {
			collected := []string{}
			for i++; i < len(lines); i++ {
				if strings.TrimSpace(lines[i]) == "'''" {
					break
				}
				collected = append(collected, strings.TrimPrefix(lines[i], "    "))
			}
			value = strings.TrimRight(strings.Join(collected, "\n"), "\n")
		}
		parsed, dataType := parseBruTypedScalar(value, currentType)
		variables = append(variables, Variable{ID: newID("var"), Name: name, Value: parsed, DataType: dataType, Type: dataType, Enabled: enabled, Secret: false})
		currentType = "string"
	}
	return variables
}

func parseBruTypedScalar(value, dataType string) (interface{}, string) {
	switch dataType {
	case "number":
		if strings.ContainsAny(value, ".eE") {
			if parsed, err := strconv.ParseFloat(value, 64); err == nil {
				return parsed, "number"
			}
		}
		if parsed, err := strconv.Atoi(value); err == nil {
			return parsed, "number"
		}
		return value, "number"
	case "boolean":
		if parsed, err := strconv.ParseBool(value); err == nil {
			return parsed, "boolean"
		}
		return value, "boolean"
	case "object":
		return value, "object"
	default:
		return value, "string"
	}
}

func normalizeBruRequestType(value string) string {
	switch strings.ToLower(value) {
	case "ws", "websocket":
		return "websocket"
	case "graphql":
		return "graphql"
	case "grpc":
		return "grpc"
	default:
		return "http"
	}
}

func normalizeBruBodyMode(value string) string {
	switch strings.ToLower(strings.TrimSpace(value)) {
	case "graphql":
		return "graphql"
	case "ws":
		return "text"
	default:
		return normalizeBodyMode(value)
	}
}

func applyBruAuthSections(auth *AuthConfig, sections map[string][]string) {
	if lines, ok := sections["auth"]; ok {
		values := parseBruScalarMap(lines)
		if mode := strings.TrimSpace(values["mode"]); mode != "" {
			auth.Mode = mode
		}
	}
	if auth.APILocation == "" {
		auth.APILocation = "header"
	}
	if lines, ok := sections["auth:basic"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "basic"
		auth.Username = values["username"]
		auth.Password = values["password"]
	}
	if lines, ok := sections["auth:digest"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "digest"
		auth.Username = values["username"]
		auth.Password = values["password"]
	}
	if lines, ok := sections["auth:wsse"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "wsse"
		auth.Username = values["username"]
		auth.Password = values["password"]
	}
	if lines, ok := sections["auth:ntlm"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "ntlm"
		auth.Username = values["username"]
		auth.Password = values["password"]
		auth.Domain = values["domain"]
	}
	if lines, ok := sections["auth:bearer"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "bearer"
		auth.Token = firstNonEmpty(values["token"], values["accessToken"])
	}
	if lines, ok := sections["auth:apikey"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "apikey"
		auth.APIKey = firstNonEmpty(values["key"], values["name"])
		auth.APIValue = values["value"]
		auth.APILocation = firstNonEmpty(strings.ToLower(values["placement"]), strings.ToLower(values["location"]), "header")
	}
	if lines, ok := sections["auth:awsv4"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "awsv4"
		auth.AWSV4.AccessKeyID = firstNonEmpty(values["accessKeyId"], values["accessKey"])
		auth.AWSV4.SecretAccessKey = firstNonEmpty(values["secretAccessKey"], values["secretKey"])
		auth.AWSV4.SessionToken = values["sessionToken"]
		auth.AWSV4.Service = values["service"]
		auth.AWSV4.Region = values["region"]
		auth.AWSV4.ProfileName = values["profileName"]
	}
	if lines, ok := sections["auth:oauth1"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "oauth1"
		auth.OAuth1.ConsumerKey = values["consumer_key"]
		auth.OAuth1.ConsumerSecret = values["consumer_secret"]
		auth.OAuth1.AccessToken = values["access_token"]
		auth.OAuth1.AccessTokenSecret = values["token_secret"]
		auth.OAuth1.CallbackURL = values["callback_url"]
		auth.OAuth1.Verifier = values["verifier"]
		auth.OAuth1.SignatureMethod = values["signature_method"]
		auth.OAuth1.PrivateKey, auth.OAuth1.PrivateKeyType = parseOAuth1PrivateKeyValue(values["private_key"])
		auth.OAuth1.Timestamp = values["timestamp"]
		auth.OAuth1.Nonce = values["nonce"]
		auth.OAuth1.Version = values["version"]
		auth.OAuth1.Realm = values["realm"]
		auth.OAuth1.Placement = values["placement"]
		auth.OAuth1.IncludeBodyHash = strings.EqualFold(values["include_body_hash"], "true")
	}
	if lines, ok := sections["auth:oauth2"]; ok {
		values := parseBruScalarMap(lines)
		auth.Mode = "oauth2"
		auth.Token = firstNonEmpty(values["accessToken"], values["access_token"], values["token"])
		auth.OAuth2.GrantType = firstNonEmpty(values["grant_type"], values["grantType"])
		auth.OAuth2.CallbackURL = firstNonEmpty(values["callback_url"], values["callbackUrl"])
		auth.OAuth2.AuthorizationURL = firstNonEmpty(values["authorization_url"], values["authorizationUrl"])
		auth.OAuth2.AccessTokenURL = firstNonEmpty(values["access_token_url"], values["accessTokenUrl"])
		auth.OAuth2.RefreshTokenURL = firstNonEmpty(values["refresh_token_url"], values["refreshTokenUrl"])
		auth.OAuth2.Username = values["username"]
		auth.OAuth2.Password = values["password"]
		auth.OAuth2.ClientID = firstNonEmpty(values["client_id"], values["clientId"])
		auth.OAuth2.ClientSecret = firstNonEmpty(values["client_secret"], values["clientSecret"])
		auth.OAuth2.Scope = values["scope"]
		auth.OAuth2.State = values["state"]
		auth.OAuth2.PKCE = strings.EqualFold(values["pkce"], "true")
		auth.OAuth2.CredentialsPlacement = firstNonEmpty(values["credentials_placement"], values["credentialsPlacement"])
		auth.OAuth2.CredentialsID = firstNonEmpty(values["credentials_id"], values["credentialsId"])
		auth.OAuth2.TokenSource = firstNonEmpty(values["token_source"], values["tokenSource"])
		auth.OAuth2.TokenPlacement = firstNonEmpty(values["token_placement"], values["tokenPlacement"])
		auth.OAuth2.TokenHeaderPrefix = firstNonEmpty(values["token_header_prefix"], values["tokenHeaderPrefix"])
		auth.OAuth2.TokenQueryKey = firstNonEmpty(values["token_query_key"], values["tokenQueryKey"])
		auth.OAuth2.AutoFetchToken = strings.EqualFold(firstNonEmpty(values["auto_fetch_token"], values["autoFetchToken"]), "true")
		auth.OAuth2.AutoRefreshToken = strings.EqualFold(firstNonEmpty(values["auto_refresh_token"], values["autoRefreshToken"]), "true")
	}
	auth.OAuth2.AuthorizationAdditionalParams = append(
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:auth_req:headers"]), "headers"),
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:auth_req:queryparams"]), "queryparams")...,
	)
	auth.OAuth2.TokenAdditionalParams = append(
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:access_token_req:headers"]), "headers"),
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:access_token_req:queryparams"]), "queryparams")...,
	)
	auth.OAuth2.TokenAdditionalParams = append(
		auth.OAuth2.TokenAdditionalParams,
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:access_token_req:body"]), "body")...,
	)
	auth.OAuth2.RefreshAdditionalParams = append(
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:refresh_token_req:headers"]), "headers"),
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:refresh_token_req:queryparams"]), "queryparams")...,
	)
	auth.OAuth2.RefreshAdditionalParams = append(
		auth.OAuth2.RefreshAdditionalParams,
		oauth2AdditionalParamsFromKeyValues(parseBruKeyValues(sections["auth:oauth2:additional_params:refresh_token_req:body"]), "body")...,
	)
}

func parseBruAssertions(lines []string) []Assertion {
	assertions := []Assertion{}
	for _, line := range lines {
		key, value, ok := strings.Cut(strings.TrimSpace(line), ":")
		if !ok {
			continue
		}
		parts := strings.Fields(strings.TrimSpace(value))
		if len(parts) < 2 {
			continue
		}
		assertions = append(assertions, Assertion{Expression: strings.TrimSpace(key), Operator: bruAssertionOperator(parts[0]), Value: strings.Join(parts[1:], " "), Enabled: true})
	}
	return assertions
}

func bruAssertionOperator(value string) string {
	switch value {
	case "eq":
		return "equals"
	case "neq":
		return "notEquals"
	default:
		return value
	}
}

func applyBruSettings(item *RequestItem, values map[string]string) {
	if encodeURL, err := strconv.ParseBool(values["encodeUrl"]); err == nil {
		item.Settings.EncodeURL = encodeURL
	}
	if timeout, err := strconv.Atoi(values["timeout"]); err == nil {
		item.Settings.TimeoutMs = timeout
	}
	if follow, err := strconv.ParseBool(values["followRedirects"]); err == nil {
		item.Settings.FollowRedirects = follow
	}
	if maxRedirects, err := strconv.Atoi(values["maxRedirects"]); err == nil {
		item.Settings.MaxRedirects = maxRedirects
	}
	if storeCookies, err := strconv.ParseBool(values["storeCookies"]); err == nil {
		item.Settings.StoreCookies = storeCookies
	}
	if verifyTLS, err := strconv.ParseBool(values["verifyTls"]); err == nil {
		item.Settings.VerifyTLS = verifyTLS
	}
	if keepAliveInterval, err := strconv.Atoi(values["keepAliveInterval"]); err == nil {
		item.Settings.KeepAliveInterval = keepAliveInterval
	}
}

func joinBruLines(lines []string) string {
	return strings.Join(lines, "\n")
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		if strings.TrimSpace(value) != "" {
			return value
		}
	}
	return ""
}

func parseBruExamples(content string, item RequestItem) []ResponseExample {
	blocks := parseBruNamedBlocks(content, "example")
	examples := make([]ResponseExample, 0, len(blocks))
	for index, block := range blocks {
		examples = append(examples, parseBruExampleBlock(block, item, index))
	}
	return examples
}

func parseBruExampleBlock(lines []string, item RequestItem, index int) ResponseExample {
	values := parseBruScalarMapDedented(lines)
	name := strings.TrimSpace(values["name"])
	if name == "" {
		name = fmt.Sprintf("Example %d", index+1)
	}
	example := ResponseExample{
		ID:          deterministicID("example", firstNonEmpty(item.FilePath, item.ID, item.Name)+"#example#"+strconv.Itoa(index)),
		Name:        name,
		Description: values["description"],
		Type:        firstNonEmpty(item.Type, "http"),
		Request: ResponseExampleRequest{
			Method:   strings.ToUpper(firstNonEmpty(item.Method, http.MethodGet)),
			URL:      item.URL,
			BodyMode: "none",
		},
		Response: ResponseExamplePayload{
			Status:     http.StatusOK,
			StatusText: http.StatusText(http.StatusOK),
			BodyType:   "text",
		},
	}
	if requestLines := collectBruColonBlock(lines, "request"); len(requestLines) > 0 {
		applyBruExampleRequest(&example, requestLines)
	}
	if responseLines := collectBruColonBlock(lines, "response"); len(responseLines) > 0 {
		applyBruExampleResponse(&example, responseLines)
	}
	return example
}

func applyBruExampleRequest(example *ResponseExample, lines []string) {
	values := parseBruScalarMapDedented(lines)
	if method := strings.TrimSpace(values["method"]); method != "" {
		example.Request.Method = strings.ToUpper(method)
	}
	if targetURL := strings.TrimSpace(values["url"]); targetURL != "" {
		example.Request.URL = targetURL
	}
	if mode := normalizeBruBodyMode(firstNonEmpty(values["mode"], values["body"])); mode != "" {
		example.Request.BodyMode = mode
	}
	if headers := collectBruColonBlock(lines, "headers"); len(headers) > 0 {
		example.Request.Headers = parseBruKeyValues(headers)
	}
	if params := collectBruColonBlock(lines, "params"); len(params) > 0 {
		example.Request.Params = parseBruKeyValues(params)
	}
	if body := collectBruColonBlock(lines, "body"); len(body) > 0 {
		bodyValues := parseBruScalarMapDedented(body)
		example.Request.BodyMode = normalizeBruBodyMode(firstNonEmpty(bodyValues["type"], example.Request.BodyMode))
		example.Request.Body = bodyValues["content"]
	}
	if body := collectBruColonBlock(lines, "body:form-urlencoded"); len(body) > 0 {
		example.Request.BodyMode = "formUrlEncoded"
		example.Request.FormURLEncoded = parseBruKeyValues(body)
	}
	if body := collectBruColonBlock(lines, "body:multipart-form"); len(body) > 0 {
		example.Request.BodyMode = "multipartForm"
		example.Request.MultipartForm = parseBruMultipartValues(body)
	}
	if body := collectBruColonBlock(lines, "body:file"); len(body) > 0 {
		example.Request.BodyMode = "file"
		example.Request.File = parseBruFileBody(body)
	}
}

func applyBruExampleResponse(example *ResponseExample, lines []string) {
	values := parseBruScalarMapDedented(lines)
	if duration, err := strconv.ParseInt(firstNonEmpty(values["duration"], values["durationMs"]), 10, 64); err == nil && duration >= 0 {
		example.Response.DurationMs = duration
	}
	if statusText := strings.TrimSpace(values["statusText"]); statusText != "" {
		example.Response.StatusText = statusText
	}
	if statusLines := collectBruColonBlock(lines, "status"); len(statusLines) > 0 {
		statusValues := parseBruScalarMapDedented(statusLines)
		if status, err := strconv.Atoi(firstNonEmpty(statusValues["code"], statusValues["status"])); err == nil {
			example.Response.Status = status
		}
		if statusText := strings.TrimSpace(firstNonEmpty(statusValues["text"], statusValues["statusText"])); statusText != "" {
			example.Response.StatusText = cleanStatusText(example.Response.Status, statusText)
		}
	}
	if example.Response.StatusText == "" {
		example.Response.StatusText = http.StatusText(example.Response.Status)
	}
	if headers := collectBruColonBlock(lines, "headers"); len(headers) > 0 {
		example.Response.Headers = parseBruKeyValues(headers)
	}
	if body := collectBruColonBlock(lines, "body"); len(body) > 0 {
		bodyValues := parseBruScalarMapDedented(body)
		example.Response.BodyType = firstNonEmpty(bodyValues["type"], "text")
		example.Response.Body = bodyValues["content"]
		example.Response.Size = len([]byte(example.Response.Body))
	}
}

func parseBru(content string) (RequestItem, error) {
	sections := parseBruSections(content)
	item := defaultRequest("Imported request", "http", 1)
	if meta, ok := sections["meta"]; ok {
		values := parseBruScalarMap(meta)
		if name := strings.TrimSpace(values["name"]); name != "" {
			item.Name = name
		}
		if requestType := strings.ToLower(strings.TrimSpace(values["type"])); requestType != "" {
			item.Type = normalizeBruRequestType(requestType)
		}
		if seq, err := strconv.Atoi(values["seq"]); err == nil && seq > 0 {
			item.Seq = seq
		}
	}
	if item.Type == "graphql" {
		item.Body.Mode = "graphql"
	}
	if item.Type == "websocket" {
		item.Method = "CONNECT"
		item.Body.Mode = "ws"
	}
	if item.Type == "grpc" {
		item.Method = "CALL"
		item.Body.Mode = "grpc"
		item.URL = "grpc://localhost:50051"
	}
	for _, method := range []string{"get", "post", "put", "patch", "delete", "head", "options", "trace"} {
		lines, ok := sections[method]
		if !ok {
			continue
		}
		values := parseBruScalarMap(lines)
		item.Method = strings.ToUpper(method)
		if targetURL := strings.TrimSpace(values["url"]); targetURL != "" {
			item.URL = targetURL
		}
		if mode := strings.TrimSpace(values["body"]); mode != "" {
			item.Body.Mode = normalizeBruBodyMode(mode)
		}
		if auth := strings.TrimSpace(values["auth"]); auth != "" {
			item.Auth.Mode = auth
		}
	}
	if lines, ok := sections["ws"]; ok {
		values := parseBruScalarMap(lines)
		item.Type = "websocket"
		item.Method = "CONNECT"
		if targetURL := strings.TrimSpace(values["url"]); targetURL != "" {
			item.URL = targetURL
		}
		if auth := strings.TrimSpace(values["auth"]); auth != "" {
			item.Auth.Mode = auth
		}
	}
	if lines, ok := sections["grpc"]; ok {
		values := parseBruScalarMap(lines)
		item.Type = "grpc"
		item.Body.Mode = "grpc"
		if method := firstNonEmpty(values["method"], values["service"]); strings.TrimSpace(method) != "" {
			item.Method = method
		}
		if targetURL := strings.TrimSpace(values["url"]); targetURL != "" {
			item.URL = targetURL
		}
		if mode := strings.TrimSpace(values["body"]); mode != "" {
			item.Body.Mode = normalizeBruBodyMode(mode)
		}
		if auth := strings.TrimSpace(values["auth"]); auth != "" {
			item.Auth.Mode = auth
		}
		item.GrpcMethodType = strings.TrimSpace(values["methodType"])
		item.ProtoPath = strings.TrimSpace(values["protoPath"])
	}
	if lines, ok := sections["headers"]; ok {
		item.Headers = parseBruKeyValues(lines)
	}
	if item.Type == "grpc" {
		if lines, ok := sections["metadata"]; ok {
			item.Headers = parseBruKeyValues(lines)
		}
		item.GrpcMessages = parseBruGrpcMessages(content)
		if len(item.GrpcMessages) > 0 {
			item.Body.Mode = "grpc"
		}
	}
	if lines, ok := sections["params:query"]; ok {
		item.Params = parseBruKeyValues(lines)
	}
	if lines, ok := sections["params:path"]; ok {
		item.PathParams = parseBruKeyValues(lines)
	}
	if lines, ok := sections["body:json"]; ok {
		item.Body.Mode = "json"
		item.Body.JSON = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:xml"]; ok {
		item.Body.Mode = "xml"
		item.Body.XML = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:text"]; ok {
		item.Body.Mode = "text"
		item.Body.Text = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:sparql"]; ok {
		item.Body.Mode = "sparql"
		item.Body.Text = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:graphql"]; ok {
		item.Type = "graphql"
		item.Body.Mode = "graphql"
		item.Body.GraphQLQuery = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:graphql:vars"]; ok {
		item.Type = "graphql"
		item.Body.Mode = "graphql"
		item.Body.GraphQLVariables = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["body:form-urlencoded"]; ok {
		item.Body.Mode = "formUrlEncoded"
		item.Body.FormURLEncoded = parseBruKeyValues(lines)
	}
	if lines, ok := sections["body:multipart-form"]; ok {
		item.Body.Mode = "multipartForm"
		item.Body.Multipart = parseBruMultipartValues(lines)
	}
	if lines, ok := sections["body:file"]; ok {
		item.Body.Mode = "file"
		item.Body.Files = parseBruFileBody(lines)
		item.Body.FilePath, item.Body.FileContentType = selectedFileBodyFields(item.Body.Files)
	}
	if lines, ok := sections["body:ws"]; ok {
		item.Type = "websocket"
		item.Method = "CONNECT"
		item.Body.Mode = "ws"
		item.WSMessages = parseBruWSMessages(content)
		if len(item.WSMessages) == 0 {
			values := parseBruScalarMap(lines)
			mode := normalizeBruBodyMode(values["type"])
			if mode == "none" {
				mode = "text"
			}
			item.Body.Mode = mode
			assignYAMLBodyData(&item.Body, mode, firstNonEmpty(values["content"], values["data"]))
		}
	}
	applyBruAuthSections(&item.Auth, sections)
	if lines, ok := sections["vars:pre-request"]; ok {
		item.Vars.Req = parseBruVariables(lines, false)
	}
	if lines, ok := sections["vars:post-response"]; ok {
		item.Vars.Res = parseBruVariables(lines, false)
	}
	if lines, ok := sections["script:pre-request"]; ok {
		item.PreScript = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["script:post-response"]; ok {
		item.PostScript = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["tests"]; ok {
		item.Tests = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["docs"]; ok {
		item.Docs = strings.TrimSpace(joinBruLines(lines))
	}
	if lines, ok := sections["assert"]; ok {
		item.Assertions = parseBruAssertions(lines)
	}
	if lines, ok := sections["settings"]; ok {
		applyBruSettings(&item, parseBruScalarMap(lines))
	}
	item.Examples = parseBruExamples(content, item)
	if item.Name == "" {
		return RequestItem{}, errors.New("bru meta.name is required")
	}
	return item, nil
}

func parseBruCollectionMetadata(collection *Collection, content string) error {
	sections := parseBruSections(content)
	if meta, ok := sections["meta"]; ok {
		values := parseBruScalarMap(meta)
		if name := strings.TrimSpace(values["name"]); name != "" {
			collection.Name = name
		}
	}
	if lines, ok := sections["headers"]; ok {
		collection.Headers = parseBruKeyValues(lines)
	}
	if lines, ok := sections["vars:pre-request"]; ok {
		collection.Variables = parseBruVariables(lines, false)
	} else if lines, ok := sections["vars"]; ok {
		collection.Variables = parseBruVariables(lines, false)
	}
	if lines, ok := sections["vars:post-response"]; ok {
		collection.ResVariables = parseBruVariables(lines, false)
	}
	applyBruAuthSections(&collection.Auth, sections)
	if lines, ok := sections["script:pre-request"]; ok {
		collection.PreScript = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["script:post-response"]; ok {
		collection.PostScript = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["tests"]; ok {
		collection.Tests = strings.TrimRight(joinBruLines(lines), "\n")
	}
	if lines, ok := sections["docs"]; ok {
		collection.Docs = strings.TrimSpace(joinBruLines(lines))
	}
	return nil
}

func readCollectionEnvironments(collectionPath string, ignorePatterns []string) ([]Environment, error) {
	envPath := filepath.Join(collectionPath, "environments")
	info, err := os.Stat(envPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	if !info.IsDir() {
		return nil, nil
	}
	entries, err := os.ReadDir(envPath)
	if err != nil {
		return nil, err
	}
	environments := []Environment{}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		path := filepath.Join(envPath, entry.Name())
		if collectionPathIgnored(collectionPath, path, ignorePatterns) {
			continue
		}
		ext := strings.ToLower(filepath.Ext(path))
		switch ext {
		case ".bru":
			content, err := os.ReadFile(path)
			if err != nil {
				return nil, err
			}
			environments = append(environments, parseBruEnvironmentFile(strings.TrimSuffix(entry.Name(), ext), string(content)))
		case ".yml", ".yaml":
			env, err := parseYAMLEnvironmentFile(path)
			if err != nil {
				return nil, err
			}
			environments = append(environments, env)
		}
	}
	sort.SliceStable(environments, func(i, j int) bool {
		return strings.ToLower(environments[i].Name) < strings.ToLower(environments[j].Name)
	})
	return environments, nil
}

func readWorkspaceGlobalEnvironments(workspacePath string) ([]Environment, error) {
	envPath := filepath.Join(workspacePath, "environments")
	info, err := os.Stat(envPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, nil
		}
		return nil, err
	}
	if !info.IsDir() {
		return nil, nil
	}
	entries, err := os.ReadDir(envPath)
	if err != nil {
		return nil, err
	}
	environments := []Environment{}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		path := filepath.Join(envPath, entry.Name())
		ext := strings.ToLower(filepath.Ext(path))
		switch ext {
		case ".bru":
			content, err := os.ReadFile(path)
			if err != nil {
				return nil, err
			}
			env := parseBruEnvironmentFile(strings.TrimSuffix(entry.Name(), ext), string(content))
			env.ID = deterministicID("global-env", filepath.ToSlash(path))
			environments = append(environments, env)
		case ".yml", ".yaml":
			env, err := parseYAMLEnvironmentFile(path)
			if err != nil {
				return nil, err
			}
			env.ID = deterministicID("global-env", filepath.ToSlash(path))
			environments = append(environments, env)
		}
	}
	sort.SliceStable(environments, func(i, j int) bool {
		return strings.ToLower(environments[i].Name) < strings.ToLower(environments[j].Name)
	})
	return environments, nil
}

func migrateWorkspaceActiveGlobalEnvironmentFromConfig(workspace *Workspace) (bool, error) {
	if workspace == nil || strings.TrimSpace(workspace.Path) == "" {
		return false, nil
	}
	configPath := filepath.Join(workspace.Path, "workspace.yml")
	data, err := os.ReadFile(configPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return false, nil
		}
		return false, err
	}
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return false, nil
	}
	root := yamlDocumentMappingRoot(&doc)
	legacyUID, ok := yamlMappingScalar(root, "activeEnvironmentUid")
	if !ok || strings.TrimSpace(legacyUID) == "" {
		return false, nil
	}
	if environmentID, ok, err := workspaceGlobalEnvironmentIDForBrunoUID(workspace.Path, strings.TrimSpace(legacyUID)); err != nil {
		return false, err
	} else if ok {
		workspace.ActiveGlobalEnvironmentID = environmentID
	}
	if yamlRemoveMappingKey(root, "activeEnvironmentUid") {
		updated, err := yaml.Marshal(&doc)
		if err != nil {
			return false, err
		}
		if err := os.WriteFile(configPath, updated, 0o600); err != nil {
			return false, err
		}
	}
	return true, nil
}

func workspaceGlobalEnvironmentIDForBrunoUID(workspacePath, uid string) (string, bool, error) {
	envPath := filepath.Join(workspacePath, "environments")
	entries, err := os.ReadDir(envPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return "", false, nil
		}
		return "", false, err
	}
	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		path := filepath.Join(envPath, entry.Name())
		ext := strings.ToLower(filepath.Ext(path))
		if ext != ".bru" && ext != ".yml" && ext != ".yaml" {
			continue
		}
		if brunoWorkspaceEnvironmentUIDForPath(path) == uid {
			return deterministicID("global-env", filepath.ToSlash(path)), true, nil
		}
	}
	return "", false, nil
}

func yamlDocumentMappingRoot(doc *yaml.Node) *yaml.Node {
	if doc == nil {
		return nil
	}
	root := doc
	if root.Kind == yaml.DocumentNode && len(root.Content) > 0 {
		root = root.Content[0]
	}
	if root.Kind != yaml.MappingNode {
		return nil
	}
	return root
}

func yamlMappingScalar(root *yaml.Node, key string) (string, bool) {
	if root == nil || root.Kind != yaml.MappingNode {
		return "", false
	}
	for index := 0; index+1 < len(root.Content); index += 2 {
		if root.Content[index].Value == key {
			return yamlScalarString(root.Content[index+1].Value), true
		}
	}
	return "", false
}

func yamlRemoveMappingKey(root *yaml.Node, key string) bool {
	if root == nil || root.Kind != yaml.MappingNode {
		return false
	}
	for index := 0; index+1 < len(root.Content); index += 2 {
		if root.Content[index].Value == key {
			root.Content = append(root.Content[:index], root.Content[index+2:]...)
			return true
		}
	}
	return false
}

func parseBruEnvironmentFile(name, content string) Environment {
	sections := parseBruSections(content)
	env := Environment{ID: newID("env"), Name: name, Color: parseBruTopLevelScalar(content, "color"), Variables: []Variable{}}
	if vars, ok := sections["vars"]; ok {
		env.Variables = parseBruVariables(vars, false)
	}
	if secrets, ok := sections["vars:secret"]; ok {
		env.Variables = mergeSecretVariables(env.Variables, parseBruVariables(secrets, true))
	}
	return env
}

func parseYAMLEnvironmentFile(path string) (Environment, error) {
	root, err := parseYAMLMapFile(path)
	if err != nil {
		return Environment{}, err
	}
	return environmentFromYAMLMap(root, strings.TrimSuffix(filepath.Base(path), filepath.Ext(path))), nil
}

func parseYAMLEnvironmentContent(content, fallbackName string) (Environment, error) {
	var root map[string]interface{}
	if err := yaml.Unmarshal([]byte(content), &root); err != nil {
		return Environment{}, err
	}
	return environmentFromYAMLMap(root, fallbackName), nil
}

func environmentFromYAMLMap(root map[string]interface{}, fallbackName string) Environment {
	name := strings.TrimSpace(yamlScalarString(root["name"]))
	if name == "" {
		name = strings.TrimSpace(fallbackName)
	}
	if name == "" {
		name = "Environment"
	}
	return Environment{
		ID:        newID("env"),
		Name:      name,
		Color:     yamlScalarString(root["color"]),
		Variables: parseYAMLVariables(root["variables"]),
	}
}

func stringifyBrunoEnvironmentExport(env Environment) (string, error) {
	info := newBrunoEnvironmentExportInfo()
	payload := brunoEnvironmentExportFromEnvironment(env)
	payload.Info = &info
	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func stringifyBrunoEnvironmentExportBundle(environments []Environment) (string, error) {
	payload := brunoEnvironmentExportBundle{
		Info:         newBrunoEnvironmentExportInfo(),
		Environments: make([]brunoEnvironmentExport, 0, len(environments)),
	}
	for _, env := range environments {
		payload.Environments = append(payload.Environments, brunoEnvironmentExportFromEnvironment(env))
	}
	data, err := json.MarshalIndent(payload, "", "  ")
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func brunoEnvironmentExportFiles(environments []Environment) ([]GlobalEnvironmentExportFile, error) {
	files := make([]GlobalEnvironmentExportFile, 0, len(environments))
	used := map[string]bool{}
	for _, env := range environments {
		baseName := brunoEnvironmentExportFileName(env.Name)
		fileBase := uniqueExportFileBaseName(baseName, used)
		content, err := stringifyBrunoEnvironmentExport(env)
		if err != nil {
			return nil, err
		}
		files = append(files, GlobalEnvironmentExportFile{Name: fileBase + ".json", Content: content})
	}
	return files, nil
}

func writeGlobalEnvironmentExportResult(result GlobalEnvironmentExportResult, targetPath string) ([]string, error) {
	targetPath = strings.TrimSpace(targetPath)
	if targetPath == "" {
		return nil, errors.New("export target path is required")
	}
	targetPath = filepath.Clean(targetPath)
	if result.Format == "folder" {
		if len(result.Files) == 0 {
			return nil, errors.New("folder export has no files")
		}
		if err := os.MkdirAll(targetPath, 0o755); err != nil {
			return nil, err
		}
		written := make([]string, 0, len(result.Files))
		for _, file := range result.Files {
			name := filepath.Base(strings.TrimSpace(file.Name))
			if name == "" || name == "." || name == string(filepath.Separator) {
				return nil, errors.New("folder export contains an invalid file name")
			}
			path := filepath.Join(targetPath, name)
			if err := os.WriteFile(path, []byte(file.Content), 0o600); err != nil {
				return nil, err
			}
			written = append(written, path)
		}
		return written, nil
	}
	if result.Content == "" {
		return nil, errors.New("global environment export content is empty")
	}
	if parent := filepath.Dir(targetPath); parent != "" && parent != "." {
		if err := os.MkdirAll(parent, 0o755); err != nil {
			return nil, err
		}
	}
	if err := os.WriteFile(targetPath, []byte(result.Content), 0o600); err != nil {
		return nil, err
	}
	return []string{targetPath}, nil
}

func expandUserExportPath(path string) (string, error) {
	path = strings.TrimSpace(path)
	if path == "" {
		return "", errors.New("export target path is required")
	}
	if path == "~" || strings.HasPrefix(path, "~/") || strings.HasPrefix(path, `~\`) {
		home, err := os.UserHomeDir()
		if err != nil || home == "" {
			return "", errors.New("home directory is unavailable")
		}
		if path == "~" {
			return home, nil
		}
		path = filepath.Join(home, strings.TrimLeft(path[1:], `/\`))
	}
	return filepath.Clean(path), nil
}

func (a *App) defaultSaveDialogDirectory() string {
	if a == nil || strings.TrimSpace(a.dataDir) == "" {
		return ""
	}
	info, err := os.Stat(a.dataDir)
	if err != nil || !info.IsDir() {
		return ""
	}
	return a.dataDir
}

func formatGlobalEnvironmentExportFiles(files []GlobalEnvironmentExportFile) string {
	manifest := map[string]interface{}{
		"folder": "bruno-global-environments",
		"files":  files,
	}
	data, _ := json.MarshalIndent(manifest, "", "  ")
	return string(data)
}

func newBrunoEnvironmentExportInfo() brunoEnvironmentExportInfo {
	return brunoEnvironmentExportInfo{
		Type:          "bruno-environment",
		ExportedAt:    time.Now().UTC().Format(time.RFC3339Nano),
		ExportedUsing: "Bruno/v2.0.0",
	}
}

func brunoEnvironmentExportFromEnvironment(env Environment) brunoEnvironmentExport {
	payload := brunoEnvironmentExport{
		Name:      env.Name,
		Variables: make([]brunoEnvironmentVariable, 0, len(env.Variables)),
		Color:     env.Color,
	}
	for _, variable := range env.Variables {
		dataType := firstNonEmpty(variable.DataType, variable.Type, "string")
		value := variable.Value
		if variable.Secret {
			value = ""
		}
		exported := brunoEnvironmentVariable{
			Name:    variable.Name,
			Value:   value,
			Type:    "text",
			Enabled: variable.Enabled,
			Secret:  variable.Secret,
		}
		if dataType != "" && dataType != "string" && dataType != "text" {
			exported.DataType = dataType
		}
		payload.Variables = append(payload.Variables, exported)
	}
	return payload
}

func selectedGlobalEnvironments(workspace Workspace, environmentIDs []string) ([]Environment, error) {
	if len(environmentIDs) == 0 {
		return append([]Environment(nil), workspace.GlobalEnvironments...), nil
	}
	byID := map[string]Environment{}
	for _, env := range workspace.GlobalEnvironments {
		byID[env.ID] = env
	}
	environments := make([]Environment, 0, len(environmentIDs))
	for _, id := range environmentIDs {
		env, ok := byID[id]
		if !ok {
			return nil, fmt.Errorf("global environment %s not found", id)
		}
		environments = append(environments, env)
	}
	return environments, nil
}

func brunoEnvironmentExportFileName(name string) string {
	name = strings.Trim(brunoExportFilenamePattern.ReplaceAllString(name, "_"), "_")
	if name == "" {
		return "environment"
	}
	return name
}

func uniqueExportFileBaseName(baseName string, used map[string]bool) string {
	if used == nil {
		used = map[string]bool{}
	}
	if !used[baseName] {
		used[baseName] = true
		return baseName
	}
	for counter := 1; ; counter++ {
		candidate := fmt.Sprintf("%s copy", baseName)
		if counter > 1 {
			candidate = fmt.Sprintf("%s copy %d", baseName, counter)
		}
		if !used[candidate] {
			used[candidate] = true
			return candidate
		}
	}
}

func parseImportedGlobalEnvironments(content string) ([]Environment, error) {
	trimmed := strings.TrimSpace(content)
	if trimmed == "" {
		return nil, errors.New("environment import content is empty")
	}
	var raw interface{}
	decoder := json.NewDecoder(strings.NewReader(trimmed))
	decoder.UseNumber()
	if err := decoder.Decode(&raw); err == nil {
		if decoder.Decode(&struct{}{}) != io.EOF {
			return nil, errors.New("environment import JSON contains trailing content")
		}
		return parseImportedGlobalEnvironmentsJSON(raw)
	} else if strings.HasPrefix(trimmed, "{") || strings.HasPrefix(trimmed, "[") {
		return nil, fmt.Errorf("invalid environment JSON: %w", err)
	}
	env, err := parseYAMLEnvironmentContent(content, "Imported Environment")
	if err != nil {
		return nil, err
	}
	return []Environment{env}, nil
}

func parseImportedGlobalEnvironmentsJSON(raw interface{}) ([]Environment, error) {
	if root, ok := mapValue(raw); ok {
		if _, hasID := root["id"]; hasID {
			if _, hasValues := root["values"]; hasValues {
				return []Environment{postmanEnvironmentFromJSONMap(root)}, nil
			}
		}
		if values, ok := listValue(root["environments"]); ok {
			return brunoEnvironmentsFromJSONList(values)
		}
		env, err := brunoEnvironmentFromJSONMap(root)
		if err != nil {
			return nil, err
		}
		return []Environment{env}, nil
	}
	if values, ok := listValue(raw); ok {
		return brunoEnvironmentsFromJSONList(values)
	}
	return nil, errors.New("invalid environment import: expected an object or array")
}

func brunoEnvironmentsFromJSONList(values []interface{}) ([]Environment, error) {
	environments := make([]Environment, 0, len(values))
	for index, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			return nil, fmt.Errorf("invalid environment at index %d: expected an object", index)
		}
		env, err := brunoEnvironmentFromJSONMap(valueMap)
		if err != nil {
			return nil, fmt.Errorf("invalid environment at index %d: %w", index, err)
		}
		environments = append(environments, env)
	}
	return environments, nil
}

func brunoEnvironmentFromJSONMap(root map[string]interface{}) (Environment, error) {
	variableValues, ok := listValue(root["variables"])
	if !ok {
		return Environment{}, errors.New("missing or invalid variables array")
	}
	name := strings.TrimSpace(yamlScalarString(root["name"]))
	if name == "" {
		name = "Imported Environment"
	}
	env := Environment{
		ID:        newID("env"),
		Name:      name,
		Color:     yamlScalarString(root["color"]),
		Variables: make([]Variable, 0, len(variableValues)),
	}
	for index, entry := range variableValues {
		valueMap, ok := mapValue(entry)
		if !ok {
			return Environment{}, fmt.Errorf("invalid variable at index %d: expected an object", index)
		}
		name := strings.TrimSpace(yamlScalarString(valueMap["name"]))
		if name == "" {
			return Environment{}, fmt.Errorf("invalid variable at index %d: missing or invalid name", index)
		}
		env.Variables = append(env.Variables, brunoVariableFromJSONMap(valueMap, true))
	}
	return env, nil
}

func postmanEnvironmentFromJSONMap(root map[string]interface{}) Environment {
	name := strings.TrimSpace(yamlScalarString(root["name"]))
	if name == "" {
		name = "Imported Environment"
	}
	values, _ := listValue(root["values"])
	env := Environment{ID: newID("env"), Name: name, Variables: make([]Variable, 0, len(values))}
	for _, entry := range values {
		valueMap, ok := mapValue(entry)
		if !ok {
			continue
		}
		if valueMap["key"] == nil && valueMap["value"] == nil {
			continue
		}
		name := invalidPostmanVariableCharacterPattern.ReplaceAllString(yamlScalarString(valueMap["key"]), "_")
		if name == "" {
			continue
		}
		secret := strings.EqualFold(strings.TrimSpace(yamlScalarString(valueMap["type"])), "secret")
		env.Variables = append(env.Variables, Variable{
			ID:       newID("var"),
			Name:     name,
			Value:    importedEnvironmentVariableValue(valueMap["value"], "string"),
			Type:     "string",
			DataType: "string",
			Enabled:  boolValue(valueMap["enabled"], true),
			Secret:   secret,
		})
	}
	return env
}

func brunoVariableFromJSONMap(root map[string]interface{}, blankSecret bool) Variable {
	secret := boolValue(root["secret"], false)
	dataType := strings.ToLower(strings.TrimSpace(yamlScalarString(root["dataType"])))
	if dataType == "" || dataType == "text" {
		dataType = "string"
	}
	value := importedEnvironmentVariableValue(root["value"], dataType)
	if secret && blankSecret {
		value = ""
	}
	return Variable{
		ID:       newID("var"),
		Name:     strings.TrimSpace(yamlScalarString(root["name"])),
		Value:    value,
		Type:     dataType,
		DataType: dataType,
		Enabled:  boolValue(root["enabled"], true),
		Secret:   secret,
	}
}

func importedEnvironmentVariableValue(raw interface{}, dataType string) interface{} {
	if raw == nil {
		return ""
	}
	switch value := raw.(type) {
	case json.Number:
		if strings.EqualFold(dataType, "number") {
			if strings.ContainsAny(value.String(), ".eE") {
				if parsed, err := value.Float64(); err == nil {
					return parsed
				}
			}
			if parsed, err := value.Int64(); err == nil {
				return parsed
			}
		}
		return value.String()
	case string:
		switch dataType {
		case "number":
			if strings.ContainsAny(value, ".eE") {
				if parsed, err := strconv.ParseFloat(value, 64); err == nil {
					return parsed
				}
			}
			if parsed, err := strconv.Atoi(value); err == nil {
				return parsed
			}
		case "boolean":
			if parsed, err := strconv.ParseBool(value); err == nil {
				return parsed
			}
		}
		return value
	default:
		return value
	}
}

func stringifyYAMLEnvironment(env Environment) string {
	env = scrubEnvironmentSecretValues([]Environment{env})[0]
	root := map[string]interface{}{
		"name":      env.Name,
		"variables": yamlVariables(env.Variables),
	}
	if strings.TrimSpace(env.Color) != "" {
		root["color"] = env.Color
	}
	data, _ := yaml.Marshal(root)
	return string(data)
}

func mergeSecretVariables(existing, secrets []Variable) []Variable {
	byName := map[string]int{}
	for i, variable := range existing {
		byName[variable.Name] = i
	}
	for _, secret := range secrets {
		if index, ok := byName[secret.Name]; ok {
			existing[index].Secret = true
			if secret.DataType != "" && secret.DataType != "string" {
				existing[index].DataType = secret.DataType
				existing[index].Type = secret.Type
			}
			continue
		}
		existing = append(existing, secret)
	}
	return existing
}

func mergeEnvironments(existing, loaded []Environment) []Environment {
	byName := map[string]int{}
	for i, env := range existing {
		byName[strings.ToLower(env.Name)] = i
	}
	for _, env := range loaded {
		key := strings.ToLower(env.Name)
		if index, ok := byName[key]; ok {
			if existing[index].ID != "" {
				env.ID = existing[index].ID
			}
			existing[index] = env
			continue
		}
		existing = append(existing, env)
	}
	sort.SliceStable(existing, func(i, j int) bool {
		return strings.ToLower(existing[i].Name) < strings.ToLower(existing[j].Name)
	})
	return existing
}

func stringifyBruCollection(collection Collection) string {
	var b strings.Builder
	if len(collection.Headers) > 0 {
		writeBruKeyValues(&b, "headers", collection.Headers)
	}
	writeBruAuth(&b, collection.Auth, false)
	if len(collection.Variables) > 0 {
		writeBruVariables(&b, "vars:pre-request", collection.Variables, false)
	}
	if len(collection.ResVariables) > 0 {
		writeBruVariables(&b, "vars:post-response", collection.ResVariables, false)
	}
	writeBruBlock(&b, "script:pre-request", collection.PreScript)
	writeBruBlock(&b, "script:post-response", collection.PostScript)
	writeBruBlock(&b, "tests", collection.Tests)
	writeBruBlock(&b, "docs", collection.Docs)
	return b.String()
}

func stringifyBruFolder(folder FolderConfig) string {
	var b strings.Builder
	b.WriteString("meta {\n")
	fmt.Fprintf(&b, "  name: %s\n", firstNonEmpty(folder.Name, filepath.Base(filepath.FromSlash(folder.Path))))
	if folder.Seq > 0 {
		fmt.Fprintf(&b, "  seq: %d\n", folder.Seq)
	}
	b.WriteString("}\n")
	if len(folder.Headers) > 0 {
		writeBruKeyValues(&b, "headers", folder.Headers)
	}
	if folder.Auth.Mode != "" {
		writeBruAuth(&b, folder.Auth, true)
	}
	if len(folder.Variables) > 0 {
		writeBruVariables(&b, "vars:pre-request", folder.Variables, false)
	}
	if len(folder.ResVariables) > 0 {
		writeBruVariables(&b, "vars:post-response", folder.ResVariables, false)
	}
	writeBruBlock(&b, "script:pre-request", folder.PreScript)
	writeBruBlock(&b, "script:post-response", folder.PostScript)
	writeBruBlock(&b, "tests", folder.Tests)
	writeBruBlock(&b, "docs", folder.Docs)
	return b.String()
}

func stringifyBruEnvironment(env Environment) string {
	var b strings.Builder
	if strings.TrimSpace(env.Color) != "" {
		fmt.Fprintf(&b, "color: %s\n\n", env.Color)
	}
	plain := []Variable{}
	secrets := []Variable{}
	for _, variable := range env.Variables {
		if variable.Secret {
			secrets = append(secrets, variable)
		} else {
			plain = append(plain, variable)
		}
	}
	if len(plain) > 0 {
		writeBruVariables(&b, "vars", plain, false)
	}
	if len(secrets) > 0 {
		writeBruVariables(&b, "vars:secret", secrets, true)
	}
	return b.String()
}

func writeBruKeyValues(b *strings.Builder, section string, values []KeyValue) {
	if len(values) == 0 {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	fmt.Fprintf(b, "%s {\n", section)
	for _, value := range values {
		prefix := ""
		if !value.Enabled {
			prefix = "~"
		}
		fmt.Fprintf(b, "  %s%s: %s\n", prefix, value.Name, value.Value)
	}
	b.WriteString("}\n")
}

func writeBruMultipartValues(b *strings.Builder, section string, values []FormPart) {
	if len(values) == 0 {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	fmt.Fprintf(b, "%s {\n", section)
	for _, value := range values {
		prefix := ""
		if !value.Enabled {
			prefix = "~"
		}
		rendered := value.Value
		if strings.TrimSpace(value.FilePath) != "" {
			rendered = "@file(" + value.FilePath + ")"
		}
		if strings.TrimSpace(value.ContentType) != "" {
			rendered = strings.TrimSpace(rendered + " @contentType(" + value.ContentType + ")")
		}
		fmt.Fprintf(b, "  %s%s: %s\n", prefix, value.Name, rendered)
	}
	b.WriteString("}\n")
}

func writeBruFileBody(b *strings.Builder, body RequestBody) {
	entries := fileBodyEntries(body)
	if len(entries) == 0 {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	b.WriteString("body:file {\n")
	write := func(selected bool) {
		for _, file := range entries {
			if file.Selected != selected {
				continue
			}
			if strings.TrimSpace(file.FilePath) == "" && strings.TrimSpace(file.ContentType) == "" {
				continue
			}
			prefix := ""
			if !file.Selected {
				prefix = "~"
			}
			rendered := "@file(" + file.FilePath + ")"
			if strings.TrimSpace(file.ContentType) != "" {
				rendered += " @contentType(" + file.ContentType + ")"
			}
			fmt.Fprintf(b, "  %sfile: %s\n", prefix, rendered)
		}
	}
	write(true)
	write(false)
	b.WriteString("}\n")
}

func writeBruVariables(b *strings.Builder, section string, values []Variable, secret bool) {
	if len(values) == 0 {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	closeToken := "}"
	if secret {
		closeToken = "]"
		fmt.Fprintf(b, "%s [\n", section)
	} else {
		fmt.Fprintf(b, "%s {\n", section)
	}
	for _, variable := range values {
		dataType := firstNonEmpty(variable.DataType, variable.Type, "string")
		if dataType != "string" {
			fmt.Fprintf(b, "  @%s\n", dataType)
		}
		prefix := ""
		if !variable.Enabled {
			prefix = "~"
		}
		if secret {
			fmt.Fprintf(b, "  %s%s\n", prefix, variable.Name)
			continue
		}
		fmt.Fprintf(b, "  %s%s: %s\n", prefix, variable.Name, bruScalarString(variable.Value))
	}
	fmt.Fprintf(b, "%s\n", closeToken)
}

func writeBruAuth(b *strings.Builder, auth AuthConfig, includeNone bool) {
	mode := auth.Mode
	if mode == "" {
		mode = "none"
	}
	if mode == "none" && !includeNone {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	b.WriteString("auth {\n")
	fmt.Fprintf(b, "  mode: %s\n", mode)
	b.WriteString("}\n")
	switch mode {
	case "basic":
		b.WriteString("\nauth:basic {\n")
		fmt.Fprintf(b, "  username: %s\n", auth.Username)
		fmt.Fprintf(b, "  password: %s\n", auth.Password)
		b.WriteString("}\n")
	case "digest":
		b.WriteString("\nauth:digest {\n")
		fmt.Fprintf(b, "  username: %s\n", auth.Username)
		fmt.Fprintf(b, "  password: %s\n", auth.Password)
		b.WriteString("}\n")
	case "wsse":
		b.WriteString("\nauth:wsse {\n")
		fmt.Fprintf(b, "  username: %s\n", auth.Username)
		fmt.Fprintf(b, "  password: %s\n", auth.Password)
		b.WriteString("}\n")
	case "ntlm":
		b.WriteString("\nauth:ntlm {\n")
		fmt.Fprintf(b, "  username: %s\n", auth.Username)
		fmt.Fprintf(b, "  password: %s\n", auth.Password)
		fmt.Fprintf(b, "  domain: %s\n", auth.Domain)
		b.WriteString("}\n")
	case "bearer":
		b.WriteString("\nauth:bearer {\n")
		fmt.Fprintf(b, "  token: %s\n", auth.Token)
		b.WriteString("}\n")
	case "apikey":
		b.WriteString("\nauth:apikey {\n")
		fmt.Fprintf(b, "  key: %s\n", auth.APIKey)
		fmt.Fprintf(b, "  value: %s\n", auth.APIValue)
		fmt.Fprintf(b, "  placement: %s\n", firstNonEmpty(auth.APILocation, "header"))
		b.WriteString("}\n")
	case "awsv4":
		b.WriteString("\nauth:awsv4 {\n")
		fmt.Fprintf(b, "  accessKeyId: %s\n", firstNonEmpty(auth.AWSV4.AccessKeyID, auth.AWSV4.AccessKey))
		fmt.Fprintf(b, "  secretAccessKey: %s\n", firstNonEmpty(auth.AWSV4.SecretAccessKey, auth.AWSV4.SecretKey))
		fmt.Fprintf(b, "  sessionToken: %s\n", auth.AWSV4.SessionToken)
		fmt.Fprintf(b, "  service: %s\n", auth.AWSV4.Service)
		fmt.Fprintf(b, "  region: %s\n", auth.AWSV4.Region)
		fmt.Fprintf(b, "  profileName: %s\n", auth.AWSV4.ProfileName)
		b.WriteString("}\n")
	case "oauth1":
		b.WriteString("\nauth:oauth1 {\n")
		fmt.Fprintf(b, "  consumer_key: %s\n", auth.OAuth1.ConsumerKey)
		fmt.Fprintf(b, "  consumer_secret: %s\n", auth.OAuth1.ConsumerSecret)
		fmt.Fprintf(b, "  access_token: %s\n", auth.OAuth1.AccessToken)
		fmt.Fprintf(b, "  token_secret: %s\n", auth.OAuth1.AccessTokenSecret)
		fmt.Fprintf(b, "  callback_url: %s\n", auth.OAuth1.CallbackURL)
		fmt.Fprintf(b, "  verifier: %s\n", auth.OAuth1.Verifier)
		fmt.Fprintf(b, "  signature_method: %s\n", firstNonEmpty(auth.OAuth1.SignatureMethod, "HMAC-SHA1"))
		fmt.Fprintf(b, "  private_key: %s\n", oauth1PrivateKeyBruValue(auth.OAuth1))
		fmt.Fprintf(b, "  timestamp: %s\n", auth.OAuth1.Timestamp)
		fmt.Fprintf(b, "  nonce: %s\n", auth.OAuth1.Nonce)
		fmt.Fprintf(b, "  version: %s\n", firstNonEmpty(auth.OAuth1.Version, "1.0"))
		fmt.Fprintf(b, "  realm: %s\n", auth.OAuth1.Realm)
		fmt.Fprintf(b, "  placement: %s\n", firstNonEmpty(auth.OAuth1.Placement, "header"))
		fmt.Fprintf(b, "  include_body_hash: %s\n", strconv.FormatBool(auth.OAuth1.IncludeBodyHash))
		b.WriteString("}\n")
	case "oauth2":
		b.WriteString("\nauth:oauth2 {\n")
		fmt.Fprintf(b, "  grant_type: %s\n", auth.OAuth2.GrantType)
		fmt.Fprintf(b, "  callback_url: %s\n", auth.OAuth2.CallbackURL)
		fmt.Fprintf(b, "  authorization_url: %s\n", auth.OAuth2.AuthorizationURL)
		fmt.Fprintf(b, "  access_token_url: %s\n", auth.OAuth2.AccessTokenURL)
		fmt.Fprintf(b, "  refresh_token_url: %s\n", auth.OAuth2.RefreshTokenURL)
		fmt.Fprintf(b, "  username: %s\n", auth.OAuth2.Username)
		fmt.Fprintf(b, "  password: %s\n", auth.OAuth2.Password)
		fmt.Fprintf(b, "  client_id: %s\n", auth.OAuth2.ClientID)
		fmt.Fprintf(b, "  client_secret: %s\n", auth.OAuth2.ClientSecret)
		fmt.Fprintf(b, "  scope: %s\n", auth.OAuth2.Scope)
		fmt.Fprintf(b, "  state: %s\n", auth.OAuth2.State)
		fmt.Fprintf(b, "  pkce: %s\n", strconv.FormatBool(auth.OAuth2.PKCE))
		fmt.Fprintf(b, "  credentials_placement: %s\n", firstNonEmpty(auth.OAuth2.CredentialsPlacement, "basic_auth_header"))
		fmt.Fprintf(b, "  credentials_id: %s\n", firstNonEmpty(auth.OAuth2.CredentialsID, "credentials"))
		fmt.Fprintf(b, "  token_source: %s\n", firstNonEmpty(auth.OAuth2.TokenSource, "access_token"))
		fmt.Fprintf(b, "  token_placement: %s\n", firstNonEmpty(auth.OAuth2.TokenPlacement, "header"))
		fmt.Fprintf(b, "  token_header_prefix: %s\n", firstNonEmpty(auth.OAuth2.TokenHeaderPrefix, "Bearer"))
		fmt.Fprintf(b, "  token_query_key: %s\n", firstNonEmpty(auth.OAuth2.TokenQueryKey, "access_token"))
		fmt.Fprintf(b, "  auto_fetch_token: %s\n", strconv.FormatBool(true))
		fmt.Fprintf(b, "  auto_refresh_token: %s\n", strconv.FormatBool(auth.OAuth2.AutoRefreshToken))
		if auth.Token != "" {
			fmt.Fprintf(b, "  access_token: %s\n", auth.Token)
		}
		b.WriteString("}\n")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:auth_req:headers", auth.OAuth2.AuthorizationAdditionalParams, "headers")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:auth_req:queryparams", auth.OAuth2.AuthorizationAdditionalParams, "queryparams")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:access_token_req:headers", auth.OAuth2.TokenAdditionalParams, "headers")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:access_token_req:queryparams", auth.OAuth2.TokenAdditionalParams, "queryparams")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:access_token_req:body", auth.OAuth2.TokenAdditionalParams, "body")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:refresh_token_req:headers", auth.OAuth2.RefreshAdditionalParams, "headers")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:refresh_token_req:queryparams", auth.OAuth2.RefreshAdditionalParams, "queryparams")
		writeBruOAuth2AdditionalParams(b, "auth:oauth2:additional_params:refresh_token_req:body", auth.OAuth2.RefreshAdditionalParams, "body")
	}
}

func writeBruOAuth2AdditionalParams(b *strings.Builder, section string, params []OAuth2AdditionalParam, sendIn string) {
	writeBruKeyValues(b, section, oauth2KeyValuesFromAdditionalParams(params, sendIn))
}

func writeBruBlock(b *strings.Builder, section, content string) {
	content = strings.TrimRight(content, "\n")
	if strings.TrimSpace(content) == "" {
		return
	}
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	fmt.Fprintf(b, "%s {\n", section)
	for _, line := range strings.Split(content, "\n") {
		fmt.Fprintf(b, "  %s\n", line)
	}
	b.WriteString("}\n")
}

func writeBruGrpcMessages(b *strings.Builder, messages []GrpcMessage) {
	for _, message := range messages {
		if strings.TrimSpace(message.Name) == "" && strings.TrimSpace(message.Content) == "" {
			continue
		}
		if b.Len() > 0 {
			b.WriteString("\n")
		}
		b.WriteString("body:grpc {\n")
		if strings.TrimSpace(message.Name) != "" {
			fmt.Fprintf(b, "  name: %s\n", message.Name)
		}
		fmt.Fprintf(b, "  content: %s\n", bruScalarString(message.Content))
		b.WriteString("}\n")
	}
}

func writeBruWSMessages(b *strings.Builder, messages []WSMessage) {
	for _, message := range messages {
		if strings.TrimSpace(message.Name) == "" && strings.TrimSpace(message.Content) == "" {
			continue
		}
		if b.Len() > 0 {
			b.WriteString("\n")
		}
		b.WriteString("body:ws {\n")
		if strings.TrimSpace(message.Name) != "" {
			fmt.Fprintf(b, "  name: %s\n", message.Name)
		}
		fmt.Fprintf(b, "  type: %s\n", normalizeWSMessageType(message.Type))
		if message.Selected {
			b.WriteString("  selected: true\n")
		}
		fmt.Fprintf(b, "  content: %s\n", bruScalarString(message.Content))
		b.WriteString("}\n")
	}
}

func bruScalarString(value interface{}) string {
	switch v := value.(type) {
	case nil:
		return ""
	case string:
		if strings.Contains(v, "\n") {
			return "'''\n    " + strings.ReplaceAll(v, "\n", "\n    ") + "\n  '''"
		}
		return v
	case bool:
		return strconv.FormatBool(v)
	case int:
		return strconv.Itoa(v)
	case int64:
		return strconv.FormatInt(v, 10)
	case float64:
		return strconv.FormatFloat(v, 'f', -1, 64)
	default:
		return fmt.Sprint(v)
	}
}

func parseBruTopLevelScalar(content, key string) string {
	prefix := key + ":"
	for _, line := range strings.Split(content, "\n") {
		if strings.TrimLeft(line, " \t") != line {
			continue
		}
		trimmed := strings.TrimSpace(line)
		if strings.HasSuffix(trimmed, "{") || strings.HasSuffix(trimmed, "[") {
			return ""
		}
		if value, ok := strings.CutPrefix(trimmed, prefix); ok {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

func stringifyBru(item RequestItem) string {
	var b strings.Builder
	fmt.Fprintf(&b, "meta {\n  name: %s\n  type: %s\n  seq: %d\n}\n\n", item.Name, item.Type, item.Seq)
	if item.Type == "grpc" {
		b.WriteString("grpc {\n")
		fmt.Fprintf(&b, "  url: %s\n", item.URL)
		if strings.TrimSpace(item.Method) != "" {
			fmt.Fprintf(&b, "  method: %s\n", item.Method)
		}
		fmt.Fprintf(&b, "  body: %s\n", firstNonEmpty(item.Body.Mode, "grpc"))
		fmt.Fprintf(&b, "  auth: %s\n", firstNonEmpty(item.Auth.Mode, "none"))
		if strings.TrimSpace(item.GrpcMethodType) != "" {
			fmt.Fprintf(&b, "  methodType: %s\n", item.GrpcMethodType)
		}
		if strings.TrimSpace(item.ProtoPath) != "" {
			fmt.Fprintf(&b, "  protoPath: %s\n", item.ProtoPath)
		}
		b.WriteString("}\n")
		writeBruAuth(&b, item.Auth, false)
		writeBruKeyValues(&b, "metadata", item.Headers)
		writeBruGrpcMessages(&b, item.GrpcMessages)
		writeBruRequestTail(&b, item)
		return b.String()
	}
	if item.Type == "websocket" {
		b.WriteString("ws {\n")
		fmt.Fprintf(&b, "  url: %s\n", item.URL)
		fmt.Fprintf(&b, "  body: %s\n", firstNonEmpty(item.Body.Mode, "ws"))
		fmt.Fprintf(&b, "  auth: %s\n", firstNonEmpty(item.Auth.Mode, "none"))
		b.WriteString("}\n")
		writeBruAuth(&b, item.Auth, false)
		writeBruKeyValues(&b, "headers", item.Headers)
		writeBruKeyValues(&b, "params:query", item.Params)
		writeBruKeyValues(&b, "params:path", item.PathParams)
		writeBruWSMessages(&b, wsMessagesForStorage(item))
		writeBruRequestTail(&b, item)
		return b.String()
	}
	method := strings.ToLower(item.Method)
	if method == "" {
		method = "get"
	}
	fmt.Fprintf(&b, "%s {\n  url: %s\n  body: %s\n  auth: %s\n}\n", method, item.URL, item.Body.Mode, item.Auth.Mode)
	writeBruAuth(&b, item.Auth, false)
	if len(item.Headers) > 0 {
		b.WriteString("\nheaders {\n")
		for _, header := range item.Headers {
			if header.Enabled {
				fmt.Fprintf(&b, "  %s: %s\n", header.Name, header.Value)
			}
		}
		b.WriteString("}\n")
	}
	if len(item.Params) > 0 {
		b.WriteString("\nparams:query {\n")
		for _, param := range item.Params {
			if param.Enabled {
				fmt.Fprintf(&b, "  %s: %s\n", param.Name, param.Value)
			}
		}
		b.WriteString("}\n")
	}
	if len(item.PathParams) > 0 {
		b.WriteString("\nparams:path {\n")
		for _, param := range item.PathParams {
			if param.Enabled {
				fmt.Fprintf(&b, "  %s: %s\n", param.Name, param.Value)
			}
		}
		b.WriteString("}\n")
	}
	if item.Body.Mode == "json" && strings.TrimSpace(item.Body.JSON) != "" {
		b.WriteString("\nbody:json {\n")
		for _, line := range strings.Split(strings.TrimRight(item.Body.JSON, "\n"), "\n") {
			b.WriteString("  " + line + "\n")
		}
		b.WriteString("}\n")
	}
	if item.Body.Mode == "formUrlEncoded" {
		writeBruKeyValues(&b, "body:form-urlencoded", item.Body.FormURLEncoded)
	}
	if item.Body.Mode == "multipartForm" {
		writeBruMultipartValues(&b, "body:multipart-form", item.Body.Multipart)
	}
	if item.Body.Mode == "file" {
		writeBruFileBody(&b, item.Body)
	}
	writeBruRequestTail(&b, item)
	return b.String()
}

func writeBruRequestTail(b *strings.Builder, item RequestItem) {
	writeBruVariables(b, "vars:pre-request", item.Vars.Req, false)
	writeBruVariables(b, "vars:post-response", item.Vars.Res, false)
	writeBruBlock(b, "script:pre-request", item.PreScript)
	writeBruBlock(b, "script:post-response", item.PostScript)
	writeBruBlock(b, "tests", item.Tests)
	writeBruBlock(b, "docs", item.Docs)
	writeBruSettings(b, item.Settings)
	for _, example := range item.Examples {
		writeBruExample(b, example)
	}
}

func writeBruSettings(b *strings.Builder, settings RequestSettings) {
	b.WriteString("\nsettings {\n")
	fmt.Fprintf(b, "  encodeUrl: %t\n", settings.EncodeURL)
	fmt.Fprintf(b, "  timeout: %d\n", settings.TimeoutMs)
	fmt.Fprintf(b, "  followRedirects: %t\n", settings.FollowRedirects)
	fmt.Fprintf(b, "  maxRedirects: %d\n", settings.MaxRedirects)
	fmt.Fprintf(b, "  storeCookies: %t\n", settings.StoreCookies)
	fmt.Fprintf(b, "  verifyTls: %t\n", settings.VerifyTLS)
	fmt.Fprintf(b, "  keepAliveInterval: %d\n", settings.KeepAliveInterval)
	b.WriteString("}\n")
}

func writeBruExample(b *strings.Builder, example ResponseExample) {
	if b.Len() > 0 {
		b.WriteString("\n")
	}
	name := strings.TrimSpace(example.Name)
	if name == "" {
		name = "Example"
	}
	b.WriteString("example {\n")
	fmt.Fprintf(b, "  name: %s\n", name)
	if strings.TrimSpace(example.Description) != "" {
		fmt.Fprintf(b, "  description: %s\n", example.Description)
	}
	b.WriteString("\n")
	b.WriteString("  request: {\n")
	if strings.TrimSpace(example.Request.URL) != "" {
		fmt.Fprintf(b, "    url: %s\n", example.Request.URL)
	}
	if strings.TrimSpace(example.Request.Method) != "" {
		fmt.Fprintf(b, "    method: %s\n", strings.ToLower(example.Request.Method))
	}
	requestBodyMode := normalizeBruBodyMode(firstNonEmpty(example.Request.BodyMode, "none"))
	fmt.Fprintf(b, "    mode: %s\n", requestBodyMode)
	writeIndentedKeyValues(b, "headers", example.Request.Headers, "    ")
	writeIndentedKeyValues(b, "params", example.Request.Params, "    ")
	if requestBodyMode == "formUrlEncoded" && len(example.Request.FormURLEncoded) > 0 {
		writeIndentedKeyValues(b, "body:form-urlencoded", example.Request.FormURLEncoded, "    ")
	} else if requestBodyMode == "multipartForm" && len(example.Request.MultipartForm) > 0 {
		writeIndentedMultipartValues(b, "body:multipart-form", example.Request.MultipartForm, "    ")
	} else if requestBodyMode == "file" && len(example.Request.File) > 0 {
		writeIndentedFileBody(b, "body:file", example.Request.File, "    ")
	} else {
		writeExampleContentBlock(b, "body", firstNonEmpty(requestBodyMode, "text"), example.Request.Body, "    ")
	}
	b.WriteString("  }\n\n")
	b.WriteString("  response: {\n")
	b.WriteString("    status: {\n")
	fmt.Fprintf(b, "      code: %d\n", example.Response.Status)
	if strings.TrimSpace(example.Response.StatusText) != "" {
		fmt.Fprintf(b, "      text: %s\n", example.Response.StatusText)
	}
	b.WriteString("    }\n")
	writeIndentedKeyValues(b, "headers", example.Response.Headers, "    ")
	if example.Response.DurationMs > 0 {
		fmt.Fprintf(b, "    duration: %d\n", example.Response.DurationMs)
	}
	writeExampleContentBlock(b, "body", firstNonEmpty(example.Response.BodyType, "text"), example.Response.Body, "    ")
	b.WriteString("  }\n")
	b.WriteString("}\n")
}

func writeIndentedKeyValues(b *strings.Builder, section string, values []KeyValue, indent string) {
	if len(values) == 0 {
		return
	}
	fmt.Fprintf(b, "%s%s: {\n", indent, section)
	for _, value := range values {
		if value.Name == "" {
			continue
		}
		prefix := ""
		if !value.Enabled {
			prefix = "~"
		}
		fmt.Fprintf(b, "%s  %s%s: %s\n", indent, prefix, value.Name, value.Value)
	}
	fmt.Fprintf(b, "%s}\n", indent)
}

func writeIndentedMultipartValues(b *strings.Builder, section string, values []FormPart, indent string) {
	if len(values) == 0 {
		return
	}
	fmt.Fprintf(b, "%s%s: {\n", indent, section)
	for _, value := range values {
		if strings.TrimSpace(value.Name) == "" {
			continue
		}
		prefix := ""
		if !value.Enabled {
			prefix = "~"
		}
		rendered := value.Value
		if strings.TrimSpace(value.FilePath) != "" {
			rendered = "@file(" + value.FilePath + ")"
		}
		if strings.TrimSpace(value.ContentType) != "" {
			rendered = strings.TrimSpace(rendered + " @contentType(" + value.ContentType + ")")
		}
		fmt.Fprintf(b, "%s  %s%s: %s\n", indent, prefix, value.Name, rendered)
	}
	fmt.Fprintf(b, "%s}\n", indent)
}

func writeIndentedFileBody(b *strings.Builder, section string, values []FileBodyEntry, indent string) {
	if len(values) == 0 {
		return
	}
	fmt.Fprintf(b, "%s%s: {\n", indent, section)
	write := func(selected bool) {
		for _, file := range values {
			if file.Selected != selected {
				continue
			}
			if strings.TrimSpace(file.FilePath) == "" && strings.TrimSpace(file.ContentType) == "" {
				continue
			}
			prefix := ""
			if !file.Selected {
				prefix = "~"
			}
			rendered := "@file(" + file.FilePath + ")"
			if strings.TrimSpace(file.ContentType) != "" {
				rendered += " @contentType(" + file.ContentType + ")"
			}
			fmt.Fprintf(b, "%s  %sfile: %s\n", indent, prefix, rendered)
		}
	}
	write(true)
	write(false)
	fmt.Fprintf(b, "%s}\n", indent)
}

func writeExampleContentBlock(b *strings.Builder, section, bodyType, body, indent string) {
	if strings.TrimSpace(body) == "" {
		return
	}
	fmt.Fprintf(b, "%s%s: {\n", indent, section)
	fmt.Fprintf(b, "%s  type: %s\n", indent, bodyType)
	fmt.Fprintf(b, "%s  content: '''\n", indent)
	for _, line := range strings.Split(strings.TrimRight(body, "\n"), "\n") {
		fmt.Fprintf(b, "%s    %s\n", indent, line)
	}
	fmt.Fprintf(b, "%s  '''\n", indent)
	fmt.Fprintf(b, "%s}\n", indent)
}

